window.CARDS=window.CARDS||{};CARDS["people-nanase-tsubasa"]=[{"i":"sc-nanase-tsubasa-y2v1-p7-1","v":"y2v1","y":2,"o":16,"k":"","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa prologue  briefed by tsukishiro in a tokyo facility  nanase  unnamed  listens as tsukishiro briefs her on ayanokoji kiyotaka  shows signs of dissatisfaction that ayanokoji is praised as the white room s masterpiece  leaves the room calmly after being asked whether she is hiding something  is briefed and sent to the school  is ordered to help expel him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p7-1\"><h3><span class=\"ttl\">Prologue: Briefed by Tsukishiro<\/span><span class=\"meta\">Y2V1 · p.7–11<\/span><\/h3><p class=\"setup\">In a Tokyo facility, Nanase (unnamed) listens as Tsukishiro briefs her on Ayanokōji Kiyotaka. Shows signs of dissatisfaction that Ayanokōji is praised as the White Room’s masterpiece. Leaves the room calmly after being asked whether she is hiding something.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is briefed and sent to the school.<span class=\"pg\">p.7–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to help expel him.<span class=\"pg\">p.7–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-2\">→ After: Prologue: Briefed by Tsukishiro<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p7-2","v":"y2v1","y":2,"o":16,"k":"","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa prologue  briefed by tsukishiro in a tokyo facility  nanase  unnamed  listens as tsukishiro briefs her on ayanokoji kiyotaka  shows signs of dissatisfaction that ayanokoji is praised as the white room s masterpiece  leaves the room calmly after being asked whether she is hiding something  is briefed and sent to the school  is ordered to help expel him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p7-2\"><h3><span class=\"ttl\">Prologue: Briefed by Tsukishiro<\/span><span class=\"meta\">Y2V1 · p.7–11<\/span><\/h3><p class=\"setup\">In a Tokyo facility, Nanase (unnamed) listens as Tsukishiro briefs her on Ayanokōji Kiyotaka. Shows signs of dissatisfaction that Ayanokōji is praised as the White Room’s masterpiece. Leaves the room calmly after being asked whether she is hiding something.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is briefed and sent to the school.<span class=\"pg\">p.7–11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to help expel him.<span class=\"pg\">p.7–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-1\">← Before: Prologue: Briefed by Tsukishiro<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p79-1\">→ After: Ch.3: Class 1-D hallway<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p79-1","v":"y2v1","y":2,"o":16,"k":"","w":"housen-kazuomi ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 3  class 1 d hallway accompanies hosen to class 2 d  stops hosen by referencing  that  apologizes to the second years and bows  looks at ayanokoji before leaving  accompanies and restrains him  looks at him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p79-1\"><h3><span class=\"ttl\">Ch.3: Class 1-D hallway<\/span><span class=\"meta\">Y2V1 · p.79–95<\/span><\/h3><p class=\"setup\">Accompanies Hōsen to Class 2-D. Stops Hōsen by referencing “that”. Apologizes to the second-years and bows. Looks at Ayanokōji before leaving.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Accompanies and restrains him.<span class=\"pg\">p.79–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Looks at him.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p7-2\">← Before: Prologue: Briefed by Tsukishiro<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p100-1\">→ After: Nanase with Hōsen; a probing look at Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p100-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa nanase with hosen  a probing look at ayanokoji accompanies hosen during his confrontation with ryuen  and obeys his order to withdraw   yes  that s a wise choice   i m sorry for the disturbance  calm and composed beside the volatile hosen   bows a polite final apology on behalf of class 1 d  when she raises her head she fixes ayanokoji with the same inquisitive  probing look as when she first arrived  then quickly looks away and runs after hosen  gives him a knowing  probing look   the white room agent silently assessing her target  obeys his withdrawal order  seen as his second in command in class 1 d","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p100-1\"><h3><span class=\"ttl\">Nanase with Hōsen; a probing look at Ayanokōji<\/span><span class=\"meta\">Y2V1 · p.100–101<\/span><\/h3><p class=\"setup\">Accompanies Hōsen during his confrontation with Ryūen, and obeys his order to withdraw.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yes. That&#x27;s a wise choice.&quot;<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m sorry for the disturbance.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Calm and composed beside the volatile Hōsen — bows a polite final apology on behalf of Class 1-D; when she raises her head she fixes Ayanokōji with the same inquisitive, probing look as when she first arrived, then quickly looks away and runs after Hōsen.<span class=\"pg\">p.100–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gives him a knowing, probing look — the White Room agent silently assessing her target.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Obeys his withdrawal order; seen as his second-in-command in Class 1-D.<span class=\"pg\">p.100–101<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p79-1\">← Before: Ch.3: Class 1-D hallway<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p142-1\">→ After: Ch.4: Approaching Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p142-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 4  approaching ayanokoji greets ayanokoji on the way to school  apologizes for hosen s rudeness  discusses cooperation between class 1 d and 2 d  says she will never yield to violence  agrees to set something up for him  approaches and proposes cooperation","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p142-1\"><h3><span class=\"ttl\">Ch.4: Approaching Ayanokōji<\/span><span class=\"meta\">Y2V1 · p.142–155<\/span><\/h3><p class=\"setup\">Greets Ayanokōji on the way to school. Apologizes for Hōsen’s rudeness. Discusses cooperation between Class 1-D and 2-D. Says she will never yield to violence. Agrees to set something up for him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches and proposes cooperation.<span class=\"pg\">p.148–155<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p100-1\">← Before: Nanase with Hōsen; a probing look at Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p204-1\">→ After: Ch.5: Library meeting and strategy<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p204-1","v":"y2v1","y":2,"o":16,"k":"","w":"horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 5  library meeting and strategy meets horikita and ayanokoji in the library  reveals class 1 d s situation and proposes becoming leader  explains hosen s individualist policy  proposes secret negotiations to horikita  tests ayanokoji s character  explains class 1 d started with 800 class points  negotiates with her  discusses cooperation with him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p204-1\"><h3><span class=\"ttl\">Ch.5: Library meeting and strategy<\/span><span class=\"meta\">Y2V1 · p.204–242<\/span><\/h3><p class=\"setup\">Meets Horikita and Ayanokōji in the library. Reveals Class 1-D’s situation and proposes becoming leader. Explains Hōsen’s individualist policy. Proposes secret negotiations to Horikita. Tests Ayanokōji’s character. Explains Class 1-D started with 800 class points.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.204–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Discusses cooperation with him.<span class=\"pg\">p.204–242<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p142-1\">← Before: Ch.4: Approaching Ayanokōji<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p205-1\">→ After: Nanase negotiates on behalf of Class 1-D<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p205-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"horikita-suzune housen-kazuomi ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase negotiates on behalf of class 1 d arrives alone at the library for the discussion with horikita and ayanokoji  fumbles her self introduction  starting with the masculine  boku  a detail the translation flags   i  no  that s not right  i am known as nanase tsubasa  i haven t done anything worthy of your thanks   many students have already begun taking action in accordance with hosen kun s orders   i m immensely sorry  but i m afraid i can t provide you with any specifics   an act of betrayal   our doors are always open to you  as long as you present us with at least a fixed number of private points  we ll accept the partnership without the slightest bit of hesitation   what really gets to me is the thought that this individualistic mindset might never go away  preventing us from being able to unite as a class in the future   yes    when asked if she fears hosen  at this point  i believe that approximately fifteen students would find it difficult to search for a partner on their own   hosen kun would never allow us to help you out for free  especially not now   hosen kun has not received any compensation from our classmates  upright  fearless and loyal   refuses to leak hosen s strategy  calling it betrayal  admits she fears him yet opposes his individualism for the class s future  and reveals he takes no profit  she negotiates single handedly to save the weak  negotiates the 15 pair equal cooperation proposal with her  confirms he controls class 1 d via orders  with no personal compensation  she opposes his individualist policy  treats him with respect  fixes her  same look  on him   the hidden white room agent quietly assessing her target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p205-1\"><h3><span class=\"ttl\">Nanase negotiates on behalf of Class 1-D<\/span><span class=\"meta\">Y2V1 · p.205–214<\/span><\/h3><p class=\"setup\">Arrives alone at the library for the discussion with Horikita and Ayanokōji; fumbles her self-introduction (starting with the masculine &quot;Boku,&quot; a detail the translation flags).<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I─ No, that&#x27;s not right… I am known as Nanase Tsubasa. I haven&#x27;t done anything worthy of your thanks.&quot;<span class=\"pg\">p.208<\/span><\/li><li class=\"q spoken\">&quot;Many students have already begun taking action in accordance with Hōsen-kun&#x27;s orders.&quot;<span class=\"pg\">p.209<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m immensely sorry, but I&#x27;m afraid I can&#x27;t provide you with any specifics.&quot;<span class=\"pg\">p.209<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;an act of betrayal.&quot;<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;our doors are always open to you. As long as you present us with at least a fixed number of private points, we&#x27;ll accept the partnership without the slightest bit of hesitation.&quot;<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What really gets to me is the thought that this individualistic mindset might never go away, preventing us from being able to unite as a class in the future.&quot;<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes.&quot; — when asked if she fears Hōsen<span class=\"pg\">p.211<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At this point, I believe that approximately fifteen students would find it difficult to search for a partner on their own.&quot;<span class=\"pg\">p.212<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hōsen-kun would never allow us to help you out for free. Especially not now.&quot;<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hōsen-kun has not received any compensation from our classmates.&quot;<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Upright, fearless and loyal — refuses to leak Hōsen&#x27;s strategy (calling it betrayal), admits she fears him yet opposes his individualism for the class&#x27;s future, and reveals he takes no profit; she negotiates single-handedly to save the weak.<span class=\"pg\">p.208–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates the 15-pair equal-cooperation proposal with her.<span class=\"pg\">p.208–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Confirms he controls Class 1-D via orders, with no personal compensation; she opposes his individualist policy.<span class=\"pg\">p.209–214<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Treats him with respect; fixes her &quot;same look&quot; on him — the hidden White Room agent quietly assessing her target.<span class=\"pg\">p.208–214<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p204-1\">← Before: Ch.5: Library meeting and strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p290-1\">→ After: Ch.6: Mediating and revealing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p290-1","v":"y2v1","y":2,"o":16,"k":"","w":"housen-kazuomi horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 6  mediating and revealing mediates between horikita and hosen  tries to stop hosen from leaving  explains nagumo s tolerance of fighting  proposes mutual trust  warns horikita about hosen s true nature  blocks hosen from stabbing ayanokoji  explains the 20 million point bounty and hosen s plan  reveals her true feelings toward ayanokoji  mediates for him  negotiates with her  explains to him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p290-1\"><h3><span class=\"ttl\">Ch.6: Mediating and revealing<\/span><span class=\"meta\">Y2V1 · p.290–335<\/span><\/h3><p class=\"setup\">Mediates between Horikita and Hōsen. Tries to stop Hōsen from leaving. Explains Nagumo’s tolerance of fighting. Proposes mutual trust. Warns Horikita about Hōsen’s true nature. Blocks Hōsen from stabbing Ayanokōji. Explains the 20-million-point bounty and Hōsen’s plan. Reveals her true feelings toward Ayanokōji.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Mediates for him.<span class=\"pg\">p.290–331<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Negotiates with her.<span class=\"pg\">p.290–333<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Explains to him.<span class=\"pg\">p.333–335<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p205-1\">← Before: Nanase negotiates on behalf of Class 1-D<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p326-1\">→ After: Nanase blocks the knife and breaks with Hōsen<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p326-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"housen-kazuomi nanase-tsubasa","q":"nanase tsubasa nanase blocks the knife and breaks with hosen steps between hosen and ayanokoji as he advances with the knife  spreading her arms to block him   please don t go any further  i can t approve of your methods after all  i can t  she declares she was wrong to accept his methods  hosen brushes her aside and ayanokoji charges the blade   i made the decision to lend you my strength until the very end  telling myself that it was for the good of the class   horikita senpai  working together with hosen kun has been impossible from the very beginning   that was just a ploy to get things to progress to this point  physically stops him  declares she was wrong to accept his methods  and is brushed aside","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p326-1\"><h3><span class=\"ttl\">Nanase blocks the knife and breaks with Hōsen<\/span><span class=\"meta\">Y2V1 · p.326–328<\/span><\/h3><p class=\"setup\">Steps between Hōsen and Ayanokōji as he advances with the knife, spreading her arms to block him. She declares she was wrong to accept his methods; Hōsen brushes her aside and Ayanokōji charges the blade.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Please don&#x27;t go any further! I can&#x27;t approve of your methods after all… I can&#x27;t!&quot;<span class=\"pg\">p.326<\/span><\/li><li class=\"q spoken\">&quot;I made the decision to lend you my strength until the very end, telling myself that it was for the good of the class.&quot;<span class=\"pg\">p.328<\/span><\/li><li class=\"q spoken\">&quot;Horikita-senpai, working together with Hōsen-kun has been impossible from the very beginning.&quot;<span class=\"pg\">p.328<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That was just a ploy to get things to progress to this point.&quot;<span class=\"pg\">p.328<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Physically stops him, declares she was wrong to accept his methods, and is brushed aside.<span class=\"pg\">p.326–328<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p290-1\">← Before: Ch.6: Mediating and revealing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p329-1\">→ After: The knife plot is exposed<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p329-1","v":"y2v1","y":2,"o":16,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa the knife plot is exposed ayanokoji lets the blade pierce his palm and stops hosen from using it on himself  hosen s plot is exposed   the reverse gripped knife  the petty knife purchase  amasawa s role   and ayanokoji offers him a deal","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p329-1\"><h3><span class=\"ttl\">The knife plot is exposed<\/span><span class=\"meta\">Y2V1 · p.329–338<\/span><\/h3><p class=\"setup\">Ayanokōji lets the blade pierce his palm and stops Hōsen from using it on himself. Hōsen&#x27;s plot is exposed — the reverse-gripped knife, the Petty knife purchase, Amasawa&#x27;s role — and Ayanokōji offers him a deal.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p326-1\">← Before: Nanase blocks the knife and breaks with Hōsen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p339-1\">→ After: The bounty and the hatred<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p339-1","v":"y2v1","y":2,"o":16,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the bounty and the hatred after the fight  she stays behind to explain to horikita and ayanokoji  she insists she had truly wanted a supporting relationship   no  nothing of the sort  horikita senpai  i truly did want to join hands with you and establish a supporting relationship between our two classes   we were told that the student who manages to expel ayanokoji kiyotaka of class 2 d will receive a bulk sum of 20 million private points  that s the special exam that was given to us  she explains she cooperated to keep the bounty from another class  then reveals an unexplained personal hatred   for the sake of my class  of class 1 d  i chose to cooperate with hosen kun knowing full well just how awful his methods truly were   because  if the 20 million point bounty were to fall into the hands of another class  it would bring about serious ramifications for us moving forward   i  simply didn t believe a person like you would be suitable for this school  ayanokoji senpai  reveals the plot and bounty to her and ayanokoji  urges them to beware other first year classes  directs open hatred at him   the white room agent s true motive remains hidden  she stays behind to explain  then leaves  breaks with hosen to stop the knife  reveals the negotiation was a ploy from the start and the 20 million point bounty  and explains she cooperated to keep the bounty from another class   then reveals an unexplained personal hatred  using the masculine katakana  boku  in her final line  deliberately linking herself to ayanokoji  per the translation notes","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p339-1\"><h3><span class=\"ttl\">The bounty and the hatred<\/span><span class=\"meta\">Y2V1 · p.339–341<\/span><\/h3><p class=\"setup\">After the fight, she stays behind to explain to Horikita and Ayanokōji; she insists she had truly wanted a supporting relationship. She explains she cooperated to keep the bounty from another class, then reveals an unexplained personal hatred.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;No, nothing of the sort, Horikita-senpai. I truly did want to join hands with you and establish a supporting relationship between our two classes.&quot;<span class=\"pg\">p.340<\/span><\/li><li class=\"q spoken\">&quot;We were told that the student who manages to expel Ayanokōji Kiyotaka of Class 2-D will receive a bulk sum of 20 million private points. That&#x27;s the special exam that was given to us.&quot;<span class=\"pg\">p.340<\/span><\/li><li class=\"q spoken\">&quot;For the sake of my class, of Class 1-D, I chose to cooperate with Hōsen-kun knowing full well just how awful his methods truly were.&quot;<span class=\"pg\">p.341<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Because, if the 20 million point bounty were to fall into the hands of another class, it would bring about serious ramifications for us moving forward.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I*… simply didn&#x27;t believe a person like you would be suitable for this school, Ayanokōji-senpai.&quot;<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Reveals the plot and bounty to her and Ayanokōji; urges them to beware other first-year classes.<span class=\"pg\">p.328–341<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Directs open hatred at him — the White Room agent&#x27;s true motive remains hidden; she stays behind to explain, then leaves.<span class=\"pg\">p.341<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Breaks with Hōsen to stop the knife, reveals the negotiation was a ploy from the start and the 20-million-point bounty, and explains she cooperated to keep the bounty from another class — then reveals an unexplained personal hatred, using the masculine katakana &quot;boku&quot; in her final line (deliberately linking herself to Ayanokōji, per the translation notes).<span class=\"pg\">p.326–341<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p329-1\">← Before: The knife plot is exposed<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p344-1\">→ After: Epilogue: Short story<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p344-1","v":"y2v1","y":2,"o":16,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa epilogue  short story irons out the agreement with horikita  observes ayanokoji on the school grounds  approaches him  meets him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p344-1\"><h3><span class=\"ttl\">Epilogue: Short story<\/span><span class=\"meta\">Y2V1 · p.344, 364–365<\/span><\/h3><p class=\"setup\">Irons out the agreement with Horikita. Observes Ayanokōji on the school grounds. Approaches him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him.<span class=\"pg\">p.344, 364–365<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p339-1\">← Before: The bounty and the hatred<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p364-1\">→ After: Short story: &quot;What is Reflected in Her Eyes&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p364-1","v":"y2v1","y":2,"o":16,"k":"narration","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa short story   what is reflected in her eyes  after leaving the dorm  spots ayanokoji approaching two class 1 a girls and decides to intercept him first  running to match his pace   good morning  ayanokouji senpai   i definitely think i managed a perfect smile   ayanokouji senpai s presence is unusually peculiar   i will force him to deepen his relationship with class 1 d   you can t judge people by their apperances  from her own viewpoint  deliberately engineers the chance morning encounter  judging ayanokoji an absentminded sharpened blade whose good or evil nature is all that matters to her  holds strongly to the belief that appearances can t tell a person s worth  the corpus prints  apperances  and notes his d class cooperation proposal is exactly what she d wanted   the white room agent manipulating the meeting  deliberately approaches him to draw him into class 1 d  he unexpectedly proposes the very cooperation she sought  she follows him to stop his outbursts  feeling powerless","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p364-1\"><h3><span class=\"ttl\">Short story: &quot;What is Reflected in Her Eyes&quot;<\/span><span class=\"meta\">Y2V1 · p.364–367<\/span><\/h3><p class=\"setup\">After leaving the dorm, spots Ayanokōji approaching two Class 1-A girls and decides to intercept him first, running to match his pace.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Good morning, Ayanokouji-senpai.&quot;<span class=\"pg\">p.364<\/span><\/li><li class=\"q narration\">&quot;I definitely think I managed a perfect smile.&quot;<span class=\"pg\">p.365<\/span><\/li><li class=\"q narration\">&quot;Ayanokouji-senpai&#x27;s presence is unusually peculiar.&quot;<span class=\"pg\">p.365<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I will force him to deepen his relationship with class 1-D&quot;<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You can&#x27;t judge people by their apperances.&quot;<span class=\"pg\">p.367<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> From her own viewpoint, deliberately engineers the chance morning encounter, judging Ayanokōji an absentminded sharpened blade whose good-or-evil nature is all that matters to her; holds strongly to the belief that appearances can&#x27;t tell a person&#x27;s worth (the corpus prints &quot;apperances&quot;) and notes his D-Class cooperation proposal is exactly what she&#x27;d wanted — the White Room agent manipulating the meeting.<span class=\"pg\">p.364–367<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Deliberately approaches him to draw him into Class 1-D; he unexpectedly proposes the very cooperation she sought.<span class=\"pg\">p.364–367<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> She follows him to stop his outbursts, feeling powerless.<span class=\"pg\">p.365<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p344-1\">← Before: Epilogue: Short story<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p368-1\">→ After: Short story: &quot;The Voice in My Heart&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v1-p368-1","v":"y2v1","y":2,"o":16,"k":"narration","w":"ayanokouji-kiyotaka horikita-suzune nanase-tsubasa","q":"nanase tsubasa short story   the voice in my heart  after horikita leaves the library  probes ayanokoji about how he ll convince hosen  then turns the question on him   that  i don t have a problem answering that question but only if  if you can tell me about you   what  kind of person are you  senpai   what you want to know isn t about her relationship with me  it seems   yes  i think you are a wicked and a filthy human being  ayanokouji senpai   as far as i can see  you look like a regular human being  ayanokouji senpai  boldly voices her belief that he is a wicked  filthy human being yet looks like a regular human   testing him about his true nature  good or evil  retreats when she fears she s come too close  while noting he seemed to understand exactly what she wanted to ask  uses the masculine  boku   katakana  hinting at her link to him  presses him on what kind of person he is  he sees through her intended question  admires her and wishes to become as splendid as her by next year","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v1-p368-1\"><h3><span class=\"ttl\">Short story: &quot;The Voice in My Heart&quot;<\/span><span class=\"meta\">Y2V1 · p.368–369<\/span><\/h3><p class=\"setup\">After Horikita leaves the library, probes Ayanokōji about how he&#x27;ll convince Hōsen, then turns the question on him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;That… I don&#x27;t have a problem answering that question but only if, if you can tell me about you.&quot;<span class=\"pg\">p.368<\/span><\/li><li class=\"q narration\">&quot;What— kind of person are you, senpai?&quot;<span class=\"pg\">p.368<\/span><\/li><li class=\"q narration\">&quot;What you want to know isn&#x27;t about her relationship with me, it seems.&quot;<span class=\"pg\">p.369<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Yes, I think you are a wicked and a filthy human being, Ayanokouji-senpai.&quot;<span class=\"pg\">p.369<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;As far as I can see, you look like a regular human being, Ayanokouji-senpai.&quot;<span class=\"pg\">p.369<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Boldly voices her belief that he is a wicked, filthy human being yet looks like a regular human — testing him about his true nature (good or evil); retreats when she fears she&#x27;s come too close, while noting he seemed to understand exactly what she wanted to ask; uses the masculine &quot;boku&quot; (katakana), hinting at her link to him.<span class=\"pg\">p.368–369<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses him on what kind of person he is; he sees through her intended question.<span class=\"pg\">p.368–369<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Admires her and wishes to become as splendid as her by next year.<span class=\"pg\">p.368<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v1-p364-1\">← Before: Short story: &quot;What is Reflected in Her Eyes&quot;<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p68-1","v":"y2v2","y":2,"o":17,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa named by ayanokoji  ch 2 backreference  he names her in his secret exam intel exchange with horikita  not present in those pages   see horikita s person record and ayanokoji s","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p68-1\"><h3><span class=\"ttl\">Named by Ayanokōji (Ch.2 backreference)<\/span><span class=\"meta\">Y2V2 · p.68–72<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He names her in his secret-exam intel exchange with Horikita; not present in those pages — see Horikita&#x27;s person record and Ayanokōji&#x27;s.<span class=\"pg\">p.68–72<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p111-1\">→ After: The confession on the way to school<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p111-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi nanase-tsubasa","q":"nanase tsubasa the confession on the way to school she is on her way to school alone on the mid june morning  she falls into step with him or he falls into hers   good morning  ayanokouji senpai   is there something in the sky   looking at the       blue sky  huh   what a beautiful day   yes  we haven t met for about a month and a half   i ve always felt sorry for what i did to you  ayanokouji senpai   senpai  do you hate me   no  the exam is still going on  the deadline is the start of the second semester   are you wondering why i haven t visited you since then   because of what happened last time  i m convinced that even with a plan  it might not work out that easily  also  after you knew our purpose  it would be very hard to pressure you in your everyday life   i don t know how  but i think they already know that housen kun has already made a move   i don t know if that s worth the cost of your left hand  senpai   yes  i think the students in my grade  including myself  have become able to deal with all sorts of special situations  although i don t know how much the upperclassmen know  us 1st years had taken our 2nd special exam at the end of may   ah  so you do know about it  one boy dropped out of class c in the first year   how did your class d place in the results of the exam   the previous time  we came in last  and this time  unfortunately  we only made third  but this time  class a and b battled fiercely  so the point difference created between the classes is very small   it d be a lie if i said he hadn t done anything  but it s true that he has nothing to do with this time s expulsion  you re the only one in his eyes now  ayanokouji senpai   although it s a far fetched theory based on only the result  i think it s thanks to you that he has become a bit more well behaved  i guess you could say that he s taking some of the energy focused on the first year students and placing it on the upperclassmen  recently  he keeps saying things like   let me fight the 2nd years  that s just great   i hope i can spend my school life here without any regrets   you must not leave any regrets in your school life as well  ayanokouji senpai   then i ll take my leave  her 1 d placed 3rd at the end of may exam  class c lost a boy  her apology changes nothing and she knows it  the strong determination is still in her eyes  cold  composed  and not forgiving herself  she carries the plan as her duty  she watches the blue sky the way a sniper watches a road  she apologizes  he absolves  neither moves  his new obsession is the 2nd years  she s disgusted and relieved","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p111-1\"><h3><span class=\"ttl\">The confession on the way to school<\/span><span class=\"meta\">Y2V2 · p.111–116<\/span><\/h3><p class=\"setup\">She is on her way to school alone on the mid-June morning; she falls into step with him or he falls into hers.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Good morning, Ayanokouji-senpai.”<span class=\"pg\">p.112<\/span><\/li><li class=\"q spoken\">“Is there something in the sky?”<span class=\"pg\">p.112<\/span><\/li><li class=\"q spoken\">“Looking at the …  …  blue sky, huh?”<span class=\"pg\">p.112<\/span><\/li><\/ul><details class=\"more\"><summary>22 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “What a beautiful day.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, we haven’t met for about a month and a half.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve always felt sorry for what I did to you, Ayanokouji-senpai.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, do you hate me?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, the exam is still going on. The deadline is the start of the second semester.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you wondering why I haven’t visited you since then?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because of what happened last time, I’m convinced that even with a plan, it might not work out that easily. Also, after you knew our purpose, it would be very hard to pressure you in your everyday life.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t know how, but I think they already know that Housen-kun has already made a move.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t know if that’s worth the cost of your left hand, senpai.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. I think the students in my grade, including myself, have become able to deal with all sorts of special situations. Although I don’t know how much the upperclassmen know, us 1st years had taken our 2nd special exam at the end of May.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, so you do know about it? One boy dropped out of Class C in the first year.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How did your Class D place in the results of the exam?”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The previous time, we came in last, and this time, unfortunately, we only made third. But this time, Class A and B battled fiercely, so the point difference created between the classes is very small.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’d be a lie if I said he hadn’t done anything. But it’s true that he has nothing to do with this time’s expulsion. You’re the only one in his eyes now, Ayanokouji-senpai.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although it’s a far-fetched theory based on only the result, I think it’s thanks to you that he has become a bit more well-behaved. I guess you could say that he’s taking some of the energy focused on the first year students and placing it on the upperclassmen. Recently, he keeps saying things like, “Let me fight the 2nd years”. That’s just great.”<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hope I can spend my school life here without any regrets.”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You must not leave any regrets in your school life as well, Ayanokouji-senpai”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then I’ll take my leave.”<span class=\"pg\">p.116<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her 1-D placed 3rd at the end-of-May exam; Class C lost a boy; her apology changes nothing and she knows it; the strong determination is still in her eyes.<span class=\"pg\">p.111–116<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cold, composed, and not forgiving herself; she carries the plan as her duty; she watches the blue sky the way a sniper watches a road.<span class=\"pg\">p.111–116<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She apologizes; he absolves; neither moves.<span class=\"pg\">p.111–116<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> His new obsession is the 2nd years; she&#x27;s disgusted and relieved.<span class=\"pg\">p.115–116<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p68-1\">← Before: Named by Ayanokōji (Ch.2 backreference)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p236-1\">→ After: The alliance terms with Housen<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p236-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"housen-kazuomi amasawa-ichika ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the alliance terms with housen she arrives late to the cafe  she checks the terms  she challenges amasawa once   we should be on equal footing  didn t i already say that before   you ve got guts  eh  trying it here   you re not bad yourself   nanase and i  and you  we ll form a group of three  alright   it s true that if you give me the bounty for getting him expelled  you won t get any money  but the reputation for getting ayanokouji senpai expelled will be given entirely to you housen kun  is that enough for you to accept the condition   shut up  nanase   are you sure about this   yeah   alright  since you re the one who makes the decision after all  but are you sure it s okay to trust amasawa san  i think she s the type who would betray her partners without giving it a second thought   trust  don t just assume that i trust her  that goes for you too  i don t trust either of you   then why did you decide to group up with her   i see  that may be true  even so  20 million points is too much   you really are a terrible person  she is the pressure holder  she tries to veto the amasawa deal and fails  she stays anyway   she has nowhere else to go  her class d co conspirator  the rival she cannot push out  she will be standing in the island exam against him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p236-1\"><h3><span class=\"ttl\">The alliance terms with Housen<\/span><span class=\"meta\">Y2V2 · p.236–242<\/span><\/h3><p class=\"setup\">She arrives late to the café; she checks the terms; she challenges Amasawa once.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“We should be on equal footing. Didn’t I already say that before?”<span class=\"pg\">p.237<\/span><\/li><li class=\"q spoken\">“You’ve got guts, eh? Trying it here.”<span class=\"pg\">p.239<\/span><\/li><li class=\"q spoken\">“You’re not bad yourself.”<span class=\"pg\">p.239<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Nanase and I, and you. We’ll form a group of three. Alright?”<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true that if you give me the bounty for getting him expelled, you won’t get any money, but the reputation for getting Ayanokouji-senpai expelled will be given entirely to you Housen-kun. Is that enough for you to accept the condition?”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shut up, Nanase.”<span class=\"pg\">p.241<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you sure about this?”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alright, since you’re the one who makes the decision after all. But are you sure it’s okay to trust Amasawa-san? I think she’s the type who would betray her partners without giving it a second thought.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Trust? Don’t just assume that I trust her. That goes for you too, I don’t trust either of you.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then why did you decide to group up with her?”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see, that may be true. Even so, 20 million points is too much.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You really are a terrible person.”<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She is the pressure-holder; she tries to veto the Amasawa deal and fails; she stays anyway — she has nowhere else to go.<span class=\"pg\">p.236–242<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Her Class D co-conspirator.<span class=\"pg\">p.236–242<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> The rival she cannot push out.<span class=\"pg\">p.237–242<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She will be standing in the island exam against him.<span class=\"pg\">p.241<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p111-1\">← Before: The confession on the way to school<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p254-1\">→ After: Coverage note: passing mentions<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p254-1","v":"y2v2","y":2,"o":17,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa coverage note  passing mentions  the first year students there were takahashi osamu kun and ishigami kyou kun from class a  me from class b  utomiya riku kun from class c  and housen kazuomi kun and nanase tsubasa san from class d  a total of 6 students","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p254-1\"><h3><span class=\"ttl\">Coverage note: passing mentions<\/span><span class=\"meta\">Y2V2 · p.254<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The first year students there were Takahashi Osamu-kun and Ishigami Kyou-kun from Class A, me from Class B, Utomiya Riku-kun from Class C, and Housen Kazuomi-kun and Nanase Tsubasa-san from Class D. A total of 6 students.”<span class=\"pg\">p.254<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p236-1\">← Before: The alliance terms with Housen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p336-1\">→ After: Nanase renews her vow<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v2-p336-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase renews her vow the bus lot  she stands before tsukishiro  his back is turned to her   yes  you are right   you re saying i should  expel ayanokouji kiyotaka   it s confirmed that he isn t an easy opponent to beat  no  it s something we ve known from the very beginning   you mean you ve been forced to be unreasonable   yes  i won t hesitate anymore  her left hand is tightly clenched as if brimming with natural power  tsukishiro smiles at the sight of it  the handler promises to free her  she swears to get him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v2-p336-1\"><h3><span class=\"ttl\">Nanase renews her vow<\/span><span class=\"meta\">Y2V2 · p.336–337<\/span><\/h3><p class=\"setup\">The bus lot; she stands before Tsukishiro; his back is turned to her.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yes, you are right.”<span class=\"pg\">p.336<\/span><\/li><li class=\"q spoken\">“You’re saying I should— expel Ayanokouji Kiyotaka?”<span class=\"pg\">p.336<\/span><\/li><li class=\"q spoken\">“It’s confirmed that he isn’t an easy opponent to beat. No, it’s something we’ve known from the very beginning.”<span class=\"pg\">p.336<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You mean you’ve been forced to be unreasonable?”<span class=\"pg\">p.337<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “—Yes. I won’t hesitate anymore.”<span class=\"pg\">p.337<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her left hand is tightly clenched as if brimming with natural power; Tsukishiro smiles at the sight of it.<span class=\"pg\">p.337<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> The handler promises to free her.<span class=\"pg\">p.336–337<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She swears to get him.<span class=\"pg\">p.337<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v2-p254-1\">← Before: Coverage note: passing mentions<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p7-1","v":"y2v3","y":2,"o":18,"k":"narration","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase s prologue monologue first person interior monologue  the old apartment in the evening light  a long shadow swinging like a pendulum  and her vow    i   not the justice driven others  will defeat ayanokoji kiyotaka for real   i can still vividly remember the shock i felt that day   that warm hand that would caress my head   that gentle smile that healed my soul   that sincere gaze that taught me admiration   that silent  blank expression that brought me to the edge of despair   but i can t forgive   and that s why   i  will   to send him back to the place he s meant to be   because  if i don t  there will surely be a second or even third victim that follows   and that alone must be avoided  no matter the cost   after all  my true objective lies far beyond defeating him  burdened by guilt and unable to support another s  justice  she fights under her own conviction  the decisive moment will come on the island  it s right here  right now  defeat ayanokoji kiyotaka for real   to send him back to where he is meant to be  a second or third victim must be avoided no matter the cost  her true objective lies far beyond defeating him  her target  he stands before her with his eyes fixed on her  she resolves to act here and now  interior monologue  first person  the corpus prints full width corner brackets  i  single curly  justice  and a figure dash in  all of this  it s right here  on p 8  the footnote marker  1  after  i  will  is printed in the text  p 8  pov nanase  no matsuo name prints on these pages  the volume record s earlier prologue summary claim overreached the print and has been corrected","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p7-1\"><h3><span class=\"ttl\">Nanase&#x27;s prologue monologue<\/span><span class=\"meta\">Y2V3 · p.7–8<\/span><\/h3><p class=\"setup\">First-person interior monologue: the old apartment in the evening light, a long shadow swinging like a pendulum, and her vow — “I” (not the justice-driven others) will defeat Ayanokōji Kiyotaka for real.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">“I can still vividly remember the shock I felt that day.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q narration\">“That warm hand that would caress my head.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q narration\">“That gentle smile that healed my soul.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> “That sincere gaze that taught me admiration.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “That silent, blank expression that brought me to the edge of despair.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “But I can&#x27;t forgive.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “And that&#x27;s why, 『I』 will.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “To send him back to the place he&#x27;s meant to be.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Because, if I don&#x27;t, there will surely be a second or even third victim that follows.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “And that alone must be avoided, no matter the cost.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “After all, my true objective lies far beyond defeating him.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Burdened by guilt and unable to support another&#x27;s “justice”, she fights under her own conviction; the decisive moment will come on the island (“It&#x27;s right here. Right now.”).<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Goal<\/span> Defeat Ayanokōji Kiyotaka for real — to send him back to where he is meant to be; a second or third victim must be avoided no matter the cost; her true objective lies far beyond defeating him.<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her target; he stands before her with his eyes fixed on her; she resolves to act here and now.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Interior monologue; first person. The corpus prints full-width corner brackets 『I』, single curly ‘justice’, and a figure dash in “all of this─ It&#x27;s right here.” on p.8; the footnote marker “[1]” after “『I』 will.” is printed in the text (p.8). POV Nanase.<span class=\"pg\">p.7–8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No Matsuo name prints on these pages; the volume record&#x27;s earlier Prologue summary claim overreached the print and has been corrected.<span class=\"pg\">p.7–8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p58-1\">→ After: First crossing: Nanase at D7<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p58-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa first crossing  nanase at d7 reaches the clearing  29 people  amasawa and hosen nowhere to be seen  she greets him and scouts the crowd   good morning to you  ayanokoji senpai   what happened to the other two  aren t groups supposed to stick together for the most part  seems better to do it that way to me at least  especially at first   they said they d scout out the area and then we all split up  so i decided to come check how many other groups were here   i think i m going to leave  it can t hurt to take a look around   indeed  you re all alone  so please be careful senpai  goodbye  then  their first encounter on the island  he gauges her independence  she releases him to probe the area","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p58-1\"><h3><span class=\"ttl\">First crossing: Nanase at D7<\/span><span class=\"meta\">Y2V3 · p.58–59<\/span><\/h3><p class=\"setup\">Reaches the clearing (29 people); Amasawa and Hōsen nowhere to be seen; she greets him and scouts the crowd.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Good morning to you, Ayanokōji-senpai.”<span class=\"pg\">p.58<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “What happened to the other two? Aren’t groups supposed to stick together for the most part? Seems better to do it that way to me at least. Especially at first.”<span class=\"pg\">p.58<\/span><\/li><li class=\"q spoken\">“They said they’d scout out the area and then we all split up. So I decided to come check how many other groups were here.”<span class=\"pg\">p.58<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I think I’m going to leave. It can’t hurt to take a look around.”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Indeed! You’re all alone, so please be careful Senpai. Goodbye, then.”<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Their first encounter on the island; he gauges her independence; she releases him to probe the area.<span class=\"pg\">p.58–59<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p7-1\">← Before: Nanase&#x27;s prologue monologue<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p69-1\">→ After: Evening crossing: second status exchange<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p69-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa evening crossing  second status exchange crosses paths again near the same sort of place  just before 5 pm  the two quietly compare the day s spoils   senpai   second time today huh   indeed  what a coincidence   how did it go for you today    speaker untagged in the translation  recorded unassigned   i did what i could and earned 3 points  you    speaker untagged in the translation  recorded unassigned   well  when it comes to designated areas  the three of us earned 8 points  i didn t manage to make it to the second area in time  but i took first place in a task instead  so we re at 13 points altogether    speaker untagged in the translation  recorded unassigned   sounds like you re off to a good start    speaker untagged in the translation  recorded unassigned   well then  senpai  if you ll excuse me  operates solo within her group  measures him with courteous precision  her group already at 13 points  evening crossing  his 3 points vs her 13  she leaves pointedly","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p69-1\"><h3><span class=\"ttl\">Evening crossing: second status exchange<\/span><span class=\"meta\">Y2V3 · p.69<\/span><\/h3><p class=\"setup\">Crosses paths again near the same sort of place, just before 5 PM; the two quietly compare the day’s spoils.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Senpai.”<span class=\"pg\">p.69<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Second time today huh?”<span class=\"pg\">p.69<\/span><\/li><li class=\"q spoken\">“Indeed. What a coincidence.”<span class=\"pg\">p.69<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “How did it go for you today?” — speaker untagged in the translation; recorded unassigned.<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I did what I could and earned 3 points. You?” — speaker untagged in the translation; recorded unassigned.<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Well, when it comes to designated areas, the three of us earned 8 points. I didn’t manage to make it to the second area in time, but I took first place in a Task instead, so we’re at 13 points altogether.” — speaker untagged in the translation; recorded unassigned.<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Sounds like you’re off to a good start.” — speaker untagged in the translation; recorded unassigned.<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well then, Senpai, if you’ll excuse me.”<span class=\"pg\">p.69<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Operates solo within her group; measures him with courteous precision; her group already at 13 points.<span class=\"pg\">p.58–69<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Evening crossing; his 3 points vs her 13; she leaves pointedly.<span class=\"pg\">p.69<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p58-1\">← Before: First crossing: Nanase at D7<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p78-1\">→ After: Third rendezvous at E6<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p78-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa third rendezvous at e6 sits down for a break at e6  he seems to be waiting for a task  she shows up alone a third time   ayanokoji senpai  it seems we meet again   by any chance  do you think that we might share the same table   maybe  her third crossing in six areas  she pauses instead of leaving   unlike the last two quick encounters  she asks for the favor","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p78-1\"><h3><span class=\"ttl\">Third rendezvous at E6<\/span><span class=\"meta\">Y2V3 · p.78<\/span><\/h3><p class=\"setup\">Sits down for a break at E6; he seems to be waiting for a Task; she shows up alone a third time.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ayanokōji-senpai, it seems we meet again.”<span class=\"pg\">p.78<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “By any chance, do you think that we might share the same Table?”<span class=\"pg\">p.78<\/span><\/li><li class=\"q spoken\">“Maybe.”<span class=\"pg\">p.78<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Her third crossing in six areas; she pauses instead of leaving — unlike the last two quick encounters; she asks for the favor.<span class=\"pg\">p.78–82<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p69-1\">← Before: Evening crossing: second status exchange<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p79-1\">→ After: The favor: accompanying him<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p79-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the favor  accompanying him she lingers and asks to accompany him  citing the group s split  hosen and amasawa chose independent action  she fears falling behind alone   um  ayanokoji senpai  there s a favor i d like to ask of you   a favor   if it s not too much trouble  would you perhaps allow me to accompany you for a while   accompany me  what do you mean by that   to tell you the truth  a slight issue came up as my group was talking last night  both hosen kun and amasawa san felt that we would be better off if we all acted independently  so everything more or less fell apart   i ve crossed paths with you a total of three times now  senpai  from what i ve seen from our encounters  i believe that you ve managed to reach the designated area faster than me  that is of course  except for the first time  i fear that if i m on my own  it won t be long before i start to fall behind the designated areas   don t you think it s possible that i just happened to be faster than you these last two times   that may be so indeed  but either way  i ve still recognized you as a step above someone as inexperienced as myself   i don t think it s a very wise idea to travel together with someone in a different school year   you re saying that due to the influence it would have on early bird bonuses and the increased competition for tasks  correct   there would be a conflict of interest if we came across a task that only had room for one more group   i would be perfectly fine with taking the back seat in that regard  ayanokoji senpai  i would only step foot into the designated area after you ve checked to make sure you ve received your points and bonuses  that way  it shouldn t place you at a disadvantage  as for tasks  i ll just defer to you should there only be one space remaining   you d ultimately lose points by doing that  nanase   this is my first uninhabited island exam  and you ve already proven the extent of your physical abilities during your fight with hosen kun  it would be immensely helpful to me if i could have you choose a suitable route for us to take   even if we assume that i m going to choose the most suitable route  would you be able to keep pace with me  sometimes the path i choose might even be dangerous  would you really be able to do it   i m fairly confident in my stamina   you re not uncertain because you think i might hold you back  it s more that you re not able to trust me  isn t it   alright  if that s what you want  then go ahead   thank you very much  she attaches herself as his companion  she gives up early bird bonuses and task spots to shadow him","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p79-1\"><h3><span class=\"ttl\">The favor: accompanying him<\/span><span class=\"meta\">Y2V3 · p.79–81<\/span><\/h3><p class=\"setup\">She lingers and asks to accompany him, citing the group&#x27;s split; Hōsen and Amasawa chose independent action; she fears falling behind alone.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Um, Ayanokōji-senpai, there’s a favor I’d like to ask of you.”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “A favor?”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">“If it’s not too much trouble, would you perhaps allow me to accompany you for a while?”<span class=\"pg\">p.79<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Accompany me? What do you mean by that?”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To tell you the truth, a slight issue came up as my group was talking last night. Both Hōsen-kun and Amasawa-san felt that we would be better off if we all acted independently, so everything more or less fell apart.”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve crossed paths with you a total of three times now, Senpai. From what I’ve seen from our encounters, I believe that you’ve managed to reach the designated area faster than me. That is of course, except for the first time. I fear that if I’m on my own, it won’t be long before I start to fall behind the designated areas.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you think it’s possible that I just happened to be faster than you these last two times?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That may be so indeed, but either way, I’ve still recognized you as a step above someone as inexperienced as myself.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think it’s a very wise idea to travel together with someone in a different school year.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re saying that due to the influence it would have on Early Bird Bonuses and the increased competition for Tasks, correct?”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There would be a conflict of interest if we came across a Task that only had room for one more group.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would be perfectly fine with taking the back seat in that regard, Ayanokōji-senpai. I would only step foot into the designated area after you’ve checked to make sure you’ve received your points and Bonuses. That way, it shouldn’t place you at a disadvantage. As for Tasks, I’ll just defer to you should there only be one space remaining.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’d ultimately lose points by doing that, Nanase.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is my first uninhabited island exam, and you’ve already proven the extent of your physical abilities during your fight with Hōsen-kun. It would be immensely helpful to me if I could have you choose a suitable route for us to take.”<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if we assume that I’m going to choose the most suitable route, would you be able to keep pace with me? Sometimes the path I choose might even be dangerous. Would you really be able to do it?”<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m fairly confident in my stamina. …You’re not uncertain because you think I might hold you back, it’s more that you’re not able to trust me, isn’t it?”<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alright. If that’s what you want, then go ahead.”<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you very much.”<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She attaches herself as his companion; she gives up Early Bird Bonuses and Task spots to shadow him.<span class=\"pg\">p.78–81<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p78-1\">← Before: Third rendezvous at E6<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p82-1\">→ After: The E5 feint; the F8 quiz registration<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p82-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka sudou-ken nanase-tsubasa","q":"nanase tsubasa the e5 feint  the f8 quiz registration 1 00 pm  an hour plus until the next designation  several new tasks  he picks the f8 quiz  she sees through it   we just have to make sure you and i really have the same table  we on the same page   indeed  the notion that we ve just coincidentally shared some of the same designated areas is certainly feasible  so further investigation is the natural first step  what do we do for now though  it seems we still have some time until the next designation happens   it looks like there s a quiz type task right under area f8  we ll go there   it s fairly close by too   yeah  after we re done there  if the next designated area shows up too far away from us  i think we ll give up on trying to get there in time   understood  please lead the way   we should be able to see it any time now   right   by the way senpai  this task we re looking to take on seems rather challenging  wouldn t you agree   well  it s a quiz  so it s true that there can be a lot to cover   that said  i should have a decent enough chance depending on the genre they choose   that may be so  but  you actually wanted to go after the task in area e5  didn t you senpai   i ll admit that i considered it  but it was honestly fifty fifty  it s nothing you need to worry about   i m glad to hear that  however  i m simply here to accompany you  so please don t make any concessions for my sake  okay   you don t need to remind me  besides  the quiz is better when it comes to rewards anyway  sudo beckons them to registration  they hurry in before the spots close   yo  ayanokoji  there s only three spots left  get in before it s too late   seems he s right  let s hurry","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p82-1\"><h3><span class=\"ttl\">The E5 feint; the F8 quiz registration<\/span><span class=\"meta\">Y2V3 · p.82–84<\/span><\/h3><p class=\"setup\">1:00 PM; an hour plus until the next designation; several new Tasks; he picks the F8 quiz; she sees through it. Sudō beckons them to registration; they hurry in before the spots close.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“We just have to make sure you and I really have the same Table. We on the same page?”<span class=\"pg\">p.82<\/span><\/li><li class=\"q spoken\">“Indeed! The notion that we’ve just coincidentally shared some of the same designated areas is certainly feasible, so further investigation is the natural first step. What do we do for now though? It seems we still have some time…”<span class=\"pg\">p.82<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It looks like there’s a quiz-type Task right under area F8. We’ll go there.”<span class=\"pg\">p.82<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Indeed! The notion that we’ve just coincidentally shared some of the same designated areas is certainly feasible, so further investigation is the natural first step. What do we do for now though? It seems we still have some time until the next designation happens.”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s fairly close by too!”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. After we’re done there, if the next designated area shows up too far away from us, I think we’ll give up on trying to get there in time.”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Understood. Please lead the way.”<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We should be able to see it any time now.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right!”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “By the way Senpai, this Task we’re looking to take on seems rather challenging, wouldn’t you agree?”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it’s a quiz, so it’s true that there can be a lot to cover.”<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, I should have a decent enough chance depending on the genre they choose.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That may be so, but… you actually wanted to go after the Task in area E5, didn’t you Senpai?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll admit that I considered it, but it was honestly fifty-fifty. It’s nothing you need to worry about.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m glad to hear that. However, I’m simply here to accompany you, so please don’t make any concessions for my sake, okay?”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t need to remind me. Besides, the quiz is better when it comes to rewards anyway.”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yo! Ayanokōji! There’s only three spots left! Get in before it’s too late!”<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Seems he’s right. Let’s hurry.”<span class=\"pg\">p.84<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p79-1\">← Before: The favor: accompanying him<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p85-1\">→ After: Ike out of it; anime-genre quiz; Nanase 5/20<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p85-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"sudou-ken ike-kanji nanase-tsubasa","q":"nanase tsubasa ike out of it  anime genre quiz  nanase 5 20 waiting for the 12th group  ike looks listless  hondo struggles to talk to him  she quietly takes it in  sudo points at ak with a warning about her   it s nanase  sudo senpai   quiz genre anime  question 1 bombdam  question 2 dashu sea chicken  she tracks his guessing  5 correct for her  bottom three for him   those questions were all pretty challenging  huh    speaker untagged in the print  recorded unassigned   we freakin  did it kanji   yay","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p85-1\"><h3><span class=\"ttl\">Ike out of it; anime-genre quiz; Nanase 5/20<\/span><span class=\"meta\">Y2V3 · p.85–90<\/span><\/h3><p class=\"setup\">Waiting for the 12th group; Ike looks listless; Hondō struggles to talk to him; she quietly takes it in; Sudō points at AK with a warning about her. 『Quiz Genre・Anime』; Question 1 Bombdam; Question 2 Dashu Sea Chicken; she tracks his guessing; 5 correct for her; bottom three for him.<\/p><p class=\"with\">with <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It’s Nanase, Sudō-senpai.”<span class=\"pg\">p.86<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “We freakin’ did it Kanji!”<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Yay…”<span class=\"pg\">p.90<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Those questions were all pretty challenging, huh?” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.90<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p82-1\">← Before: The E5 feint; the F8 quiz registration<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p90-1\">→ After: Reading Ike; the day she stays the course; Table confirmed<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p90-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka sudou-ken nanase-tsubasa","q":"nanase tsubasa reading ike  the day she stays the course  table confirmed the quiz is done  she asks about sudo s group  ak slots ike s worry into shinohara  she spots his real concern  he sets the last of the day as i7 random designation  skipping it for the g8 g9 tasks  her tablet  same table  i7   is something the matter   is something wrong with sudo senpai s group   as an uninvolved third party  what does their group look like to you  nanase   anything since you ve never met any of them other than sudo before   indeed  then could you perhaps fill me in and tell me a bit about them   off on sudo s left is ike kanji  and to his right is hondo ryotaro  they re the type of people who do stupid things and end up standing out in a bad way  or  well  i guess it might be better to say that they re the type of people who easily get carried away  but  at the same time  they both really add a lot to the class atmosphere   they aren t a studious bunch by any means so their group leaves a lot to be desired  but sudo has plenty of physical strength and ike has the right skills and experience to camp out on an uninhabited island  and hondo  well  hondo s a lively guy   ike senpai and hondo senpai  is it  they add a lot to the atmosphere  from what i can tell  that doesn t really seem to be the case for ike senpai  could he be sick perhaps   it s true that he s usually livening things up in class  while he seems to be in a bit of a funk right now  he should at least be fine physically   so that s what ayanokoji senpai is worried about   well  it is what it is  it s troublesome  but i can t always worry about the affairs of others  in the quiz  instead of placing in the top three  i placed all the way down at the bottom  they on the other hand took first  composition aside  the group that racks up more points is the better one   senpai  may i say something before we depart   once again  just to reiterate  please disregard my presence and choose what you truly believe to be the most ideal route  okay  ayanokoji senpai   i ll say this one more time as well  i m not letting your presence influence my decisions  so stop worrying about it   i m relieved to hear you say that  please take care of me moving forward   oi ayanokoji  didja just say you re gonna set up camp in h9   if ya want  how  bout we all meet up after an  camp together  should be more fun with friends  i d also like to hear whatcha think  bout our strategies so far and see if you ve got any suggestions   it ll prolly be hard to find each other in the forest  so how  bout we meet up on the beach in g9 instead   since we ll all be close by  how  bout 5 30   alright  see you on the beach in g9 at 5 30   turns out that we ll be spending the night with them today  do you have any problems with that  nanase   it s fine  i actually think it ll be a good chance to get to know everyone","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p90-1\"><h3><span class=\"ttl\">Reading Ike; the day she stays the course; Table confirmed<\/span><span class=\"meta\">Y2V3 · p.90–96<\/span><\/h3><p class=\"setup\">The quiz is done; she asks about Sudō&#x27;s group; AK slots Ike&#x27;s worry into Shinohara; she spots his real concern; he sets the last of the day as I7 random designation (skipping it for the G8/G9 Tasks); her tablet: same Table (I7).<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Is something the matter?”<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\">“Is something wrong with Sudō-senpai’s group?”<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “As an uninvolved third-party, what does their group look like to you, Nanase? …anything since you’ve never met any of them other than Sudō before.”<span class=\"pg\">p.90<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Indeed. Then could you perhaps fill me in and tell me a bit about them?”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Off on Sudō’s left is Ike Kanji, and to his right is Hondō Ryōtarō. They’re the type of people who do stupid things and end up standing out in a bad way… or, well, I guess it might be better to say that they’re the type of people who easily get carried away. But, at the same time, they both really add a lot to the class atmosphere.”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They aren’t a studious bunch by any means so their group leaves a lot to be desired, but Sudō has plenty of physical strength and Ike has the right skills and experience to camp out on an uninhabited island. And Hondō… Well, Hondō’s a lively guy.”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ike-senpai and Hondō-senpai, is it? They add a lot to the atmosphere…? From what I can tell, that doesn’t really seem to be the case for Ike-senpai; Could he be sick perhaps?”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true that he’s usually livening things up in class. While he seems to be in a bit of a funk right now, he should at least be fine physically.”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So that’s what Ayanokōji-senpai is worried about…”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it is what it is. It’s troublesome, but I can’t always worry about the affairs of others. In the quiz, instead of placing in the top three, I placed all the way down at the bottom. They on the other hand took first. Composition aside, the group that racks up more points is the better one.”<span class=\"pg\">p.91<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, may I say something before we depart?”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Once again, just to reiterate, please disregard my presence and choose what you truly believe to be the most ideal route. Okay, Ayanokōji-senpai?”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll say this one more time as well. I’m not letting your presence influence my decisions, so stop worrying about it.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m relieved to hear you say that. Please take care of me moving forward.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oi Ayanokōji! Didja just say you’re gonna set up camp in H9?”<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If ya want, how ‘bout we all meet up after an’ camp together? Should be more fun with friends. I’d also like to hear whatcha think ‘bout our strategies so far and see if you’ve got any suggestions.”<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’ll prolly be hard to find each other in the forest, so how ‘bout we meet up on the beach in G9 instead?”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since we’ll all be close by, how ‘bout 5:30?”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alright. See you on the beach in G9 at 5:30.”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Turns out that we’ll be spending the night with them today. Do you have any problems with that, Nanase?”<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s fine. I actually think it’ll be a good chance to get to know everyone.”<span class=\"pg\">p.96<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p85-1\">← Before: Ike out of it; anime-genre quiz; Nanase 5/20<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p97-1\">→ After: The beach/the clearing camp<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p97-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"sudou-ken ayanokouji-kiyotaka ike-kanji nanase-tsubasa","q":"nanase tsubasa the beach the clearing camp 5 30 beach meet  sudo s group arrives breathless  the replacement task netted only third  they walk to h9 s clearing  hondo wheezing  ike unresponsive   ehhh  not so great  after we split  a buncha new tasks popped up so we ended up goin  for three of  em  we took third place in one  but the other two had so many people that we couldn t even register   the second day only just ended  so don t overwork yourselves   first things first  let s find a place to camp  how  bout it  kanji   let s go back to h9 for now  we passed by a clearing earlier  that should be good enough   i really don t get the impression that ike senpai is the life of the party that you made him out to be  ayanokoji senpai   he has a lot going on   a lot   i don t feel comfortable talking about it when it s not my place to do so  if you really want to know  you should ask him yourself   you re right  i ll try asking him when i get the chance   oi kanji  ain tcha gonna go fishin  tonight   eh  oh  uh  well  it s already kinda late and i m pretty tired  so yeah  sorry   well  i guess it can t be helped then   seems like his mind is somewhere else","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p97-1\"><h3><span class=\"ttl\">The beach/the clearing camp<\/span><span class=\"meta\">Y2V3 · p.97–99<\/span><\/h3><p class=\"setup\">5:30 beach meet; Sudō&#x27;s group arrives breathless; the replacement Task netted only third; they walk to H9&#x27;s clearing; Hondō wheezing; Ike unresponsive.<\/p><p class=\"with\">with <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Ehhh… Not so great. After we split, a buncha new Tasks popped up so we ended up goin’ for three of ‘em. We took third place in one, but the other two had so many people that we couldn’t even register.”<span class=\"pg\">p.97<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The second day only just ended, so don’t overwork yourselves.”<span class=\"pg\">p.97<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “First things first, let’s find a place to camp. How ‘bout it, Kanji?”<span class=\"pg\">p.97<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Let’s go back to H9 for now. We passed by a clearing earlier. That should be good enough.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I really don’t get the impression that Ike-senpai is the life of the party that you made him out to be, Ayanokōji-senpai.”<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He has a lot going on.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A lot…?”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t feel comfortable talking about it when it’s not my place to do so. If you really want to know, you should ask him yourself.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re right. I’ll try asking him when I get the chance.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oi Kanji. Ain’tcha gonna go fishin’ tonight?”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Oh, uh, well… it’s already kinda late and I’m pretty tired, so yeah. Sorry.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I guess it can’t be helped then.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Seems like his mind is somewhere else.”<span class=\"pg\">p.99<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p90-1\">← Before: Reading Ike; the day she stays the course; Table confirmed<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p100-1\">→ After: The tent-fire circle: equanimity with Hondō<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p100-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"hondou-ryoutaro sudou-ken ike-kanji nanase-tsubasa","q":"nanase tsubasa the tent fire circle  equanimity with hondo mosquitos  conversations through mesh  hondo chats her up  sudo warns her  she owns her past  ike s listlessness becomes the topic  she quietly intervenes to buy ike time   so nanase chan s in class d  huh  i never wouldda guessed   no no  i m really not a very capable person  class d seems like an appropriate place for me   eh  no way  if anything  we re the incapable ones here  ain t that right guys   the atmosphere feels down in the dumps  kanji  ken  what s with you guys   nothin  really  but lemme warn ya ryotaro  nanase ain t trustworthy   wha  why s that   no reason  really  just stating a fact   and what s that supposed to mean   it s okay hondo senpai  i did something rather rude to sudo senpai in the past  that s all   rude  so it s not cuz he tried to touch you inappropriately or somethin   you think i d do somethin  like that   well  it is true that you ve always been devoted to horikita  but like  what the hell happened then   it s not somethin  you need to know about   well  alright then i guess  but kanji s been pretty out of it this whole time   o oh  uh  i  same old same old  ya know   sudo took the words right out of my mouth  you ve been really out of it man   even though we ve only just met  i also got the impression that you were rather lacking in spirit   what do you think ayanokoji   earlier  ayanokoji senpai told me that you and hondo senpai are the type of people who add a lot to the class  atmosphere  but  so far  it just seems to me like your mind is somewhere else entirely  is something troubling you  ike senpai   uhm  how do i put it   could you two please hold off and give him a moment   there s no need for us to hold off  nanase chan  in the end it s probably nothin  big   no  it might be a bit too early to say that ryotaro  let s try waitin   eh  a ah  well i guess we can try","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p100-1\"><h3><span class=\"ttl\">The tent-fire circle: equanimity with Hondō<\/span><span class=\"meta\">Y2V3 · p.100–103<\/span><\/h3><p class=\"setup\">Mosquitos; conversations through mesh; Hondō chats her up; Sudō warns her; she owns her past; Ike&#x27;s listlessness becomes the topic; she quietly intervenes to buy Ike time.<\/p><p class=\"with\">with <a href=\"hondou-ryoutaro.html\">Hondō Ryōtaro<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hondō Ryōtaro<\/b> “So Nanase-chan’s in Class D, huh? I never wouldda guessed.”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">“No no. I’m really not a very capable person… Class D seems like an appropriate place for me.”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hondō Ryōtaro<\/b> “Eh? No way. If anything, we’re the incapable ones here, ain’t that right guys?”<span class=\"pg\">p.100<\/span><\/li><\/ul><details class=\"more\"><summary>21 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “The atmosphere feels down in the dumps. Kanji, Ken, what’s with you guys?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nothin’ really. But lemme warn ya Ryōtarō… Nanase ain’t trustworthy.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wha? Why’s that?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No reason, really. Just stating a fact.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And what’s that supposed to mean!?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s okay Hondō-senpai. I did something rather rude to Sudō-senpai in the past, that’s all.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Rude? So it’s not cuz he tried to touch you inappropriately or somethin’?”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You think I’d do somethin’ like that?”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it is true that you’ve always been devoted to Horikita. But like, what the hell happened then?”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not somethin’ you need to know about.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, alright then I guess… But Kanji’s been pretty out of it this whole time.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “O-oh, uh, I… same old same old, ya know?”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sudō took the words right out of my mouth. You’ve been really out of it man.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even though we’ve only just met, I also got the impression that you were rather lacking in spirit.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you think Ayanokōji?”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Earlier, Ayanokōji-senpai told me that you and Hondō-senpai are the type of people who add a lot to the class’ atmosphere. But, so far, it just seems to me like your mind is somewhere else entirely… Is something troubling you, Ike-senpai?”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uhm, how do I put it…”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Could you two please hold off and give him a moment?”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s no need for us to hold off, Nanase-chan. In the end it’s probably nothin’ big.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. It might be a bit too early to say that Ryōtarō. Let’s try waitin’.”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? A-ah… Well I guess we can try.”<span class=\"pg\">p.103<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p97-1\">← Before: The beach/the clearing camp<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p103-1\">→ After: Ike&#x27;s confession: Shinohara<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p103-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ike-kanji hondou-ryoutaro sudou-ken nanase-tsubasa","q":"nanase tsubasa ike s confession  shinohara ten minutes of silence  ike breaks  the shinohara revelation  her gentle counsel  her tears   to be honest  there s  a girl i ve had my eye on for a while now   what  who  who is it   let s wait until ike senpai feels ready to tell us himself   h hey but like  you ve gotta dive in head first with this kinda stuff   how about you calm down and wait to hear what ike senpai has to say  instead of worrying about who he likes  don t you think that it s more important to find out how it relates to the matter at hand  or am i wrong   i i guess you re right   the girl i like is  uhm  sh shinohara  shinohara satsuki   b but kanji  like  you re on bad terms with shinohara right  you re always talkin  about how crazy ugly she is   it s not like i ve been conscious of her from the start or anything  hell  i hated her at first  but  i dunno why  but at some point i started caring about her and  well  i guess i didn t wanna admit it to myself  so just went along pretending that i hadn t fallen for her   i mean  if you like shinohara  then why don t you just go confess to her   it s just not that simple  not anymore   did something happen  ike senpai   shinohara is in a group together with komiya right now  that guy  probably likes her too   plus  well  it seems like she sees him as someone special as well   i  i only realized that i was fallin  in love with shinohara a little while ago  so when this exam came around  i wanted to group up with her more than anything  but i just couldn t be freaking honest about it so we started fightin  like we always do  it s pathetic  this whole time  i ve just been searching for her   maybe i just got the wrong idea at some point  thinking she liked me somehow even though we argue so much  i m such a loser  even now i ve got no idea what i shouldda done differently   can t you just be honest with her  ike senpai  i don t necessarily think that d be a bad thing   but  shinohara s together with that komiya guy while i m here in the friendzone   i m not so certain about that  this is just a guess  but  don t you think shinohara senpai has just been waiting for you to draw the line   draw the line   from what i ve been told  you re someone who s always bright and cheerful to everyone  someone who often speaks what s on your mind  of course  i m sure that shinohara senpai has a high opinion of you in this regard as well  that said  don t you think she might wish she could be someone a little more special to you   don t you think maybe she wants you to be more upfront about your feelings   ike senpai  would you be happy if the girl you liked never took you seriously  there s nothing wrong with trying to hide your embarrassment  but you won t get anywhere if you don t convey your feelings to her  wouldn t you want her to look at you a little more seriously as well   dammit   feeling troubled about this isn t a bad thing  per se  but you re currently in the midst of a special exam where your future here is at stake  you wouldn t be the only one expelled either  your actions could very well drag sudo senpai and hondo senpai down along with you  i fully understand the feeling of wanting to go chasing after shinohara senpai  i do  but you should focus on fighting for survival first   if you can t meet  if you can never reunite with someone you care about  then you ll never ever be able to let them know you love them again    her voice breaks  sudo panics  attribution of the following exchange lines is ambiguous in the print  y you  why are you crying     ike senpai  you don t have the time to be feeling caught up in your troubles  wouldn t you agree    sudo by  sudo spoke up in a panic     sudo s question went unanswered   yeah  i ve gotta get through this exam safely first right    speaker untagged  recorded unassigned   y you  why are you crying   ike senpai  you don t have the time to be feeling caught up in your troubles  wouldn t you agree   ken  ryotaro  i m sorry guys  i  i ve prolly troubled you two a heck of a lot these past two days  haven t i   no  you haven t  eh  well  maybe just a lil  bit   to be honest  i m still anxious about shinohara  but  that won t matter anyway if i don t get through the exam first  all my worrying  all this time i ve spent  everything wouldda been in vain if we don t pass   eyy  attaboy kanji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p103-1\"><h3><span class=\"ttl\">Ike&#x27;s confession: Shinohara<\/span><span class=\"meta\">Y2V3 · p.103–109<\/span><\/h3><p class=\"setup\">Ten minutes of silence; Ike breaks; the Shinohara revelation; her gentle counsel; her tears.<\/p><p class=\"with\">with <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"hondou-ryoutaro.html\">Hondō Ryōtaro<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “To be honest… There’s… a girl I’ve had my eye on for a while now.”<span class=\"pg\">p.103<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hondō Ryōtaro<\/b> “What!? Who!? Who is it!?”<span class=\"pg\">p.104<\/span><\/li><li class=\"q spoken\">“Let’s wait until Ike-senpai feels ready to tell us himself.”<span class=\"pg\">p.104<\/span><\/li><\/ul><details class=\"more\"><summary>29 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “H-hey but like, you’ve gotta dive in head-first with this kinda stuff!”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How about you calm down and wait to hear what Ike-senpai has to say? Instead of worrying about who he likes, don’t you think that it’s more important to find out how it relates to the matter at hand? Or am I wrong?”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-I guess you’re right.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The girl I like is… uhm… Sh-Shinohara… Shinohara Satsuki.”<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “B-but Kanji, like… You’re on bad terms with Shinohara right? You’re always talkin’ about how crazy ugly she is.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not like I’ve been conscious of her from the start or anything. Hell, I hated her at first. But… I dunno why, but at some point I started caring about her and, well… I guess I didn’t wanna admit it to myself, so just went along pretending that I hadn’t fallen for her.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I mean, if you like Shinohara, then why don’t you just go confess to her?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s just not that simple. Not anymore.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did something happen, Ike-senpai?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shinohara is in a group together with Komiya right now. That guy… probably likes her too.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Plus, well… it seems like she sees him as someone special as well.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I… I only realized that I was fallin’ in love with Shinohara a little while ago… So when this exam came around, I wanted to group up with her more than anything. But I just couldn’t be freaking honest about it so we started fightin’ like we always do… It’s pathetic… This whole time, I’ve just been searching for her…”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe I just got the wrong idea at some point, thinking she liked me somehow even though we argue so much… I’m such a loser. Even now I’ve got no idea what I shouldda done differently.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can’t you just be honest with her, Ike-senpai? I don’t necessarily think that’d be a bad thing.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But… Shinohara’s together with that Komiya guy while I’m here in the friendzone.”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not so certain about that. This is just a guess, but… don’t you think Shinohara-senpai has just been waiting for you to draw the line?”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Draw the line…?”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From what I’ve been told, you’re someone who’s always bright and cheerful to everyone. Someone who often speaks what’s on your mind. Of course, I’m sure that Shinohara-senpai has a high opinion of you in this regard as well. That said, don’t you think she might wish she could be someone a little more special to you?”<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t you think maybe she wants you to be more upfront about your feelings?”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ike-senpai, would you be happy if the girl you liked never took you seriously? There’s nothing wrong with trying to hide your embarrassment, but you won’t get anywhere if you don’t convey your feelings to her. Wouldn’t you want her to look at you a little more seriously as well?”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Dammit.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Feeling troubled about this isn’t a bad thing, per se, but you’re currently in the midst of a special exam where your future here is at stake. You wouldn’t be the only one expelled either; Your actions could very well drag Sudō-senpai and Hondō-senpai down along with you. I fully understand the feeling of wanting to go chasing after Shinohara-senpai, I do, but you should focus on fighting for survival first.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “If you can’t meet… If you can never reunite with someone you care about… then you’ll never ever be able to let them know you love them again…!” — her voice breaks; Sudō panics; attribution of the following exchange lines is ambiguous in the print (“Y-you, why are you crying?” / “Ike-senpai, you don’t have the time to be feeling caught up in your troubles, wouldn’t you agree?” — Sudō by ‘Sudō spoke up in a panic’ / ‘Sudō’s question went unanswered’); “…Yeah. I’ve gotta get through this exam safely first right?” — speaker untagged; recorded unassigned.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Y-you, why are you crying?”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ike-senpai, you don’t have the time to be feeling caught up in your troubles, wouldn’t you agree?”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ken, Ryōtarō, I’m sorry guys. I… I’ve prolly troubled you two a heck of a lot these past two days, haven’t I?”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, you haven’t… Eh, well, maybe just a lil’ bit.”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To be honest, I’m still anxious about Shinohara. But… that won’t matter anyway if I don’t get through the exam first. All my worrying, all this time I’ve spent, everything wouldda been in vain if we don’t pass.”<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eyy, attaboy Kanji!”<span class=\"pg\">p.108<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p100-1\">← Before: The tent-fire circle: equanimity with Hondō<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p110-1\">→ After: Pre-dawn: her Ike-worry; I8 over H7<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p110-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka sudou-ken ike-kanji nanase-tsubasa","q":"nanase tsubasa pre dawn  her ike worry  i8 over h7 just after 6 am  wakes him from outside his tent   the others still asleep  she asks whether she said too much at the fire  his response relieves her only partly  the split up question  her resolve to keep eyes on ike while keeping pace   uhm  ayanokoji senpai  are you awake yet   please wait a second  i ll be right out   i m sorry to bother you so early in the morning   i was already awake so it s fine  we need to start tidying up and get ready to head out soon anyway  what s up   it s about ike senpai  do you think i said a little too much last night   well  rather than having said too much  to me it felt more like you just called it like it was   thanks to you  ike s managed to get back on his feet  or  i guess it s more like he s managed to finally take a stand  i think he appreciates what you ve done for him   you think so   i feel like ike senpai is in a sort of precarious position right now  i m afraid that yesterday s discussion might backfire and cause him to act recklessly  that s why i m not sure if we should split off from them right away   it s not that i don t understand how you feel  but   it s no good  huh  i thought so  if we split up with them  it would probably be impossible to meet back up again   well  let s see   in any case  we should probably wait and see what designated area they get first   h7  huh   we can always choose to conserve energy and miss the area for a second time  sudo s group got i8  they all move together  ike in the lead   energized  she watches him closely   we got i8 so if you two are goin  the same way we can head out together  i m fired up so let s get this done   we re heading in the same direction again  so how about we stick together until we have to split up   sure thing  you down  kanji   a ah  of course   well  anyway  i guess i ll lead  so you all can just follow me   you don t seem to be enjoying this very much  ayanokoji senpai  your expression is quite stiff   it s nothing out of the ordinary   is that so   there s no use worryin   bout that  ayanokoji s always got that sorta look on his face   well there s your answer   you re still thinking about ike senpai  aren t you ayanokoji senpai   you re reading too far into it  i m glad to see that he s grown up a bit  but honestly outside of that i m not sure what you re referring to   is that so","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p110-1\"><h3><span class=\"ttl\">Pre-dawn: her Ike-worry; I8 over H7<\/span><span class=\"meta\">Y2V3 · p.110–115<\/span><\/h3><p class=\"setup\">Just after 6 AM; wakes him from outside his tent — the others still asleep; she asks whether she said too much at the fire; his response relieves her only partly; the split-up question; her resolve to keep eyes on Ike while keeping pace. Sudō&#x27;s group got I8; they all move together; Ike in the lead — energized; she watches him closely.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Uhm, Ayanokōji-senpai, are you awake yet?”<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Please wait a second, I’ll be right out.”<span class=\"pg\">p.110<\/span><\/li><li class=\"q spoken\">“I’m sorry to bother you so early in the morning.”<span class=\"pg\">p.110<\/span><\/li><\/ul><details class=\"more\"><summary>25 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I was already awake so it’s fine. We need to start tidying up and get ready to head out soon anyway. What’s up?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s about Ike-senpai. Do you think I said a little too much last night…?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, rather than having said too much… To me it felt more like you just called it like it was.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanks to you, Ike’s managed to get back on his feet. Or, I guess it’s more like he’s managed to finally take a stand. I think he appreciates what you’ve done for him.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You think so?”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I feel like Ike-senpai is in a sort-of precarious position right now. I’m afraid that yesterday’s discussion might backfire and cause him to act recklessly… That’s why I’m not sure if we should split off from them right away.”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not that I don’t understand how you feel, but…”<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s no good, huh… I thought so. If we split up with them, it would probably be impossible to meet back up again.”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, let’s see…”<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In any case, we should probably wait and see what designated area they get first.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “H7, huh?”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We can always choose to conserve energy and miss the area for a second time.”<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We got I8 so if you two are goin’ the same way we can head out together. I’m fired up so let’s get this done!”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’re heading in the same direction again, so how about we stick together until we have to split up?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sure thing. You down, Kanji?”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A-ah, of course.”<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, anyway. I guess I’ll lead, so you all can just follow me.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t seem to be enjoying this very much, Ayanokōji-senpai. Your expression is quite stiff.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s nothing out of the ordinary.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so?”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s no use worryin’ ‘bout that. Ayanokōji’s always got that sorta look on his face.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well there’s your answer.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re still thinking about Ike-senpai, aren’t you Ayanokōji-senpai?”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re reading too far into it. I’m glad to see that he’s grown up a bit, but honestly outside of that I’m not sure what you’re referring to.”<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Is that so?”<span class=\"pg\">p.114<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p103-1\">← Before: Ike&#x27;s confession: Shinohara<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p116-1\">→ After: The J9 sprint; the Beach Flags Showdown<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p116-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the j9 sprint  the beach flags showdown southeast of i8  sudo s group bolts for the i9 task  j9 ahead  adult task setup in j6    beach flags showdown  they look the other way to reach the area  arrive first in j5  early bird gone to ak  her arrival bonus 1 point   for now  let s head over to j9   this is to lower the chances of being in the next designated area at nine o clock  correct   yeah   we did it senpai  back to j6   a long line  likely another table s area  she considers sitting out   if we re lucky  we might be able to take up the last spot   perhaps  maybe j6 is the designated area for another table   perhaps   let s go check it out for the time being   right","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p116-1\"><h3><span class=\"ttl\">The J9 sprint; the Beach Flags Showdown<\/span><span class=\"meta\">Y2V3 · p.116–119<\/span><\/h3><p class=\"setup\">Southeast of I8; Sudō&#x27;s group bolts for the I9 Task; J9 ahead; adult Task setup in J6 — “Beach Flags Showdown”; they look the other way to reach the area; arrive first in J5 (Early Bird gone to AK; her Arrival Bonus 1 point). Back to J6 — a long line; likely another Table&#x27;s area; she considers sitting out.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “For now, let’s head over to J9.”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\">“This is to lower the chances of being in the next designated area at nine o’clock, correct?”<span class=\"pg\">p.116<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Yeah.”<span class=\"pg\">p.117<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “We did it Senpai.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we’re lucky, we might be able to take up the last spot?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps. Maybe J6 is the designated area for another Table?”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps…”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let’s go check it out for the time being.”<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right!”<span class=\"pg\">p.119<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p110-1\">← Before: Pre-dawn: her Ike-worry; I8 over H7<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p120-1\">→ After: Kiriyama&#x27;s rush; the Beach Flags runs; her landslide<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p120-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka kiriyama-ikuto nanase-tsubasa","q":"nanase tsubasa kiriyama s rush  the beach flags runs  her landslide j6  vice president kiriyama fills the last boys  slot  seven girls already   one slot left  he yields it to her  she takes it   if senpai can t participate then i ll sit this one out as well  i wouldn t want to keep you waiting   it s okay  i wanted to take a break anyway  you should participate   but   since you re surrendering all of the early bird bonuses to me  the gap between our points is only going to get wider  i m not saying anything about whether you ll win or not  but you should just go for it if you think you stand a chance   thank you very much  well  i suppose i ll go sign up then  blue green bikini with the tv reference excuse  first vs tomioka   gun sync reflex  second match by large margin  semifinal  the final vs tokunaga  b  her landslide  tokunaga asks for the handshake  paying due respect to the victor two years her junior   can i ask you something   what is it   i see that you chose a rather cute swimsuit  is there a reason for that   a reason  from what i ve seen of beach flags on tv  girls usually compete wearing swimsuits like this  right  i thought it d be strange if i took part in a school swimsuit  have i misunderstood something   she s a tough one   that was a landslide victory   thank you very much  i managed to get through it somehow   u uhm  ayanokoji senpai   hm   seeing you stare at me so closely like that  it s  well  it s a little unsettling  you know   ah  yeah  sorry   ayanokoji  don t say anything unnecessary","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p120-1\"><h3><span class=\"ttl\">Kiriyama&#x27;s rush; the Beach Flags runs; her landslide<\/span><span class=\"meta\">Y2V3 · p.120–127<\/span><\/h3><p class=\"setup\">J6; vice president Kiriyama fills the last boys&#x27; slot; seven girls already — one slot left; he yields it to her; she takes it. Blue-green bikini with the TV-reference excuse; first vs Tomioka — gun-sync reflex; second match by large margin; semifinal; the final vs Tokunaga (B+); her landslide; Tokunaga asks for the handshake (“paying due respect to the victor two years her junior”).<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kiriyama-ikuto.html\">Kiriyama Ikuto<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“If Senpai can’t participate then I’ll sit this one out as well. I wouldn’t want to keep you waiting.”<span class=\"pg\">p.121<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’s okay, I wanted to take a break anyway. You should participate.”<span class=\"pg\">p.121<\/span><\/li><li class=\"q spoken\">“But…”<span class=\"pg\">p.121<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Since you’re surrendering all of the Early Bird Bonuses to me, the gap between our points is only going to get wider. I’m not saying anything about whether you’ll win or not, but you should just go for it if you think you stand a chance.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you very much. Well… I suppose I’ll go sign up then.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can I ask you something?”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is it?”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see that you chose a rather cute swimsuit. Is there a reason for that?”<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A reason? From what I’ve seen of Beach Flags on TV, girls usually compete wearing swimsuits like this, right? I thought it’d be strange if I took part in a school swimsuit. Have I misunderstood something?”<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She’s a tough one.”<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That was a landslide victory.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you very much. I managed to get through it somehow.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “U-uhm, Ayanokōji-senpai?”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hm?”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Seeing you stare at me so closely like that, it’s… well, it’s a little unsettling, you know…?”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah… Yeah. Sorry.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji, don’t say anything unnecessary.”<span class=\"pg\">p.127<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p116-1\">← Before: The J9 sprint; the Beach Flags Showdown<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p130-1\">→ After: Nanase named at the beach<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p130-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase named at the beach  nanase  i m going to go talk with a senpai for a bit  so take your time    named by nagumo  not present  pov ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p130-1\"><h3><span class=\"ttl\">Nanase named at the beach<\/span><span class=\"meta\">Y2V3 · p.130<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nanase, I’m going to go talk with a senpai for a bit, so take your time” — named by Nagumo; not present; POV Ayanokōji.<span class=\"pg\">p.130<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p120-1\">← Before: Kiriyama&#x27;s rush; the Beach Flags runs; her landslide<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p133-1\">→ After: The water limit; the H5 approach; middle school<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p133-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the water limit  the h5 approach  middle school h5  she drinks her last water at arrival  probes him on lone wolf status  probes back on her middle school  her managed answers about smiling less and an  incident   nanase  how much water do you have   i used up the last of what i had on hand this morning  all i have left is the bottle i was given from participating in the task earlier   this is our first major hurdle   we ll need to obtain fresh water somehow  won t we senpai   ayanokoji senpai  why did you decide to take part in the exam alone   i don t have many friends  so i couldn t find anyone to group up with   that doesn t seem to be the case to me   i m not lying  there really aren t very many people i d be willing to call a friend   even so  i m sure you could ve at least found someone   are you really that curious   yes  because no matter how you look at it  acting independently puts you at a complete disadvantage  wouldn t you agree   back when you faced off against hosen kun  your movements were different from those of a normal high school student  ayanokoji senpai   if you managed to notice something like that  then you re not exactly a normal high school student either  nanase   it s true that acting independently comes with many disadvantages  it shouldn t be impossible for me to join up with another group during the exam  but if i don t have a decent number of points when the time comes  i d just end up causing trouble for the other group   understandably so  after all  your score would be averaged together with theirs  regardless of how many people their group might have   but  it seems fairly misguided to complain  the school recommended that we form groups from the very beginning  so those of us who decided otherwise aren t in any position to complain   even so  it s not like it s impossible for me to win either  if i were to join a group that was struggling to accumulate enough points  there s a chance that my presence might bring forth unexpected synergies   so you chose to fight on your own in order to bring forth these synergies  is that what you re saying  ayanokoji senpai   well  i m not sure  i was just talking in a general sense  despite your misconception  you still shouldn t discount the possibility that i simply struggled to find a group to join   fufu  that s true  you certainly seem a bit inarticulate at times   have you always been like that   for the most part  aren t people with my sort of disposition usually like this from the start   i don t think so at all  things happen that can cause someone with a gloomy disposition to become bright and spirited  and in the same vein  someone with a spirited disposition may become gloomy  that can happen  right   i hear you say that a naturally gloomy person can change  but i can t help but feel like it would be forced   yet  though it may be forced  the fact that they can act cheerful is amazing in it s own right   true   i don t think i d be able to do it  on that note  have you changed since you were in middle school  nanase   i wonder  i don t feel like i ve changed very much since back then  but i probably have a little   in what way   in the past  i get the sense that i used to smile more   i also get the sense that i talk and go out with others far less often than i did back then   after all  an incident took place that i believe changed me forever   yes  between hosen kun and amasawa san  we ve been earning quite a few from tasks recently  i m not sure which of the two has been contributing more  but either way  they appear to be doing more than me   conversely  i might be in a risky spot   let s do our best moving forward  senpai   let s do our best moving forward  senpai   right","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p133-1\"><h3><span class=\"ttl\">The water limit; the H5 approach; middle school<\/span><span class=\"meta\">Y2V3 · p.133–138<\/span><\/h3><p class=\"setup\">H5; she drinks her last water at arrival; probes him on lone-wolf status; probes back on her middle school; her managed answers about smiling less and an “incident”.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Nanase, how much water do you have?”<span class=\"pg\">p.134<\/span><\/li><li class=\"q spoken\">“I used up the last of what I had on hand this morning. All I have left is the bottle I was given from participating in the Task earlier.”<span class=\"pg\">p.134<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “This is our first major hurdle.”<span class=\"pg\">p.134<\/span><\/li><\/ul><details class=\"more\"><summary>34 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “We’ll need to obtain fresh water somehow, won’t we Senpai?”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-senpai, why did you decide to take part in the exam alone?”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t have many friends, so I couldn’t find anyone to group up with.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That doesn’t seem to be the case to me.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not lying. There really aren’t very many people I’d be willing to call a friend.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, I’m sure you could’ve at least found someone.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you really that curious?”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Because no matter how you look at it, acting independently puts you at a complete disadvantage, wouldn’t you agree?”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Back when you faced off against Hōsen-kun, your movements were different from those of a normal high school student, Ayanokōji-senpai.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you managed to notice something like that, then you’re not exactly a normal high school student either, Nanase.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true that acting independently comes with many disadvantages. It shouldn’t be impossible for me to join up with another group during the exam, but if I don’t have a decent number of points when the time comes, I’d just end up causing trouble for the other group.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Understandably so. After all, your score would be averaged together with theirs, regardless of how many people their group might have.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, it seems fairly misguided to complain. The school recommended that we form groups from the very beginning, so those of us who decided otherwise aren’t in any position to complain.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even so, it’s not like it’s impossible for me to win either. If I were to join a group that was struggling to accumulate enough points, there’s a chance that my presence might bring forth unexpected synergies.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you chose to fight on your own in order to bring forth these synergies…? Is that what you’re saying, Ayanokōji-senpai?”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I’m not sure. I was just talking in a general sense. Despite your misconception, you still shouldn’t discount the possibility that I simply struggled to find a group to join.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fufu, that’s true. You certainly seem a bit inarticulate at times.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Have you always been like that?”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “For the most part, aren’t people with my sort of disposition usually like this from the start?”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think so at all. Things happen that can cause someone with a gloomy disposition to become bright and spirited, and in the same vein, someone with a spirited disposition may become gloomy. That can happen, right?”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hear you say that a naturally gloomy person can change, but I can’t help but feel like it would be forced.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yet, though it may be forced, the fact that they can act cheerful is amazing in it’s own right.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…True.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think I’d be able to do it. On that note, have you changed since you were in middle school, Nanase?”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wonder. I don’t feel like I’ve changed very much since back then, but I probably have a little.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In what way?”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the past─ I get the sense that I used to smile more.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I also get the sense that I talk and go out with others far less often than I did back then.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “After all, an incident took place that I believe changed me forever…”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Between Hōsen-kun and Amasawa-san, we’ve been earning quite a few from Tasks recently. I’m not sure which of the two has been contributing more, but either way, they appear to be doing more than me.”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Conversely, I might be in a risky spot.”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let’s do our best moving forward, Senpai.”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let’s do our best moving forward, Senpai.”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right.”<span class=\"pg\">p.138<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p130-1\">← Before: Nanase named at the beach<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p139-1\">→ After: The rest stop; the History Test win<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p139-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa the rest stop  the history test win she rests in the shade  he sprints for the history test  she watches him thread between two three person groups  he takes first  100  chemistry win  5  48 points on day 3","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p139-1\"><h3><span class=\"ttl\">The rest stop; the History Test win<\/span><span class=\"meta\">Y2V3 · p.139–145<\/span><\/h3><p class=\"setup\">She rests in the shade; he sprints for the History Test; she watches him thread between two three-person groups; he takes first (100); chemistry win (+5); 48 points on day 3.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p133-1\">← Before: The water limit; the H5 approach; middle school<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p146-1\">→ After: The Sakagami water race; the strategy probes<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p146-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka sakagami nanase-tsubasa","q":"nanase tsubasa the sakagami water race  the strategy probes her recovery  the h4 drift off route  she flags the error  he ignores it  the sakagami tent  the 2l 1 5l water race  her relief   thanks to your concern earlier  my energy has recovered completely  i m prepared for anything you might throw at me   you know  i must say  there s no decent path forward around here at all  is there   uhm  senpai  how do you plan to go about securing more water   you have something in mind  don t you senpai   the fact that you don t seem very concerned about our impending lack of water   t that would be a bit of a problem for me   our current circumstances don t really allow us to do that  right  it would take several hours to return to the harbor from here  and it would be even slower if we chose to do so at night   water is an absolute necessity  but if you do that way  you might end up getting hurt  i don t think it s a very wise idea  not by any stretch of the imagination   and yet  you re telling me this dangerous idea is the only one you ve been considering  ayanokoji senpai   that  yes  i suppose you re right about that   forcing yourself to move across the island at night is already more than risky enough   so you re saying that  if it s you  you won t fail   if it fails  then that s that  the sakagami site  the race  water secured  her  we are truly fortunate  the walk to i4   eh   uhm  senpai  it seems we ve gone off course  we need to go further to the east   this is great senpai  we re lucky to have found another task before it showed on our tablets   lucky indeed   though  i wonder what type of task this is   this is a task where you earn water according to the order in which you arrive  a race  essentially  ayanokoji  having come in first  will receive 2 liters of water and three points  as you came in second  nanase  you ll receive 1 5 liters of water and two points   that means  we ve already cleared the task haven t we   what a surprise   luck is also an extension of your abilities  you two  be proud   we are truly fortunate   with this  we won t have to think about drinking water  well  at least for a while  she quizzes him about holding back  he admits it s part of his strategy  he deflects with i4   if i m not mistaken  i believe that you re someone who can aim much higher  ayanokoji senpai  be it designated areas or tasks  i m sure you re capable of scoring quite a large number of points   but  with the way things are going now  aren t you afraid that you ll just continue to fall behind the other groups  no matter what  time efficiency is important  it isn t something that you can work to overcome in a single day   i never planned on exerting myself during the early stages of the exam  since i m on my own  it would all be over if i were to get sick or injured due to negligence   a strategy  that involves deliberately holding yourself back when it comes to earning points   let s just say that this is only one part of my strategy   y yes","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p146-1\"><h3><span class=\"ttl\">The Sakagami water race; the strategy probes<\/span><span class=\"meta\">Y2V3 · p.146–152<\/span><\/h3><p class=\"setup\">Her recovery; the H4 drift-off-route; she flags the error; he ignores it; the Sakagami tent; the 2L/1.5L water race; her relief. The Sakagami site; the race; water secured; her “…We are truly fortunate.”; the walk to I4. She quizzes him about holding back; he admits it&#x27;s part of his strategy; he deflects with I4.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sakagami.html\">Sakagami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Thanks to your concern earlier, my energy has recovered completely. I’m prepared for anything you might throw at me.”<span class=\"pg\">p.146<\/span><\/li><li class=\"q spoken\">“You know, I must say… There’s no decent path forward around here at all, is there?”<span class=\"pg\">p.146<\/span><\/li><li class=\"q spoken\">“Uhm, Senpai, how do you plan to go about securing more water?”<span class=\"pg\">p.147<\/span><\/li><\/ul><details class=\"more\"><summary>26 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You have something in mind, don’t you Senpai?”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The fact that you don’t seem very concerned about our impending lack of water.”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “T-that would be a bit of a problem for me…”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our current circumstances don’t really allow us to do that, right? It would take several hours to return to the harbor from here. And it would be even slower if we chose to do so at night.”<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Water is an absolute necessity, but if you do that way, you might end up getting hurt. I don’t think it’s a very wise idea, not by any stretch of the imagination.”<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And yet, you’re telling me this dangerous idea is the only one you’ve been considering, Ayanokōji-senpai?”<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That… Yes, I suppose you’re right about that.”<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Forcing yourself to move across the island at night is already more than risky enough.”<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…So you’re saying that, if it’s you, you won’t fail?”<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it fails, then that’s that.”<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh─?”<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uhm, Senpai, it seems we’ve gone off course. We need to go further to the east.”<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is great Senpai. We’re lucky to have found another Task before it showed on our tablets.”<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Lucky indeed.”<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Though, I wonder what type of Task this is?”<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is a Task where you earn water according to the order in which you arrive, a race, essentially. Ayanokōji, having come in first, will receive 2 liters of water and three points. As you came in second, Nanase, you’ll receive 1.5 liters of water and two points.”<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That means─ We’ve already cleared the Task haven’t we? …What a surprise.”<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Luck is also an extension of your abilities, you two. Be proud.”<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…We are truly fortunate.”<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “With this, we won’t have to think about drinking water. Well, at least for a while.”<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I’m not mistaken, I believe that you’re someone who can aim much higher, Ayanokōji-senpai. Be it designated areas or Tasks, I’m sure you’re capable of scoring quite a large number of points.”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, with the way things are going now, aren’t you afraid that you’ll just continue to fall behind the other groups? No matter what, time efficiency is important. It isn’t something that you can work to overcome in a single day.”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I never planned on exerting myself during the early stages of the exam. Since I’m on my own, it would all be over if I were to get sick or injured due to negligence.”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A strategy… that involves deliberately holding yourself back when it comes to earning points?”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let’s just say that this is only one part of my strategy.”<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Y-yes.”<span class=\"pg\">p.152<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p139-1\">← Before: The rest stop; the History Test win<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p153-1\">→ After: The river camp; Ike&#x27;s fire; Kei&#x27;s group<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p153-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ike-kanji sudou-ken ayanokouji-kiyotaka karuizawa-kei nanase-tsubasa","q":"nanase tsubasa the river camp  ike s fire  kei s group i4  bonuses denied  day 3 curtain  sudo ike hondo meet them across the river  the fish grill  class 2 a shows up with them   shimazaki ikkei  fukuyama shinobu and kei   heeey  ayanokoji   ayanokoji  nanase  i thought it was you two  so this is where you guys ve been   what an amazing coincidence  are you camping around here tonight  ike senpai   hold up  what was your last designated area today  you two   i4   man  what re the odds   but  well  there s a difference between knowledge and experience  right  how should i put it  if you could do something just cuz you knew about it  nothing would be hard at all   you re quite resourceful   ah  there you are  ayanokoji senpai   what s up   you were gone for a while  so i went to look for you   what wrong  karuizawa san   oh  nothing  i was just  like  shocked  bout them grilling fish is all   hey  why don t we camp here too  i think ike kun d be willing to treat us   haah  why should i treat you   c mon  it s not like you ll run outta fish   there ll be less for us if you guys eat them  no way   dude  what s the harm  she might know somethin   bout shinohara   i it can t be helped  i guess i ll just have to prepare for three more people","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p153-1\"><h3><span class=\"ttl\">The river camp; Ike&#x27;s fire; Kei&#x27;s group<\/span><span class=\"meta\">Y2V3 · p.153–158<\/span><\/h3><p class=\"setup\">I4, bonuses denied; day 3 curtain; Sudō/Ike/Hondō meet them across the river; the fish grill; Class 2-A shows up with them — Shimazaki Ikkei, Fukuyama Shinobu and Kei.<\/p><p class=\"with\">with <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Heeey-! Ayanokōji-!”<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Ayanokōji-! Nanase-! I thought it was you two-! So this is where you guys’ve been-!”<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\">“What an amazing coincidence-! Are you camping around here tonight, Ike-senpai-!?”<span class=\"pg\">p.154<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Hold up, what was your last designated area today, you two…?”<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I4.”<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Man, what’re the odds!”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, well, there’s a difference between knowledge and experience, right? How should I put it… If you could do something just cuz you knew about it, nothing would be hard at all.”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re quite resourceful.”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, there you are, Ayanokōji-senpai.”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What’s up?”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You were gone for a while, so I went to look for you.”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What wrong, Karuizawa-san?”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, nothing. I was just, like, shocked ‘bout them grilling fish is all.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, why don’t we camp here too? I think Ike-kun’d be willing to treat us.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Haah!? Why should I treat you!?”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “C’mon, it’s not like you’ll run outta fish.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’ll be less for us if you guys eat them! No way!”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Dude, what’s the harm? She might know somethin’ ‘bout Shinohara.”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-it can’t be helped! I guess I’ll just have to prepare for three more people!”<span class=\"pg\">p.158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p146-1\">← Before: The Sakagami water race; the strategy probes<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p161-1\">→ After: Nanase named at the interrogation<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p161-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase named at the interrogation  i could talk of how nanase might be involved in the expulsion plan    named in his own narration  not present  pov ayanokoji   i m just traveling together with nanase in order to successfully get    named by ayanokoji to kei  not present  pov ayanokoji   even though there was nothing between nanase and me  as my girlfriend    named  not present  pov ayanokoji   nanase  then the fastest way to get around it was to give her something more    named  not present  pov ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p161-1\"><h3><span class=\"ttl\">Nanase named at the interrogation<\/span><span class=\"meta\">Y2V3 · p.161–162<\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I could talk of how Nanase might be involved in the expulsion plan” — named in his own narration; not present; POV Ayanokōji.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I’m just traveling together with Nanase in order to successfully get” — named by Ayanokōji to Kei; not present; POV Ayanokōji.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Even though there was nothing between Nanase and me, as my girlfriend,” — named; not present; POV Ayanokōji.<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nanase, then the fastest way to get around it was to give her something more” — named; not present; POV Ayanokōji.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p153-1\">← Before: The river camp; Ike&#x27;s fire; Kei&#x27;s group<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p164-1\">→ After: The double Emergency Alert; the formation<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p164-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka ike-kanji nanase-tsubasa","q":"nanase tsubasa the double emergency alert  the formation just before 5 am  a faint  continuous electronic noise  both tents stir  she pokes out of hers   an emergency alert  continuous  echoing twice out of sync   can you hear something   yes  it s faint  but i can hear an electronic noise of some sort   do you think it might be an emergency alert   it s definitely possible   it doesn t sound like it s going to stop any time soon  does it   the school will locate you through the gps in your watch and send help to your position   if i m not mistaken  after five minutes   couldn t we go find them before the school arrives   why would we do that  although it s not pitch black outside anymore  the visibility is still poor  and if we re careless  we might run into danger ourselves   do you need a reason to go help someone   if we re going to take action  it d be better to have more people on board  let s wake up sudo and the others  the formation   her override of ike s volunteer  she and ak take flashlights  she ll be behind him   given that it s still fairly dark out  i cannot allow a technically unreliable person to take the lead  the job should be left to someone with good crisis management skills and the discernment to select an optimal route   well  but ya know  outta all of us  i think i m prolly the best one to   ayanokoji senpai  could i ask you to lead us  i d be willing to follow your judgment without hesitation   nanase  ike  and i will each take a flashlight  nanase will be behind me  followed by sudo and hondo  ike  i ll have you take up the rear","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p164-1\"><h3><span class=\"ttl\">The double Emergency Alert; the formation<\/span><span class=\"meta\">Y2V3 · p.164–167<\/span><\/h3><p class=\"setup\">Just before 5 AM; a faint, continuous electronic noise; both tents stir; she pokes out of hers — an Emergency Alert (continuous, echoing twice out of sync). The formation — her override of Ike&#x27;s volunteer; she and AK take flashlights; she&#x27;ll be behind him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Can you hear something?”<span class=\"pg\">p.164<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Yes… it’s faint, but I can hear an electronic noise of some sort.”<span class=\"pg\">p.164<\/span><\/li><li class=\"q spoken\">“Do you think it might be an Emergency Alert?”<span class=\"pg\">p.164<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It’s definitely possible.”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It doesn’t sound like it’s going to stop any time soon, does it?”<span class=\"pg\">p.164<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The school will locate you through the GPS in your watch and send help to your position?”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I’m not mistaken, after five minutes─”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Couldn’t we go find them before the school arrives?”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why would we do that? Although it’s not pitch black outside anymore, the visibility is still poor. And if we’re careless, we might run into danger ourselves.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you need a reason to go help someone?”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we’re going to take action, it’d be better to have more people on board. Let’s wake up Sudō and the others.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Given that it’s still fairly dark out, I cannot allow a technically unreliable person to take the lead. The job should be left to someone with good crisis management skills and the discernment to select an optimal route.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, but ya know… Outta all of us, I think I’m prolly the best one to─”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-senpai, could I ask you to lead us? I’d be willing to follow your judgment without hesitation.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nanase, Ike, and I will each take a flashlight. Nanase will be behind me, followed by Sudō and Hondō. Ike, I’ll have you take up the rear.”<span class=\"pg\">p.166<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p161-1\">← Before: Nanase named at the interrogation<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p167-1\">→ After: The search; Komiya and Kinoshita found<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p167-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"sudou-ken hondou-ryoutaro ayanokouji-kiyotaka komiya-kyogo ike-kanji nanase-tsubasa","q":"nanase tsubasa the search  komiya and kinoshita found into the forest  two distinct alerts  they comb the area  a fallen boy  komiya  a second body a few meters off  kinoshita  both left legs ruined  the mystery gate reader footprints   if someone s there  respond to us   why aren t they sayin  anything  d do you think this might be the work of a g ghost   peculiar  well  it certainly sounds eerie  that s prolly just cuz we ve been sloggin  through this dark ass forest though   no  that s not what i   you re talking about the frequency  right nanase   at first  i thought that the noise was simply echoing because it was coming from deep within the forest  but now that we re closer  i realized that that s not the case  rather  i m fairly certain that it s actually two different sounds   is that  komiya   kinoshita senpai won t regain consciousness either  but  judging from all the dirt and scratches on her jersey  i m afraid that  komiya groans  she gives the worst case verdict on the legs  she whispers the oddness of it straight to ak   m my leg  it hurts   it isn t just komiya senpai  kinoshita senpai s left leg seems to be in terrible shape as well  worst case scenario  it may even be broken   something seems a bit off  don t you think   you re right  they might ve gotten caught up in trouble of some sort   i i don t know  it just happened out of nowhere  i suddenly felt something strike my calf and the next thing i knew i was rolling down the slope  agh   your calf was hit by something   m maybe  i don t really remember very well  sorry   kinoshita fell as well and ended up beside you  do you know anything about what happened to her   eh  n no  i have no idea  why is kinoshita here  if i remember correctly  when it happened we   that s right  satsuki  where s satsuki  did she fall too   shinohara is missing  were you guys not moving together   satsuki was  agh   n no  i m worried about satsuki  sorry sudo  but can you help me sit up   y yeah  but don t overdo it   komiya  where s shinohara   i don t know  we  we were trying to move quickly   then  we were waiting  for satsuki to come back   you were waiting  what  i don t understand what you re sayin  here   let me start from the beginning  we were in a hurry because we missed the last two designated areas yesterday  after talking it out last night  we ultimately decided to try and close the distance early this morning  it was still fairly dark when we set out  so we were keeping tabs on each other as we traveled  but  at some point  satsuki said she needed to go to the restroom  so she split off for a bit while kinoshita and i waited for her to finish  of course  we were using our flashlights to keep track of each other   that s when something hit your calf  yes   i remember it hurt like hell  but the pain didn t last long  cause the next thing i knew i was rolling down the slope  and then  when i came to  sudo and the rest of you guys were here","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p167-1\"><h3><span class=\"ttl\">The search; Komiya and Kinoshita found<\/span><span class=\"meta\">Y2V3 · p.167–176<\/span><\/h3><p class=\"setup\">Into the forest; two distinct alerts; they comb the area; a fallen boy (Komiya); a second body a few meters off (Kinoshita); both left legs ruined; the mystery gate-reader footprints. Komiya groans; she gives the worst-case verdict on the legs; she whispers the oddness of it straight to AK.<\/p><p class=\"with\">with <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"hondou-ryoutaro.html\">Hondō Ryōtaro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"komiya-kyogo.html\">Komiya Kyogo<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “If someone’s there, respond to us-!”<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hondō Ryōtaro<\/b> “Why aren’t they sayin’ anything…? D-do you think this might be the work of a g-ghost?”<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hondō Ryōtaro<\/b> “Peculiar? Well, it certainly sounds eerie. That’s prolly just cuz we’ve been sloggin’ through this dark-ass forest though…”<span class=\"pg\">p.168<\/span><\/li><\/ul><details class=\"more\"><summary>26 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No, that’s not what I─”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re talking about the frequency, right Nanase?”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At first, I thought that the noise was simply echoing because it was coming from deep within the forest. But now that we’re closer, I realized that that’s not the case. Rather, I’m fairly certain that it’s actually two different sounds.”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that… Komiya!?”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kinoshita-senpai won’t regain consciousness either. But, judging from all the dirt and scratches on her jersey, I’m afraid that…”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “M-my leg… it hurts…!”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It isn’t just Komiya-senpai, Kinoshita-senpai’s left leg seems to be in terrible shape as well. Worst case scenario, it may even be broken.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Something seems a bit off, don’t you think?”<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re right. They might’ve gotten caught up in trouble of some sort.”<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-I don’t know… it just happened out of nowhere. I suddenly felt something strike my calf and the next thing I knew I was rolling down the slope… Agh…!”<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your calf was hit by something?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “M-maybe? I don’t really remember very well… Sorry.”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kinoshita fell as well and ended up beside you. Do you know anything about what happened to her?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh…? N-no, I have no idea. Why is Kinoshita here…? If I remember correctly, when it happened we…”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s right…! Satsuki, where’s Satsuki!? Did she fall too!?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shinohara is missing. Were you guys not moving together?”<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Satsuki was─ Agh…!!”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “N-no, I’m worried about Satsuki… Sorry Sudō, but can you help me sit up…?”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Y-yeah. But don’t overdo it.”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Komiya, where’s Shinohara!?”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I don’t know… We… We were trying to move quickly…”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, we were waiting… for Satsuki to come back…”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You were waiting? What? I don’t understand what you’re sayin’ here!”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me start from the beginning. We were in a hurry because we missed the last two designated areas yesterday. After talking it out last night, we ultimately decided to try and close the distance early this morning… It was still fairly dark when we set out, so we were keeping tabs on each other as we traveled, but… at some point, Satsuki said she needed to go to the restroom, so she split off for a bit while Kinoshita and I waited for her to finish. Of course, we were using our flashlights to keep track of each other…”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s when something hit your calf, yes?”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I remember it hurt like hell… But the pain didn’t last long ‘cause the next thing I knew I was rolling down the slope… And then, when I came to, Sudō and the rest of you guys were here.”<span class=\"pg\">p.176<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p164-1\">← Before: The double Emergency Alert; the formation<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p177-1\">→ After: After the presence (her POV)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p177-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka sudou-ken nanase-tsubasa","q":"nanase tsubasa after the presence  her pov  ak says  i ll leave the tablet with you  wait here    he follows ike up the slope  she waits  fearing nobody answers  she leaves ak with the tablet he left her  no   he kept his  no   i ll leave the tablet with you  wait here until we get back    she gets the tablet  she spots the presence watching  suspicion builds  she throws herself after it   i know  i ll leave the tablet with you  wait here until we get back   but won t you be in trouble if you get lost without the tablet  senpai   it ll just get in the way of climbing the slope  her pov  she gently lays kinoshita down  stares into the forest  a viscous  demanding aura  they ve been watching since ak left  she sets the tablet down  sprints  the gap holds at 10 20 meters  she grabs the jersey cuff  so fast  the nimble escape  the hair from a split second   distinct  characteristic color and style  a memory of a name she has seen before  her foot catches a tree root  the reveal of the outcome  she believes they pushed komiya and kinoshita  don t tell me  they  pushed komiya senpai and kinoshita senpai  but  why   hey  what s wrong   sudou senpai  please take care of them until i m back    her pov   eh  wha  hey   so fast   damn   please wait  i simply want to talk to you   the reason those two are hurt so badly is because of something you did  isn t it   what  you   dammit   don t tell me  they  pushed komiya senpai and kinoshita senpai  but  why","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p177-1\"><h3><span class=\"ttl\">After the presence (her POV)<\/span><span class=\"meta\">Y2V3 · p.177–188<\/span><\/h3><p class=\"setup\">AK says “I’ll leave the tablet with you. Wait here” — he follows Ike up the slope; she waits; fearing nobody answers, she leaves AK with the tablet he left her? no — he kept his? no: “I’ll leave the tablet with you. Wait here until we get back.” — she gets the tablet; she spots the presence watching; suspicion builds; she throws herself after it. Her POV: she gently lays Kinoshita down; stares into the forest; a viscous, demanding aura; they&#x27;ve been watching since AK left; she sets the tablet down; sprints; the gap holds at 10–20 meters; she grabs the jersey cuff (“So fast!”); the nimble escape; the hair from a split second — distinct, characteristic color and style; a memory of a name she has seen before; her foot catches a tree root; the reveal of the outcome; she believes they pushed Komiya and Kinoshita (“Don’t tell me… They… pushed Komiya-senpai and Kinoshita-senpai…? But, why…?”).<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I know. I’ll leave the tablet with you. Wait here until we get back.”<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\">“But won’t you be in trouble if you get lost without the tablet, Senpai?”<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’ll just get in the way of climbing the slope.”<span class=\"pg\">p.177<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Hey, what’s wrong?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sudou-senpai! Please take care of them until I’m back!” ✓ her POV.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Wha, hey!”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So fast!”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Damn!”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Please wait! I simply want to talk to you!”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The reason those two are hurt so badly is because of something you did, isn’t it!?”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What, you!?”<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Dammit…!”<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t tell me… They… pushed Komiya-senpai and Kinoshita-senpai…? But, why…?”<span class=\"pg\">p.187<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p167-1\">← Before: The search; Komiya and Kinoshita found<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p188-1\">→ After: The road back; the first-years; Sakagami&#x27;s pressure<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p188-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka dogami-mitsuko sakagami chabashira-sae ike-kanji shinohara-satsuki nanase-tsubasa","q":"nanase tsubasa the road back  the first years  sakagami s pressure after the failure  she returns walking alone  ak finds her  she deflects his  nothing  her genuine sigh of relief on finding shinohara safe  they take the reins   why are you here nanase   that  uhm  i wasn t able to see you and ike senpai anymore so i decided to go looking for you   are you searching for something   no  please don t worry about it   i m glad that you managed to find shinohara senpai safe and sound   sudo senpai and the others are this way   it seems that shinohara and her friends passed a group of first years last night   first years  you say   that s true  though  i wonder who the first year students in question are  if we knew  then we might be able to poke around for information or at least find some clues   senpai  if  there really was someone out there willing to cause such a grievous injury  isn t it strange that komiya senpai didn t notice anybody   yeah  normally  you d know if someone was there or not   if it were you  ayanokoji senpai  would you be able to do it without the two of them noticing   me  don t be unreasonable   as for me  if i were to attack komiya senpai and kinoshita senpai  i don t think it would be impossible  well  depending on the timing  though  of course  it would still be fairly difficult   that said  it s not clear why they were attacked in the first place   there s been a bit of trouble  these two fell down the slope and got injured pretty badly  the four first years arrive  the school officials  the gps readout  shinohara presses on in tears  sakagami s verdict  an awfully convenient tale you ve spun  chabashira explains the gps timing  ak asks chabashira to investigate discreetly  her nod   uhm  has something happened here   we were camping nearby when we heard an alert go off and what sounded like somebody shouting  we chose to wait a little for it to get brighter out before coming here to check on what had happened  just in case   anyway  could i ask if the injured are alright   let s get down to business and hear what happened here  shall we   from a cursory observation  it seems like it ll be difficult for komiya and kinoshita to continue the exam   yes  their retirement seems virtually unavoidable   was it just a simple accident   well  i imagine we ll find out soon enough   crying isn t going to get us anywhere  i hope you know that   uhm  is it alright if i explain  shinohara told me what happened   well  i suppose that s fine  go ahead and speak   shinohara said that they were pushed off the slope   pushed off   how awfully unsettling   so they won t have to retire because of that  right  that s right  right   if that s the truth  then yes  of course they won t   what do you mean  if that s the truth  shinohara said so herself   then  i assume she must have evidence of some sort to back that up  yes   so how about it  shinohara san  you can t just keep crying  so how about you give us an answer   i it was dark   dark  so dark that you couldn t see the culprit s face   so  it was dark to the extent that you couldn t see their face  and yet you were able to see them get pushed without any problems  it pains me to say this  but that s an awfully convenient tale you ve spun  now isn t it   shinohara would never lie   you re her classmate  it s only natural that you would say that   are you saying that you don t believe her   if she s telling the truth  then this is quite a serious matter  however  this testimony alone is not enough   how could you  then what s gonna happen to komiya and kinoshita   no matter how things play out  i d say that their only real option is retirement  as their homeroom teacher  i certainly can t say i m happy to see them withdraw from the exam either  but from the look of their legs  it would be impossible for them to continue   given the current situation  we have no choice but to conclude that shinohara san is lying in order to gloss over the injuries caused by this accident   you re fuckin  kidding me  who in their right mind would buy that bullshit   i ll overlook that careless outburst of yours just this once  are we clear   tsk   it seems that you already had a lot of this figured out before you got here  chabashira sensei   we relied on komiya and kinoshita s gps signals to get here  komiya s emergency alert went off at 4 56 24 am  whereas kinoshita s went off seven seconds later  the only other signal that was in the nearby area in that timeframe was shinohara s and shinohara s alone   the first to arrive at the scene after the alerts went off was a group of five students  yourself included  the next to arrive was a group of four first year students  we were the last to arrive   yeah  we ll do a more detailed examination of their injuries back on the ship","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p188-1\"><h3><span class=\"ttl\">The road back; the first-years; Sakagami&#x27;s pressure<\/span><span class=\"meta\">Y2V3 · p.188–195<\/span><\/h3><p class=\"setup\">After the failure, she returns walking alone; AK finds her; she deflects his “nothing”; her genuine sigh of relief on finding Shinohara safe; they take the reins. The four first-years arrive; the school officials; the GPS readout; Shinohara presses on in tears; Sakagami&#x27;s verdict (“an awfully convenient tale you&#x27;ve spun”); Chabashira explains the GPS timing; AK asks Chabashira to investigate discreetly; her nod.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"index.html#dogami-mitsuko\">Dogami Mitsuko<\/a> · <a href=\"sakagami.html\">Sakagami<\/a> · <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"shinohara-satsuki.html\">Shinohara Satsuki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Why are you here Nanase?”<span class=\"pg\">p.188<\/span><\/li><li class=\"q spoken\">“That─ Uhm, I wasn’t able to see you and Ike-senpai anymore so I decided to go looking for you…”<span class=\"pg\">p.189<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Are you searching for something?”<span class=\"pg\">p.189<\/span><\/li><\/ul><details class=\"more\"><summary>48 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No, please don’t worry about it.”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m glad that you managed to find Shinohara-senpai safe and sound.”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sudō-senpai and the others are this way.”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems that Shinohara and her friends passed a group of first-years last night.”<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “First-years, you say?”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s true. Though, I wonder who the first-year students in question are? If we knew, then we might be able to poke around for information or at least find some clues.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai. If… there really was someone out there willing to cause such a grievous injury, isn’t it strange that Komiya-senpai didn’t notice anybody?”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. Normally, you’d know if someone was there or not.”<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it were you, Ayanokōji-senpai, would you be able to do it without the two of them noticing?”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Me? Don’t be unreasonable.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As for me… If I were to attack Komiya-senpai and Kinoshita-senpai… I don’t think it would be impossible. Well, depending on the timing. Though, of course, it would still be fairly difficult.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, it’s not clear why they were attacked in the first place.”<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s been a bit of trouble. These two fell down the slope and got injured pretty badly.”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uhm~… Has something happened here?”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We were camping nearby when we heard an alert go off and what sounded like somebody shouting… We chose to wait a little for it to get brighter out before coming here to check on what had happened, just in case.”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, could I ask if the injured are alright?”<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let’s get down to business and hear what happened here, shall we?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From a cursory observation, it seems like it’ll be difficult for Komiya and Kinoshita to continue the exam.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Their retirement seems virtually unavoidable.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Was it just a simple accident?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well… I imagine we’ll find out soon enough.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Crying isn’t going to get us anywhere, I hope you know that.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uhm, is it alright if I explain? Shinohara told me what happened.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Well, I suppose that’s fine. Go ahead and speak.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shinohara said that they were pushed off the slope.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Pushed off? …How awfully unsettling.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So they won’t have to retire because of that, right? That’s right, right?”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If that’s the truth, then yes, of course they won’t.”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean ‘if that’s the truth’? Shinohara said so herself!”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, I assume she must have evidence of some sort to back that up, yes?”<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So how about it, Shinohara-san? You can’t just keep crying, so how about you give us an answer?”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-it was dark…”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Dark? So dark that you couldn’t see the culprit’s face?”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, it was dark to the extent that you couldn’t see their face, and yet you were able to see them get pushed without any problems…? It pains me to say this, but that’s an awfully convenient tale you’ve spun, now isn’t it?”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shinohara would never lie!”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re her classmate. It’s only natural that you would say that.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you saying that you don’t believe her!?”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If she’s telling the truth, then this is quite a serious matter. However, this testimony alone is not enough.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How could you! Then what’s gonna happen to Komiya and Kinoshita!?”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No matter how things play out, I’d say that their only real option is retirement. As their homeroom teacher, I certainly can’t say I’m happy to see them withdraw from the exam either, but from the look of their legs, it would be impossible for them to continue.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Given the current situation, we have no choice but to conclude that Shinohara-san is lying in order to gloss over the injuries caused by this accident.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re fuckin’ kidding me! Who in their right mind would buy that bullshit!?”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll overlook that careless outburst of yours just this once. Are we clear?”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsk…!”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems that you already had a lot of this figured out before you got here, Chabashira-sensei.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We relied on Komiya and Kinoshita’s GPS signals to get here. Komiya’s Emergency Alert went off at 4:56:24 AM, whereas Kinoshita’s went off seven seconds later. The only other signal that was in the nearby area in that timeframe was Shinohara’s and Shinohara’s alone.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The first to arrive at the scene after the alerts went off was a group of five students, yourself included. The next to arrive was a group of four first-year students. We were the last to arrive.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. We’ll do a more detailed examination of their injuries back on the ship.”<span class=\"pg\">p.199<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p177-1\">← Before: After the presence (her POV)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p199-1\">→ After: Komiya&#x27;s blessing; her bunker advice; her stay<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p199-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"shinohara-satsuki komiya-kyogo sudou-ken chabashira-sae ike-kanji hondou-ryoutaro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa komiya s blessing  her bunker advice  her stay komiya calls ike in close   show me how much of a man you are  her bunker recommendation to shinohara  chabashira endorses  shinohara bursts into tears and bolts  ike gives chase  she refuses him   i i can t go on like this  there s no way i can do this alone   ike  come here real quick   show me how much of a man you are   that s gotta be tough   it s possible to lighten the burden by bunkering down near the starting area  while you won t be able to earn points from reaching designated areas  it should definitely be more than enough to help you avoid retirement   shinohara  i don t want it to sound like i m expecting you to get expelled  but  what s your plan  it ll be difficult to continue with the exam on your own   i i know   then  like nanase said  you can at least head back to the harbor and hold out until the end of the exam  it s not like it would be impossible for you to pick up the tasks that show up in the nearby area either   i hope that  somehow  you re able to make it to the starting area on your own   yes  understood   are you really just gonna go back to the starting area and wait there   what other choice do i have  komiya kun and kinoshita san aren t here anymore  there s absolutely no way i can make it through this special exam on my own   i m just gonna be expelled anyway  so leave me alone   i  i ll do something about it   just stop  it s impossible  absolutely impossible   it s not impossible   why not  this has nothing to do with you ike  with me outta the way  there ll be less of a chance for your group to get expelled  you should be happy   happy  what kind of shit are you spouting  there s no way i d be happy   i mean  we ll lose a whole lotta class points if you get expelled  i ve  uhm  you know  i ve gotta stop that from happening  that s why i ll lend you a hand to make sure   well  that s true  but  what ll you do if your group sinks down to the bottom because you re helping me  not to mention  it ll just end up making trouble for sudo kun and hondo kun   ike  you never think things through  do you  if you keep going on like that  then sooner or later you re gonna get yourself expelled   anyway  i m not going to give up until the very end  so you should do your best too ike   w wait   kanji   wait  i said wait   m my god  you scared me  i heard you already  jeez  is there still something you want from me   there is  there s all sorts of stuff  i really don t want you to get expelled  that s why i m gonna save you whether you like it or not   right oh  if this is how kanji wants to do it  let s discuss battle plans  ryotaro   g gotcha  her lecture  three extra slots  merging math  her nod at the challenge  his withdrawal  her consent to accompany him to g3  the standings reveal  bottom ten  seven 3 b 3 d  akito s group ninth from bottom with 28 points   in order to guarantee that you save shinohara  she ll have to join up with a group with at least three slots for extra group members   but wouldn t it be better to assume that there won t be any tasks that she can win by herself  she d prolly end up having to pin her hopes on getting lucky or some kinda freak coincidence where there aren t enough participants or something    speaker untagged in the print  recorded unassigned   is there really no way for her to get into a group smoothly  ayanokoji   it s not like it s impossible  there is one idea that comes to mind that has a high probability of working out   r really  what is it   o oi  ayanokoji  what s this plan of yours   the only thing you can do right now is have ike take the lead in protecting shinohara and focus on earning as many points as possible  beyond that  you should try to take part in tasks that increase the maximum number of people allowed in your group if you get the chance   what are you gonna be doing    speaker untagged in the print  recorded unassigned   i ll be setting up a contingency plan of sorts just in case something goes wrong   but  like i said earlier  there s no way to guarantee anything here  furthermore  if any of our other classmates were to fall into the bottom five as well  then  we might be forced to make a tough choice about who to save   don t forget that  ike   i won t   sudo  take care of ike and the others  out of everyone  you re the one capable of making the most sensible decisions   r right  leave it to me   it seems that some of your classmates are in a dangerous position  senpai   all things considered  it s surprising  to think so many third year students would be at the bottom   to start out i m going to aim for the arrival bonus at g3  but  i ll probably skip the designated areas that come after that for a while   so there s somewhere you want to go  even if it means missing out on the designated areas   yeah  if you want to continue going for them  then we ll have to split up at g3   no no  i ll stay with you  as long as amasawa san or hosen kun arrive in time  my group won t miss out on the area  besides  this has to do with the plan you ve thought of to save shinohara senpai  right","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p199-1\"><h3><span class=\"ttl\">Komiya&#x27;s blessing; her bunker advice; her stay<\/span><span class=\"meta\">Y2V3 · p.199–210<\/span><\/h3><p class=\"setup\">Komiya calls Ike in close: “Show me how much of a man you are.”; her bunker recommendation to Shinohara; Chabashira endorses; Shinohara bursts into tears and bolts; Ike gives chase; she refuses him. Her lecture (three extra slots; merging math; her nod at the challenge); his withdrawal; her consent to accompany him to G3; the standings reveal (bottom ten: seven 3-B/3-D; Akito&#x27;s group ninth-from-bottom with 28 points).<\/p><p class=\"with\">with <a href=\"shinohara-satsuki.html\">Shinohara Satsuki<\/a> · <a href=\"komiya-kyogo.html\">Komiya Kyogo<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a> · <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"ike-kanji.html\">Ike Kanji<\/a> · <a href=\"hondou-ryoutaro.html\">Hondō Ryōtaro<\/a> <span class=\"n\">+1 more<\/span><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shinohara Satsuki<\/b> “I-I can’t go on like this…! There’s no way I can do this alone…!”<span class=\"pg\">p.199<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Komiya Kyogo<\/b> “Ike… come here real quick.”<span class=\"pg\">p.200<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Komiya Kyogo<\/b> “Show me how much of a man you are.”<span class=\"pg\">p.200<\/span><\/li><\/ul><details class=\"more\"><summary>46 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “That’s gotta be tough…”<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s possible to lighten the burden by bunkering down near the starting area. While you won’t be able to earn points from reaching designated areas, it should definitely be more than enough to help you avoid retirement.”<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shinohara. I don’t want it to sound like I’m expecting you to get expelled, but… what’s your plan? It’ll be difficult to continue with the exam on your own.”<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-I know…”<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, like Nanase said, you can at least head back to the harbor and hold out until the end of the exam. It’s not like it would be impossible for you to pick up the Tasks that show up in the nearby area either.”<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hope that, somehow, you’re able to make it to the starting area on your own.”<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes… Understood.”<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you really just gonna go back to the starting area and wait there!?”<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What other choice do I have? Komiya-kun and Kinoshita-san aren’t here anymore… There’s absolutely no way I can make it through this special exam on my own.”<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m just gonna be expelled anyway, so leave me alone!”<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I… I’ll do something about it!”<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just stop. It’s impossible. Absolutely impossible.”<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not impossible!”<span class=\"pg\">p.202<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why not!? This has nothing to do with you Ike! With me outta the way, there’ll be less of a chance for your group to get expelled… You should be happy!”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Happy? What kind of shit are you spouting!? There’s no way I’d be happy!”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I mean, we’ll lose a whole lotta class points if you get expelled! I’ve, uhm, you know, I’ve gotta stop that from happening! That’s why I’ll lend you a hand to make sure!”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, that’s true, but… What’ll you do if your group sinks down to the bottom because you’re helping me? Not to mention, it’ll just end up making trouble for Sudō-kun and Hondō-kun.”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ike, you never think things through, do you? If you keep going on like that, then sooner or later you’re gonna get yourself expelled.”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, I’m not going to give up until the very end, so you should do your best too Ike.”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “W-wait…!”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kanji.”<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, I said wait!”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “M-my god, you scared me. I heard you already, jeez… Is there still something you want from me?”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is! There’s all sorts of stuff! I really don’t want you to get expelled! That’s why I’m gonna save you whether you like it or not!”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right-oh! If this is how Kanji wants to do it, let’s discuss battle plans, Ryōtarō!”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “G-gotcha!”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In order to guarantee that you save Shinohara, she’ll have to join up with a group with at least three slots for extra group members.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “But wouldn’t it be better to assume that there won’t be any Tasks that she can win by herself? She’d prolly end up having to pin her hopes on getting lucky or some kinda freak coincidence where there aren’t enough participants or something.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is there really no way for her to get into a group smoothly, Ayanokōji?”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s not like it’s impossible. There is one idea that comes to mind that has a high probability of working out.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “R-really? What is it!?”<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “O-oi, Ayanokōji? What’s this plan of yours?”<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The only thing you can do right now is have Ike take the lead in protecting Shinohara and focus on earning as many points as possible. Beyond that, you should try to take part in Tasks that increase the maximum number of people allowed in your group if you get the chance.”<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “What are you gonna be doing?” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll be setting up a contingency plan of sorts just in case something goes wrong.”<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, like I said earlier, there’s no way to guarantee anything here. Furthermore, if any of our other classmates were to fall into the bottom five as well, then… we might be forced to make a tough choice about who to save.”<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t forget that, Ike.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I won’t.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sudō, take care of Ike and the others. Out of everyone, you’re the one capable of making the most sensible decisions.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “R-right, leave it to me.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems that some of your classmates are in a dangerous position, Senpai.”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “All things considered, it’s surprising. To think so many third-year students would be at the bottom…”<span class=\"pg\">p.208<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To start out I’m going to aim for the Arrival Bonus at G3. But, I’ll probably skip the designated areas that come after that for a while.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So there’s somewhere you want to go, even if it means missing out on the designated areas?”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah. If you want to continue going for them, then we’ll have to split up at G3.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No no, I’ll stay with you. As long as Amasawa-san or Hōsen-kun arrive in time, my group won’t miss out on the area… Besides, this has to do with the plan you’ve thought of to save Shinohara-senpai, right?”<span class=\"pg\">p.209<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p188-1\">← Before: The road back; the first-years; Sakagami&#x27;s pressure<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p211-1\">→ After: Day 5: south along the river; the fisherman<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p211-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa day 5  south along the river  the fisherman day 5 at just before 7 am  pushing south along the river from d4 to d5  four areas missed in a row  i8 first designation of the day  shinohara s bottom eight status  nagumo first  kiriyama second  she points out a fisherman  they approach quietly   ah  senpai  there s someone fishing up ahead   mind if we make a detour  nanase   i m just your travelling companion  ayanokoji senpai  please don t feel the need to ask for my opinion","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p211-1\"><h3><span class=\"ttl\">Day 5: south along the river; the fisherman<\/span><span class=\"meta\">Y2V3 · p.211–213<\/span><\/h3><p class=\"setup\">Day 5 at just before 7 AM; pushing south along the river from D4 to D5; four areas missed in a row (I8 first designation of the day); Shinohara&#x27;s bottom-eight status; Nagumo first; Kiriyama second; she points out a fisherman; they approach quietly.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ah, Senpai. There’s someone fishing up ahead.”<span class=\"pg\">p.212<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Mind if we make a detour, Nanase?”<span class=\"pg\">p.212<\/span><\/li><li class=\"q spoken\">“I’m just your travelling companion, Ayanokōji-senpai. Please don’t feel the need to ask for my opinion.”<span class=\"pg\">p.212<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p199-1\">← Before: Komiya&#x27;s blessing; her bunker advice; her stay<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p213-1\">→ After: Katsuragi and Ryūen; the plan table; her dismissal<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p213-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"katsuragi-kouhei ayanokouji-kiyotaka ryuuen-kakeru nanase-tsubasa","q":"nanase tsubasa katsuragi and ryuen  the plan table  her dismissal two class 2 b students  the komiya kinoshita retirement  the plan pitched to ryuen behind her back  she is sent away from the sidebar   you started off on your own  but it doesn t seem like you ve dropped to the bottom ten yet   somehow  but if i took it easy for a day  my rank would probably plummet   so you re strollin   round the island with a lass on your arm  eh  you get tired of that karuizawa chick and ditch her   karuizawa  why are you bringing her up   kuku  it s nothin  don t mind it   it seems you two have been doing pretty well for yourselves   oh shove it with the sarcasm  isn t that freak with a few screws loose one of your classmates   well  that s true   what s your next designated area   hah   it s already past 7 00 am  you two sure seem to be taking it easy   we ve been moving at a rapid pace these past four days as we worked on tasks and map movement  that being said  our first designated area today turned out to be the random designation down in e10  so we d have to push ourselves fairly hard if we wanted to arrive within the time limit  i decided that the one or two points we d get for making it there wouldn t be worth the effort   so  have you caught anything   sadly  not much  we d have to go to the sea if we wanted to catch a lot of fish   i take it you re doing fine on the food front  then   there s plenty of food to gather from the sea  rivers  and forest  water is no different too since all you have to do is boil river water   but isn t it risky to drink river water    speaker untagged in the print  recorded unassigned   you re not wrong  boiling it doesn t guarantee that it s perfectly safe  but that s why i m the only one who drinks it  ryuen drinks the water we started out with and whatever we get from tasks   it just so happens that i ve been looking for you  ryuen   lookin  for me  eh   i assume you re aware of which groups are in the bottom ten right now  right   well  sure  i dunno what those idiots from my class are doin  down there in the bottom eight though   komiya and kinoshita retired   they retired  what happened   they were seriously injured  it s unlikely that either of them will be able to walk anytime soon    hers   per the print   was it an accident   well  that s    hers  cut off by ak    per the print   according to shinohara  the last remaining member of their group  they were attacked by someone   i assume this  someone  was kicked outta here right along with  em then  right   unfortunately  shinohara s testimony was the only evidence they had  neither komiya nor kinoshita could recall whether they were actually attacked or not  the school should still be investigating it  but i wouldn t get my hopes up   they re looking at it under the pretense that shinohara senpai lied because she didn t want her fellow group members to retire    speaker untagged in the print  recorded unassigned   what should we do ryuen  even if we manage to place in the top three  it ll be meaningless if komiya and kinoshita get expelled   you said you were lookin  for me  right  shinohara s your classmate  so i assume you ve already come up with a plan to stop the expulsions  or am i wrong   sorry nanase  but i can t let you listen to the rest of this conversation  the survival of the second years is at stake here   i understand    hers   per the print   kuku  i see  with a plan like that there really is a way for shinohara to survive  that said  will it all go smoothly   it should have a decent chance as long as you cooperate  the rest will happen naturally   you ve got balls changing shit up like this  if the other groups realize what s happening  they ll start takin  action too   there are some clever first year students out there as well  there s a chance that they might catch on sooner than anticipated    speaker untagged in the print  recorded unassigned   if it were a couple of small fry i wouldn t even hesitate to let  em go  but komiya and kinoshita still have their uses   so you ll work with me  is that what you re saying   our interests align so there s no way i wouldn t take advantage of this strat of yours   if you run into ichinose  can you tell her the plan as well   that doormat ichinose aside  i don t think sakayanagi ll choose to lend a hand so easily   she s not the type to sit back and let the first years look down on her    speaker untagged in the print  recorded unassigned   kuku  i guess so","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p213-1\"><h3><span class=\"ttl\">Katsuragi and Ryūen; the plan table; her dismissal<\/span><span class=\"meta\">Y2V3 · p.213–219<\/span><\/h3><p class=\"setup\">Two Class 2-B students; the Komiya/Kinoshita retirement; the plan pitched to Ryūen behind her back; she is sent away from the sidebar.<\/p><p class=\"with\">with <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “You started off on your own, but it doesn’t seem like you’ve dropped to the bottom ten yet.”<span class=\"pg\">p.213<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Somehow. But if I took it easy for a day, my rank would probably plummet.”<span class=\"pg\">p.213<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “So you’re strollin’ ‘round the island with a lass on your arm, eh? You get tired of that Karuizawa chick and ditch her?”<span class=\"pg\">p.213<\/span><\/li><\/ul><details class=\"more\"><summary>43 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Karuizawa? Why are you bringing her up?”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku, it’s nothin’. Don’t mind it.”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems you two have been doing pretty well for yourselves.”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh shove it with the sarcasm. Isn’t that freak with a few screws loose one of your classmates?”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, that’s true.”<span class=\"pg\">p.213<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What’s your next designated area?”<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hah?”<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s already past 7:00 AM. You two sure seem to be taking it easy.”<span class=\"pg\">p.214<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’ve been moving at a rapid pace these past four days as we worked on Tasks and map movement. That being said, our first designated area today turned out to be the random designation down in E10, so we’d have to push ourselves fairly hard if we wanted to arrive within the time limit. I decided that the one or two points we’d get for making it there wouldn’t be worth the effort.”<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, have you caught anything?”<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sadly, not much. We’d have to go to the sea if we wanted to catch a lot of fish.”<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I take it you’re doing fine on the food front, then?”<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s plenty of food to gather from the sea, rivers, and forest. Water is no different too since all you have to do is boil river water.”<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “But isn’t it risky to drink river water?” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not wrong. Boiling it doesn’t guarantee that it’s perfectly safe, but that’s why I’m the only one who drinks it. Ryūen drinks the water we started out with and whatever we get from Tasks.”<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It just so happens that I’ve been looking for you, Ryūen.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Lookin’ for me, eh?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I assume you’re aware of which groups are in the bottom ten right now, right?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, sure. I dunno what those idiots from my class are doin’ down there in the bottom eight though.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Komiya and Kinoshita retired.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They retired? What happened?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They were seriously injured. It’s unlikely that either of them will be able to walk anytime soon.” — hers ✓ per the print.<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Was it an accident?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, that’s─” — hers, cut off by AK. ✓ per the print.<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “According to Shinohara, the last remaining member of their group, they were attacked by someone.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I assume this ‘someone’ was kicked outta here right along with ‘em then, right?”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unfortunately, Shinohara’s testimony was the only evidence they had. Neither Komiya nor Kinoshita could recall whether they were actually attacked or not. The school should still be investigating it, but I wouldn’t get my hopes up.”<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “They’re looking at it under the pretense that Shinohara-senpai lied because she didn’t want her fellow group members to retire.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What should we do Ryūen? Even if we manage to place in the top three, it’ll be meaningless if Komiya and Kinoshita get expelled.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You said you were lookin’ for me, right? Shinohara’s your classmate, so I assume you’ve already come up with a plan to stop the expulsions. Or am I wrong?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry Nanase, but I can’t let you listen to the rest of this conversation. The survival of the second-years is at stake here.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand.” — hers ✓ per the print.<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku, I see. With a plan like that there really is a way for Shinohara to survive. That said… will it all go smoothly?”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It should have a decent chance as long as you cooperate. The rest will happen naturally.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ve got balls changing shit up like this. If the other groups realize what’s happening, they’ll start takin’ action too.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “There are some clever first-year students out there as well. There’s a chance that they might catch on sooner than anticipated.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it were a couple of small fry I wouldn’t even hesitate to let ‘em go, but Komiya and Kinoshita still have their uses.”<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’ll work with me… is that what you’re saying?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Our interests align so there’s no way I wouldn’t take advantage of this strat of yours.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you run into Ichinose, can you tell her the plan as well?”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That doormat Ichinose aside, I don’t think Sakayanagi’ll choose to lend a hand so easily.”<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “She’s not the type to sit back and let the first-years look down on her.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kuku, I guess so.”<span class=\"pg\">p.219<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p211-1\">← Before: Day 5: south along the river; the fisherman<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p220-1\">→ After: C5 summit: Tug of War; her girls&#x27; victory by default<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p220-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka kouenji-rokusuke nanase-tsubasa","q":"nanase tsubasa c5 summit  tug of war  her girls  victory by default a single task day   tug of war  koenji rokusuke at the summit  no pack  his swim self baptism  they register  one boy each  she is the only girl   wins by default  koenji s raw power unbeatable  the count at zero   he got here pretty quickly didn t he  he must ve been even closer than we were    speaker untagged in the print  recorded unassigned   i wonder    speaker untagged in the print  recorded unassigned   i m not sure whether this will help clear things up for you or not  but that s koenji rokusuke   koenji  the same koenji from your class who s currently in fourth place overall   well  he does seem to give off an  aura of greatness of some sort   he seems to be saying  something  is he talking to us   no  he s definitely talking to himself  he s probably just immersed in his own beauty   i is that so   it seeeeems that my opponent is you  ayanokoji boy   fufu  so you re a man who thinks about things from the perspective of efficiency  hmmmm   is  is that true  senpai   ayanokoji boy  quit overselling your worth inside that head of yours  after all  it s not every day that you ll get the chance to compete against my motivated self   now then  if you ll each take up your positions  i ll begin the countdown  you may start pulling when i get to zero    the task staff  speaker unidentified in print  recorded unassigned   to win at tug of war  one needs not these paltry parlor tricks  but raw  unbridled power   so you chose to prioritize efficiency until the bitter end  did you   it s quite unfortunate  senpai   no  even if i were to seriously face off against him  i wouldn t stand a chance  it s only natural that it ended up this way   can you keep going  nanase   if i m being honest  my legs are slightly sore   full speed ahead then   yes","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p220-1\"><h3><span class=\"ttl\">C5 summit: Tug of War; her girls&#x27; victory by default<\/span><span class=\"meta\">Y2V3 · p.220–232<\/span><\/h3><p class=\"setup\">A single-Task day — Tug of War; Kōenji Rokusuke at the summit, no pack; his swim-self baptism; they register; one boy each; she is the only girl — wins by default; Kōenji&#x27;s raw power unbeatable; the count at zero.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I’m not sure whether this will help clear things up for you or not, but that’s Kōenji Rokusuke.”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\">“Kōenji…? The same Kōenji from your class who’s currently in fourth place overall? …Well, he does seem to give off an… aura of greatness of some sort.”<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\">“He seems to be saying… something… Is he talking to us…?”<span class=\"pg\">p.221<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “He got here pretty quickly didn’t he? He must’ve been even closer than we were.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I wonder.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, he’s definitely talking to himself. He’s probably just immersed in his own beauty.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-is that so…”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seeeeems that my opponent is you, Ayanokōji-boy.”<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fufu, so you’re a man who thinks about things from the perspective of efficiency, hmmmm?”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is… Is that true, Senpai?”<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-boy, quit overselling your worth inside that head of yours. After all, it’s not every day that you’ll get the chance to compete against my motivated self.”<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Now then, if you’ll each take up your positions, I’ll begin the countdown. You may start pulling when I get to zero.” — the Task staff; speaker unidentified in print; recorded unassigned.<span class=\"pg\">p.226<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “To win at Tug of War, one needs not these paltry parlor tricks, but raw, unbridled power.”<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you chose to prioritize efficiency until the bitter end, did you?”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s quite unfortunate, Senpai.”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, even if I were to seriously face off against him, I wouldn’t stand a chance. It’s only natural that it ended up this way.”<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you keep going, Nanase?”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I’m being honest, my legs are slightly sore.”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Full speed ahead then.”<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes!”<span class=\"pg\">p.229<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p213-1\">← Before: Katsuragi and Ryūen; the plan table; her dismissal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p230-1\">→ After: The harbor; the swim entry<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p230-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the harbor  the swim entry the harbor  she enters the open water swimming at the last minute  ak goes to find someone  koenji wins his race by landslide   haaaa  i finally managed to catch up   it s hard to believe you re a first year high school girl  i didn t expect you to have so much stamina   no no  compared to me  you re not even short of breath  ayanokoji senpai  you re just as outstanding as i thought   i m just putting on a stoic front  well  that aside  take a look over there   wow  so many people   so  why did we come all the way here to the starting area  senpai   before that  let s check out the task   senpai  is  is that koenji senpai   if you want to compete in the task  you d better hurry up and register  that said  are you sure you re feeling okay   although i m reluctant to say i m in perfect condition  it s a rare opportunity  so i d like to give it my best shot   i ll be waiting over there then  come find me when it s over   will do","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p230-1\"><h3><span class=\"ttl\">The harbor; the swim entry<\/span><span class=\"meta\">Y2V3 · p.230–232<\/span><\/h3><p class=\"setup\">The harbor; she enters the Open Water Swimming at the last minute; AK goes to find someone; Kōenji wins his race by landslide.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Haaaa… I finally managed to catch up.”<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’s hard to believe you’re a first-year high school girl. I didn’t expect you to have so much stamina.”<span class=\"pg\">p.230<\/span><\/li><li class=\"q spoken\">“No no, compared to me, you’re not even short of breath, Ayanokōji-senpai… You’re just as outstanding as I thought.”<span class=\"pg\">p.231<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’m just putting on a stoic front. Well, that aside, take a look over there.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wow─! So many people!”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So… Why did we come all the way here to the starting area, Senpai?”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Before that, let’s check out the Task.”<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai… Is… Is that Kōenji-senpai?”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you want to compete in the Task, you’d better hurry up and register. That said, are you sure you’re feeling okay?”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although I’m reluctant to say I’m in perfect condition… it’s a rare opportunity, so I’d like to give it my best shot.”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll be waiting over there then. Come find me when it’s over.”<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will do!”<span class=\"pg\">p.232<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p220-1\">← Before: C5 summit: Tug of War; her girls&#x27; victory by default<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p233-1\">→ After: Nanase named at the parasol<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p233-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase named at the parasol  after seeing nanase off  i decided to leave the task registration area in    named  not present  pov ayanokoji   it should be about half an hour until the task is over and nanase san    named by sakayanagi  not present  pov ayanokoji   how do you know about nanase    named by ayanokoji  not present  pov ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p233-1\"><h3><span class=\"ttl\">Nanase named at the parasol<\/span><span class=\"meta\">Y2V3 · p.233, 235, 237<\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “After seeing Nanase off, I decided to leave the Task registration area in” — named; not present; POV Ayanokōji.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It should be about half an hour until the Task is over and Nanase-san” — named by Sakayanagi; not present; POV Ayanokōji.<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “How do you know about Nanase?” — named by Ayanokōji; not present; POV Ayanokōji.<span class=\"pg\">p.237<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p230-1\">← Before: The harbor; the swim entry<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p242-1\">→ After: Third place; the random designation; his strategy out in the open<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p242-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa third place  the random designation  his strategy out in the open she swims to third  his deliberate heat hint  his open books at last   he lays out the bottom ten complacency math and his minimal risk design  he admits she is  technically  his enemy  she soaks it in silently   that girl who took first place is my classmate onodera  she s a highly formidable opponent when it comes to swimming  so you shouldn t let the loss get to you    hmm   ak s line  fix   says ayanokouji kiyotaka   yes  onodera senpai was certainly amazing  however  the one i m truly concerned about is   he s as much a freak as he is a superhuman  thinking about him any more than necessary isn t worth the time   senpai  in terms of distance it s certainly manageable  but   it ll be hard if we try to go straight through the forest  however  we can take the beach in d8 and c8 and cut through a shorter patch of forest to the beach in b8 instead  then  if we just head north from there  we can get to b6 without too much trouble   we ve only just started and i m already thirsty    hmm   whose  untagged  flow  whoever   note   there are more groups huddled around the starting area than i expected  i wonder if that s due to the stress and difficulty that comes with living on the island for four or five days in a row  what do you think  senpai   i think that s part of it  but that s not the only reason  i d say the largest factor is the revelation of the bottom ten groups   is that so  well  the expulsion penalty only applies to the bottom five groups  and since they were given the ability to find out their current situation through their tablets on the fourth day  i suppose it makes sense that they ve grown complacent   but  even if you have a 10 to 20 point lead on the bottom five  there s no absolute guarantee that you ll be safe  right  if it were me  i d try my best to establish a 30 to 40 point lead and work to maintain it   of course  at some level  everyone knows that they should be doing it that way  after all  everyone wants to face the special exam with the resolve to give it their all from start to finish  but reality is not that kind  just like how you and i are eager to get a drink of water right now  once you get a taste of something sweet  whatever resolve you might have is bound to falter   she looked embarrassed as she spoke  as though this was a retelling of something she had experienced firsthand    narration  about her  recorded as a  note   rest is important  there are times where you ll have no choice but to overwork yourself to earn points  but the key to that is knowing when to push yourself and when to take a step back and take a break  you ultimately just have to avoid doing the same things as the majority of other students   i ve been thinking that you ve been taking on the exam fairly negligently these past few days  ayanokoji senpai  but  you ve just been conducting yourself that way because you don t want to stand out too much during the first half  haven t you   that s about right  of course  i ll bite if an adequate opportunity presents itself  but even if i made it into a highly contested task  the number of points i can earn would be limited   uhm  if i may ask  why are you telling me about your plan  up until now  it has always seemed that you ve been looking to placate or deceive me whenever the topic comes up  senpai   put simply  there s no questioning the fact you re my enemy  nanase  not only because this exam requires us to compete against each other as students from different school years  but also because there s 20 million private points in it for you for getting me expelled   that s right  after all  i tried to plot against you before  senpai   that being said  your actions so far have made it impossible for me to see you as an enemy   even though i ve acted with blatant hostility before","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p242-1\"><h3><span class=\"ttl\">Third place; the random designation; his strategy out in the open<\/span><span class=\"meta\">Y2V3 · p.242–250<\/span><\/h3><p class=\"setup\">She swims to third; his deliberate heat-hint; his open books at last — he lays out the bottom-ten complacency math and his minimal-risk design; he admits she is (technically) his enemy; she soaks it in silently.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“That girl who took first place is my classmate Onodera. She’s a highly formidable opponent when it comes to swimming, so you shouldn’t let the loss get to you.” — hmm — AK&#x27;s line. Fix: [says:ayanokouji-kiyotaka].<span class=\"pg\">p.243<\/span><\/li><li class=\"q spoken\">“Yes. Onodera-senpai was certainly amazing. However, the one I’m truly concerned about is…”<span class=\"pg\">p.243<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “He’s as much a freak as he is a superhuman. Thinking about him any more than necessary isn’t worth the time.”<span class=\"pg\">p.243<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Senpai. In terms of distance it’s certainly manageable, but…”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’ll be hard if we try to go straight through the forest. However, we can take the beach in D8 and C8 and cut through a shorter patch of forest to the beach in B8 instead. Then, if we just head north from there, we can get to B6 without too much trouble.”<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’ve only just started and I’m already thirsty.” — hmm — whose? untagged; flow: whoever; [note].<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are more groups huddled around the starting area than I expected. I wonder if that’s due to the stress and difficulty that comes with living on the island for four or five days in a row? What do you think, Senpai?”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think that’s part of it, but that’s not the only reason. I’d say the largest factor is the revelation of the bottom ten groups.”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Is that so? Well, the expulsion penalty only applies to the bottom five groups, and since they were given the ability to find out their current situation through their tablets on the fourth day, I suppose it makes sense that they’ve grown complacent…”<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, even if you have a 10 to 20 point lead on the bottom five, there’s no absolute guarantee that you’ll be safe, right? If it were me, I’d try my best to establish a 30 to 40 point lead and work to maintain it.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, at some level, everyone knows that they should be doing it that way. After all, everyone wants to face the special exam with the resolve to give it their all from start to finish. But reality is not that kind. Just like how you and I are eager to get a drink of water right now, once you get a taste of something sweet, whatever resolve you might have is bound to falter.”<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “She looked embarrassed as she spoke, as though this was a retelling of something she had experienced firsthand.” — narration (about her); recorded as a [note].<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Rest is important. There are times where you’ll have no choice but to overwork yourself to earn points, but the key to that is knowing when to push yourself and when to take a step back and take a break. You ultimately just have to avoid doing the same things as the majority of other students.”<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve been thinking that you’ve been taking on the exam fairly negligently these past few days, Ayanokōji-senpai. But, you’ve just been conducting yourself that way because you don’t want to stand out too much during the first half, haven’t you?”<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s about right. Of course, I’ll bite if an adequate opportunity presents itself, but even if I made it into a highly contested Task, the number of points I can earn would be limited.”<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uhm, if I may ask… why are you telling me about your plan? Up until now, it has always seemed that you’ve been looking to placate or deceive me whenever the topic comes up, Senpai.”<span class=\"pg\">p.248<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Put simply, there’s no questioning the fact you’re my enemy, Nanase. Not only because this exam requires us to compete against each other as students from different school years, but also because there’s 20 million private points in it for you for getting me expelled.”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…That’s right. After all, I tried to plot against you before, Senpai.”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That being said, your actions so far have made it impossible for me to see you as an enemy.”<span class=\"pg\">p.249<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even though I’ve acted with blatant hostility before…?”<span class=\"pg\">p.249<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p233-1\">← Before: Nanase named at the parasol<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p250-1\">→ After: B5; Hamaguchi&#x27;s camp; the “Honami-chan” dinner<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p250-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka hamaguchi-tetsuya andou-sayo minamikata-kozue nanase-tsubasa","q":"nanase tsubasa b5  hamaguchi s camp  the  honami chan  dinner she collapses at b5  class reception area  a camp of three  hamaguchi tetsuya  ando sayo  minamikata kozue  the 50  head start card group  22 500 points  the yakiniku invitation  the  honami chan  gossip as they dine   phew  somehow we finally managed to make it to our last area   it seems like you ve been pushing yourself quite a lot   yo   you guys in a hurry to get somewhere   no  we ve already reached our designated area for the day  we were just thinking of finding somewhere a bit closer to the ocean   then how about you take it easy and stick around for a bit   though  you don t have to force yourself if you don t want to   well  i suppose we ll take a short break   come on over then  make yourself at home   no  no  nothin  like that  we were whisperin   bout somethin  else  it just so happens we wanted to talk with you  ayanokoji kun  so it s totally fine by us if you guys camp here tonight  right kozue   yep   eh  wait  then has there really not been any progress yet  for real   no way  i thought for sure that they d at least be at that  more than friends  less than lovers  stage by now   i know right  honami chan s been dropping his name pretty much all the time these days   is that so    speaker untagged in the print  recorded unassigned   well  like  ya know   i know it s not our place to say this an  all  but  is there even any reason why they shouldn t be going out at this point   i m not 100  certain i get what you two are going on about  but i don t think we should go out with each other   no no no no no no  what are you saying  i ll say it again just to be sure  but you do know that this is the honami chan we re talkin  about  right   i can t really speak for all the boys out there  but prolly like 80 to 90  of the second years like honami chan  right   that sounds like a safe bet to me   you two are in different classes  sure  but you don t have to let that get in the way of love  there re tons of couples out there going steady with each other regardless of their class or grade   isn t the bigger issue here the fact that ichinose isn t even interested in me   ooooo  is that modesty i see  you do know that you were quite the hit with the girls back when we first enrolled here  right ayanokoji kun   it sounds like you re quite a hit with the ladies  ayanokoji senpai   no  i m not  nothing of the sort  no girls have ever said anything like that to me before   reeeally  ah  well i can think of one time when you came up in a conversation  but the topic changed real fast   well  ain t no helpin  that  there s no way to tell if you re gonna like a guy unless you up and talk with  em face to face  and ayanokoji kun wasn t the type a  guy to talk with people a year ago   doesn t seem to me like he s changed much since then either though   ayanokoji senpai has changed a little from how he used to be  then   well  i guess in some ways he seems a lot  softer now","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p250-1\"><h3><span class=\"ttl\">B5; Hamaguchi&#x27;s camp; the “Honami-chan” dinner<\/span><span class=\"meta\">Y2V3 · p.250–259<\/span><\/h3><p class=\"setup\">She collapses at B5 (class reception area); a camp of three (Hamaguchi Tetsuya; Andō Sayo; Minamikata Kozue); the 50% Head Start card group (22,500 points); the yakiniku invitation; the “Honami-chan” gossip as they dine.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"hamaguchi-tetsuya.html\">Hamaguchi Tetsuya<\/a> · <a href=\"index.html#andou-sayo\">Andō Sayo<\/a> · <a href=\"index.html#minamikata-kozue\">Minamikata Kozue<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Phew~! Somehow we finally managed to make it to our last area.”<span class=\"pg\">p.250<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It seems like you’ve been pushing yourself quite a lot.”<span class=\"pg\">p.250<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hamaguchi Tetsuya<\/b> “Yo!”<span class=\"pg\">p.251<\/span><\/li><\/ul><details class=\"more\"><summary>28 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You guys in a hurry to get somewhere?”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. We’ve already reached our designated area for the day. We were just thinking of finding somewhere a bit closer to the ocean.”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then how about you take it easy and stick around for a bit?”<span class=\"pg\">p.251<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Though, you don’t have to force yourself if you don’t want to.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I suppose we’ll take a short break.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Come on over then, make yourself at home.”<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, nothin’ like that. We were whisperin’ ‘bout somethin’ else. It just so happens we wanted to talk with you, Ayanokōji-kun, so it’s totally fine by us if you guys camp here tonight. Right Kozue?”<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yep.”<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Wait, then has there really not been any progress yet? For real?”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way! I thought for sure that they’d at least be at that ‘more than friends, less than lovers’ stage by now!”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know right? Honami-chan’s been dropping his name pretty much all the time these days.”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Is that so?” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, like… ya know…”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know it’s not our place to say this an’ all, but… is there even any reason why they shouldn’t be going out at this point?”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I’m not 100% certain I get what you two are going on about, but I don’t think we should go out with each other.”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No no no no no no. What are you saying? I’ll say it again just to be sure, but you do know that this is THE Honami-chan we’re talkin’ about, right?”<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t really speak for all the boys out there, but prolly like 80 to 90% of the second-years like Honami-chan, right?”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That sounds like a safe bet to me.”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You two are in different classes, sure, but you don’t have to let that get in the way of love! There’re tons of couples out there going steady with each other regardless of their class or grade.”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn’t the bigger issue here the fact that Ichinose isn’t even interested in me?”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ooooo, is that modesty I see? You do know that you were quite the hit with the girls back when we first enrolled here, right Ayanokōji-kun?”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It sounds like you’re quite a hit with the ladies, Ayanokōji-senpai.”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I’m not. Nothing of the sort. No girls have ever said anything like that to me before.”<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Reeeally~? Ah, well I can think of one time when you came up in a conversation, but the topic changed real fast.”<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, ain’t no helpin’ that. There’s no way to tell if you’re gonna like a guy unless you up and talk with ‘em face-to-face, and Ayanokōji-kun wasn’t the type a’ guy to talk with people a year ago.”<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Doesn’t seem to me like he’s changed much since then either though~!”<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-senpai has changed a little from how he used to be, then?”<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I guess in some ways he seems a lot… softer now?”<span class=\"pg\">p.258<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p242-1\">← Before: Third place; the random designation; his strategy out in the open<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p260-1\">→ After: Day 6: the B4 cliff (her side of it)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p260-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa day 6  the b4 cliff  her side of it  day 6  b6 first designation  he takes early bird  a5 second  arrival  1 00 pm the random designation   c3  the route talk  she decides to follow  the cliff  her fall  the ribbon  her insistence  the shake of her arms on the rock face  him lowering to help  the handhold   i think so too   i m guessing that most of the other groups we re up against are going to go through c4 or take a detour down and around   while i don t imagine that you re in the best condition  we re going to have to take on the risk anyway   you want to take the direct path through a4 and b4  don t you senpai   i  i can do this   oww  that hurt   i guess that s the end of the line    speaker untagged in the print  recorded unassigned   i i can do it   even if you can  there s no point if it takes up all your stamina just to get to the top  the entire reason why we re scaling the mountain like this is to   save time  not everyone is going to end up taking a detour  so every second counts   i m going now  it s up to you if you still want to insist on climbing  but you re the one responsible for whatever happens   what are you doing   please  don t mind me  i ve made the choice to follow after you of my own volition  ayanokoji senpai   if you re not careful  you might end up facing consequences even worse than retirement  she begs to be left  he outstretches his hand  she takes it  the summit  the wind  her fatigue  the graduation question disguised  her strangeness sensed by him   i  i can t do that senpai  i promised you that i wouldn t get in your way back when i asked to accompany you  so please  go on ahead and don t worry about me  i beg you   if i went ahead and you got injured  it d leave a bad taste in my mouth  if you were down there begging me for help i might feel differently  but i m the one making the decision in this case  so don t worry about it   but   isn t it a waste of time to continue arguing about it like this   alright   senpai  do you perhaps have prior rock climbing experience   no  this is my first time doing something like this   is that so   t thank goodness   it s been pretty calm out these last few days but it s pretty windy today  huh    speaker untagged in the print  recorded unassigned   it must ve been surprising to suddenly get tossed onto a deserted island right after entering highschool    speaker untagged in the print  recorded unassigned   of course it was  this really is such an amazing school    speaker untagged in the print  recorded unassigned   senpai  do you enjoy it  this school   i guess  there have certainly been a handful of headaches to deal with  but i ve never really thought of it as unenjoyable   while it feels like graduation is a long ways away  it ll probably be here in the blink of an eye  that s why i think it d be best to spend what time i do have without any regrets   graduation   is something wrong   o oh  no  it s nothing  the cliff s edge   what she ll endure to keep up with him is deeper than duty  the sleep wake difference now blurs  graduation mentions shake her","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p260-1\"><h3><span class=\"ttl\">Day 6: the B4 cliff (her side of it)<\/span><span class=\"meta\">Y2V3 · p.260–266<\/span><\/h3><p class=\"setup\">Day 6; B6 first designation (he takes Early Bird); A5 second (Arrival); 1:00 PM the random designation — C3; the route talk; she decides to follow. The cliff; her fall; the ribbon; her insistence; the shake of her arms on the rock face; him lowering to help; the handhold. She begs to be left; he outstretches his hand; she takes it; the summit; the wind; her fatigue; the graduation question disguised; her strangeness sensed by him.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I think so too.”<span class=\"pg\">p.260<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I’m guessing that most of the other groups we’re up against are going to go through C4 or take a detour down and around.”<span class=\"pg\">p.260<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “While I don’t imagine that you’re in the best condition, we’re going to have to take on the risk anyway.”<span class=\"pg\">p.260<\/span><\/li><\/ul><details class=\"more\"><summary>29 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You want to take the direct path through A4 and B4, don’t you Senpai?”<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I… I can do this!”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oww, that hurt…!”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I guess that’s the end of the line.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-I can do it!”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if you can, there’s no point if it takes up all your stamina just to get to the top. The entire reason why we’re scaling the mountain like this is to … save time. Not everyone is going to end up taking a detour, so every second counts.”<span class=\"pg\">p.261<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m going now. It’s up to you if you still want to insist on climbing, but you’re the one responsible for whatever happens.”<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What are you doing?”<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Please… don’t mind me. I’ve made the choice to follow after you of my own volition, Ayanokōji-senpai…!”<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re not careful, you might end up facing consequences even worse than retirement.”<span class=\"pg\">p.262<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I, I can’t do that Senpai. I promised you that I wouldn’t get in your way back when I asked to accompany you… So please, go on ahead and don’t worry about me. I beg you.”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I went ahead and you got injured, it’d leave a bad taste in my mouth. If you were down there begging me for help I might feel differently, but I’m the one making the decision in this case, so don’t worry about it.”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But…!”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Isn’t it a waste of time to continue arguing about it like this?”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Alright.”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai… Do you perhaps have prior rock climbing experience?”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, this is my first time doing something like this.”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so…”<span class=\"pg\">p.264<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “T-thank goodness…!”<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “It’s been pretty calm out these last few days but it’s pretty windy today, huh?” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “It must’ve been surprising to suddenly get tossed onto a deserted island right after entering highschool.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Of course it was. This really is such an amazing school.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, do you enjoy it? This school?”<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess. There have certainly been a handful of headaches to deal with, but I’ve never really thought of it as unenjoyable.”<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “While it feels like graduation is a long ways away, it’ll probably be here in the blink of an eye. That’s why I think it’d be best to spend what time I do have without any regrets.”<span class=\"pg\">p.265<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Graduation…”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is something wrong?”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “O-oh, no. It’s nothing.”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The cliff&#x27;s edge — what she&#x27;ll endure to keep up with him is deeper than duty; the sleep/wake difference now blurs; graduation mentions shake her.<span class=\"pg\">p.260–266<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p250-1\">← Before: B5; Hamaguchi&#x27;s camp; the “Honami-chan” dinner<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p271-1\">→ After: Nanase named at the bonfire<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p271-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase named at the bonfire  apparently  nanase san s been sticking together with ayanokoji senpai for a while now  i heard that he s even given her permission to tag along too  i tried checking up on them with the gps search feature just to make sure  and sure enough  the both of  em are up in area c3 together right now    named by tsubaki  via the gps search feature  not present  named as connected to ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p271-1\"><h3><span class=\"ttl\">Nanase named at the bonfire<\/span><span class=\"meta\">Y2V3 · p.271<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Apparently, Nanase-san’s been sticking together with Ayanokōji-senpai for a while now. I heard that he’s even given her permission to tag along too. I tried checking up on them with the GPS Search feature just to make sure, and sure enough, the both of ‘em are up in area C3 together right now.” — named by Tsubaki (via the GPS Search feature); not present; named as connected to Ayanokōji.<span class=\"pg\">p.271<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p260-1\">← Before: Day 6: the B4 cliff (her side of it)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p275-1\">→ After: Day 7: the 6:50 wake; her odd sleep<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p275-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa day 7  the 6 50 wake  her odd sleep day 7 dawn  thick grey clouds  the first years  rise  takahashi yagami utomiya sixth  his 67 51st  koenji second  the school s weather broadcast  she emerges late  her inarticulate answer on the first years  his concern for horikita   good morning to you  ayanokoji senpai   i ve been checking the rankings while i waited  there s a group of first years that have been doing quite well for themselves so far   the group that s doing well is utomiya kun and yagami kun s  correct   after all  amongst all the first year groups  well  yes  they re definitely one of the best   as a member of class 1 d  it s honestly difficult for me to earnestly support them in their efforts   nevertheless  our third year senpais really are amazing  aren t they  every class from class 3 a to class 3 d has someone currently in the top ten   that said  you re also amazing  ayanokoji senpai  despite being all on your own  you ve managed to earn quite a large number of points   while that may be true  it won t be easy for me to push into the top ranks from where i m at now  at the end of the day  if you aren t part of the top three  you won t get the reward that matters most   although you say it won t be easy  you don t seem to be very anxious about it  senpai   i m hoping for a miracle  people in other groups should start retiring soon enough   that is true  i suppose    speaker untagged in the print  recorded unassigned","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p275-1\"><h3><span class=\"ttl\">Day 7: the 6:50 wake; her odd sleep<\/span><span class=\"meta\">Y2V3 · p.275–278<\/span><\/h3><p class=\"setup\">Day 7 dawn; thick grey clouds; the first-years’ rise (Takahashi/Yagami/Utomiya sixth); his 67/51st; Kōenji second; the school’s weather broadcast; she emerges late; her inarticulate answer on the first-years; his concern for Horikita.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“…Good morning to you, Ayanokōji-senpai.”<span class=\"pg\">p.276<\/span><\/li><li class=\"q spoken\">“I’ve been checking the rankings while I waited. There’s a group of first-years that have been doing quite well for themselves so far.”<span class=\"pg\">p.276<\/span><\/li><li class=\"q spoken\">“The group that’s doing well is Utomiya-kun and Yagami-kun’s, correct?”<span class=\"pg\">p.277<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “After all, amongst all the first-year groups, well… Yes, they’re definitely one of the best.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As a member of Class 1-D, it’s honestly difficult for me to earnestly support them in their efforts.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nevertheless, our third-year senpais really are amazing, aren’t they? Every class from Class 3-A to Class 3-D has someone currently in the top ten.”<span class=\"pg\">p.277<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, you’re also amazing, Ayanokōji-senpai. Despite being all on your own, you’ve managed to earn quite a large number of points.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “While that may be true, it won’t be easy for me to push into the top ranks from where I’m at now. At the end of the day, if you aren’t part of the top three, you won’t get the reward that matters most.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although you say it won’t be easy, you don’t seem to be very anxious about it, Senpai.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m hoping for a miracle. People in other groups should start retiring soon enough.”<span class=\"pg\">p.278<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “…That is true, I suppose.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.278<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p271-1\">← Before: Nanase named at the bonfire<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p279-1\">→ After: The E2 mountain; her strange air; the backpack<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p279-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the e2 mountain  her strange air  the backpack the weather alert  her volunteer mountain plan  she insists on ascending alone if he won t join  the climb  the crash of her breath  him lowering her backpack  the summit   we ll really have to think about how we re going to get there  won t we   how should we proceed   let s see  well  i guess it s safest to take a detour   that s understandable  depending on what the weather s like after this  we might not even be able to continue our journey   but personally  i d still like to go over the mountain   if it starts raining  it d be hard to find a proper foothold on the mountain  it s too dangerous   i believe that most of our rivals will choose to take a detour in anticipation of the weather  however  that s why it s a golden opportunity for you to pile up another first place early bird bonus  don t you think  let s make a run for it before it starts raining   what if i don t choose to go over the mountain   in that case  i will try to go over the mountain on my own   there s a limit to how impractical you can get  hosen and amasawa might not even reach e2 in time to make a difference   alright  if you ve already made up your mind then i ll go with you   thank you very much  senpai   since we ve decided on a route we should hurry up and get going   senpai  i can still   give me your backpack   a are you sure you can carry it   you should get moving if you have the time to stand around and ask questions   i ll be fine now that we ve come this far  my bag  i ll carry it again from here   are you sure  i d like to avoid wasting time later by having to go through the process of handing it over again   yes  i m sure  thank you very much for helping me","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p279-1\"><h3><span class=\"ttl\">The E2 mountain; her strange air; the backpack<\/span><span class=\"meta\">Y2V3 · p.279–286<\/span><\/h3><p class=\"setup\">The weather alert; her volunteer mountain plan (she insists on ascending alone if he won&#x27;t join); the climb; the crash of her breath; him lowering her backpack; the summit.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “We’ll really have to think about how we’re going to get there, won’t we?”<span class=\"pg\">p.281<\/span><\/li><li class=\"q spoken\">“How should we proceed?”<span class=\"pg\">p.281<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Let’s see… Well, I guess it’s safest to take a detour.”<span class=\"pg\">p.281<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “That’s understandable. Depending on what the weather’s like after this, we might not even be able to continue our journey.”<span class=\"pg\">p.281<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But personally, I’d still like to go over the mountain.”<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it starts raining, it’d be hard to find a proper foothold on the mountain. It’s too dangerous.”<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I believe that most of our rivals will choose to take a detour in anticipation of the weather. However, that’s why it’s a golden opportunity for you to pile up another first-place Early Bird Bonus, don’t you think? Let’s make a run for it before it starts raining.”<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What if I don’t choose to go over the mountain?”<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…In that case, I will try to go over the mountain on my own.”<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s a limit to how impractical you can get. Hōsen and Amasawa might not even reach E2 in time to make a difference.”<span class=\"pg\">p.282<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Alright. If you’ve already made up your mind then I’ll go with you.”<span class=\"pg\">p.283<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you very much, Senpai.”<span class=\"pg\">p.283<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since we’ve decided on a route we should hurry up and get going.”<span class=\"pg\">p.283<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai…! I can still─！”<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Give me your backpack.”<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A-are you sure you can carry it?”<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should get moving if you have the time to stand around and ask questions.”<span class=\"pg\">p.285<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll be fine now that we’ve come this far. My bag… I’ll carry it again from here.”<span class=\"pg\">p.287<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you sure? I’d like to avoid wasting time later by having to go through the process of handing it over again.”<span class=\"pg\">p.287<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, I’m sure. Thank you very much for helping me.”<span class=\"pg\">p.287<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p275-1\">← Before: Day 7: the 6:50 wake; her odd sleep<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p287-1\">→ After: The reveal; her orders; the opening<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p287-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the reveal  her orders  the opening the bag drop  her confession approach  white room reveal  her orders to knock him out  the emergency alert  his feinted vulnerability  her feint to the left  his stopped punch   ayanokoji senpai  i have something i d like to ask you   it s seemed like you ve been thinking about something ever since you first came out of your tent this morning   so  you noticed after all  huh   there s a reason why i ve been sticking close to you these past few days  ayanokoji senpai   but before that  please allow me to apologize for something   i m afraid you won t be reaching area e2 today  senpai   the reason i wanted to head up the mountain was to lure you here  senpai   we re probably the only two people up here right now    speaker untagged in the print  recorded unassigned   yes indeed  i believe that to be the case as well   over the course of the last six days i ve been with you  i ve been able to witness all sorts of things  ayanokoji senpai  you ve made a lot of friends at this school and built up a lot of trust for yourself  and  slowly but surely  you ve demonstrated what you re truly capable of   i d also like to express my respect for the depth of the insight and physical prowess you ve shown from time to time   i don t remember having done anything special though   if that s really the case  then that just makes you even more amazing  don t you think   but  ayanokoji senpai  i don t think you re someone who belongs at this school   you don t  care to explain the reason for that   it s because you re from the white room   as you may have already guessed  i enrolled here in this school under acting director tsukishiro s orders  and more precisely  those orders were to get you expelled   you could ve done this at any point over the last few days  so why here  why now  you must have had some other reason than just wanting to avoid the eyes of others  right   i m going to knock you out here and injure you  setting off your emergency alert in the process  the teachers would then come running and force you to retire  thus resulting in your expulsion  something like that   so  something similar to what happened to komiya and kinoshita  were you the one behind what happened to them as well   well  hmm  what do you think  senpai   i don t really think you d have been able to make it there and back in such a short timeframe  but if you were really from the white room  i m not so confident about that   what happens if i tell the faculty members who came rushing to the scene that you were the one who had attacked me   i don t think you d be able to explain your way out of it   undoubtedly be the acting director himself   i see  so basically  losing to you here would be no different from being kicked out of school   if acting director tsukishiro sent you thinking you d be able to take me down  then it looks like there ll be no getting around having to fight seriously  although  having said that  raising my hand against a girl could easily turn into a major issue in it s own right   if you re looking for a way out of this  senpai  then i believe your only option is abandoning your bag and running away   perhaps   but  i m afraid that would be futile as well   so  what will you do   since it s come to this  there s really only one choice i can make   so you ve chosen to fight  but  do you think you ll be saved by doing that  this might seem cowardly of me to say  but my loss is no different from your own loss  ayanokoji senpai   maybe so   i ll be making my move  then  her feint to the left  her gentle open palm grappling technique  his stopped punch    that s the first","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p287-1\"><h3><span class=\"ttl\">The reveal; her orders; the opening<\/span><span class=\"meta\">Y2V3 · p.287–291<\/span><\/h3><p class=\"setup\">The bag-drop; her confession approach; White Room reveal; her orders to knock him out; the Emergency Alert; his feinted vulnerability; her feint to the left; his stopped punch. Her feint to the left; her gentle open-palm grappling technique; his stopped punch — “That’s the first.”<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ayanokōji-senpai, I have something I’d like to ask you.”<span class=\"pg\">p.287<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’s seemed like you’ve been thinking about something ever since you first came out of your tent this morning.”<span class=\"pg\">p.287<\/span><\/li><li class=\"q spoken\">“So… you noticed after all, huh?”<span class=\"pg\">p.287<\/span><\/li><\/ul><details class=\"more\"><summary>31 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There’s a reason why I’ve been sticking close to you these past few days, Ayanokōji-senpai.”<span class=\"pg\">p.287<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But before that, please allow me to apologize for something.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m afraid you won’t be reaching area E2 today, Senpai.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The reason I wanted to head up the mountain was to lure you here, Senpai.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “We’re probably the only two people up here right now.” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes indeed. I believe that to be the case as well.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Over the course of the last six days I’ve been with you, I’ve been able to witness all sorts of things, Ayanokōji-senpai. You’ve made a lot of friends at this school and built up a lot of trust for yourself. And, slowly but surely, you’ve demonstrated what you’re truly capable of.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’d also like to express my respect for the depth of the insight and physical prowess you’ve shown from time to time.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t remember having done anything special though.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If that’s really the case, then that just makes you even more amazing, don’t you think?”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, Ayanokōji-senpai, I don’t think you’re someone who belongs at this school.”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t? Care to explain the reason for that?”<span class=\"pg\">p.288<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s because you’re from the White Room.”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As you may have already guessed, I enrolled here in this school under Acting Director Tsukishiro’s orders. And more precisely, those orders were to get you expelled.”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You could’ve done this at any point over the last few days, so why here? Why now? You must have had some other reason than just wanting to avoid the eyes of others, right?”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m going to knock you out here and injure you, setting off your Emergency Alert in the process. The teachers would then come running and force you to retire, thus resulting in your expulsion. Something like that.”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, something similar to what happened to Komiya and Kinoshita. Were you the one behind what happened to them as well?”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, hmm… What do you think, Senpai?”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t really think you’d have been able to make it there and back in such a short timeframe, but if you were really from the White Room, I’m not so confident about that.”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What happens if I tell the faculty members who came rushing to the scene that you were the one who had attacked me?”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t think you’d be able to explain your way out of it. …undoubtedly be the Acting Director himself.”<span class=\"pg\">p.289<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. So basically, losing to you here would be no different from being kicked out of school.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Acting Director Tsukishiro sent you thinking you’d be able to take me down, then it looks like there’ll be no getting around having to fight seriously. Although, having said that, raising my hand against a girl could easily turn into a major issue in it’s own right.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re looking for a way out of this, Senpai, then I believe your only option is abandoning your bag and running away.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But, I’m afraid that would be futile as well.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, what will you do?”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since it’s come to this, there’s really only one choice I can make.”<span class=\"pg\">p.290<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you’ve chosen to fight. But, do you think you’ll be saved by doing that? This might seem cowardly of me to say, but my loss is no different from your own loss, Ayanokōji-senpai.”<span class=\"pg\">p.291<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe so.”<span class=\"pg\">p.291<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll be making my move, then.”<span class=\"pg\">p.291<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p279-1\">← Before: The E2 mountain; her strange air; the backpack<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p292-1\">→ After: The three stopped punches; her burst<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p292-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the three stopped punches  her burst three stopped punches  her second rush is faster  the boku switch  the karate style assault  the first real danger   that s the first   nanase  are you tired  or was that hesitation  you should be capable of much more than this   do you think you can beat me without even trying to fight back  is that what this is   and that s the second  if i had gone through with it  i could ve knocked you out two times now   but you didn t go through with it   that s true   although you re free to make this show of dominance all you want  you don t stand a chance at winning if you don t actually fight back   i still wouldn t stand a chance even if i did  though   correct  so  what will you do   i m not sure yet   it would be great if you could figure that out while you re still able to stand around and talk   what the   i ll say this just in case you haven t noticed  but this makes three times now   it seems your strength is just as the rumors say  ayanokoji senpai   i know what you re trying to do here  senpai   it s true that it s improbable that i ll be able to win against you if we keep going on like this  i ll admit to that   i  may not be able to beat you   therefore i will  right here  right now   who are you   i came back from  that place  in order to put a stop to you   from that dark  gloomy place i have come back","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p292-1\"><h3><span class=\"ttl\">The three stopped punches; her burst<\/span><span class=\"meta\">Y2V3 · p.292–296<\/span><\/h3><p class=\"setup\">Three stopped punches; her second rush is faster; the『Boku』switch; the karate-style assault; the first real danger.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “That’s the first.”<span class=\"pg\">p.292<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Nanase, are you tired? Or was that hesitation? You should be capable of much more than this.”<span class=\"pg\">p.293<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Do you think you can beat me without even trying to fight back…? Is that what this is?”<span class=\"pg\">p.293<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “And that’s the second. If I had gone through with it, I could’ve knocked you out two times now.”<span class=\"pg\">p.293<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But you didn’t go through with it.”<span class=\"pg\">p.293<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s true.”<span class=\"pg\">p.293<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although you’re free to make this show of dominance all you want, you don’t stand a chance at winning if you don’t actually fight back.”<span class=\"pg\">p.293<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I still wouldn’t stand a chance even if I did, though?”<span class=\"pg\">p.293<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Correct. So, what will you do?”<span class=\"pg\">p.294<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not sure yet.”<span class=\"pg\">p.294<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would be great if you could figure that out while you’re still able to stand around and talk.”<span class=\"pg\">p.294<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the─!?”<span class=\"pg\">p.294<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll say this just in case you haven’t noticed, but this makes three times now.”<span class=\"pg\">p.295<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems your strength is just as the rumors say, Ayanokōji-senpai…”<span class=\"pg\">p.295<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I know what you’re trying to do here, Senpai…”<span class=\"pg\">p.295<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true that it’s improbable that I’ll be able to win against you if we keep going on like this. I’ll admit to that.”<span class=\"pg\">p.295<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “‘I’… may not be able to beat you.”<span class=\"pg\">p.295<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Therefore…『I』will. Right here, right now.”<span class=\"pg\">p.296<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who are you?”<span class=\"pg\">p.296<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “『I』came back from ‘that place’ in order to put a stop to you.”<span class=\"pg\">p.296<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From that dark… gloomy place…『I』have come back.”<span class=\"pg\">p.296<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p287-1\">← Before: The reveal; her orders; the opening<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p297-1\">→ After: Matsuo; the collapse<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p297-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa matsuo  the collapse the boku watashi switch  her matsuo eiichiro reveal   the son of the man atsuomi killed  his demolition of the fiction  her teeth  her shriek  her knees give  his victim play gambit  the end of the fight   do you really think that you can keep dodging forever   ha  haaa   whew  haaa   absolutely i ll absolutely defeat you  absolutely  defeat  you   i came back i came back in order to bring you down   you came back  what are you talking about   it makes sense that you don t understand  after all  you and i have never met in person before   if you aren t going to fight back  then that s your decision i ll just have to do this over and over until you re down on the ground   hyaaah   you don t seem like nanase anymore   you still don t get it  do you   i m not nanase  the one standing here before you right now is  matsuo eiichiro   matsuo eiichiro   the son of a man who was killed by your father   this body has been borrowed i m right here  right now  all for the sake of bringing you down   borrowed  what a funny joke   if you think i m joking  then please  be my guest   i m here i came all the way here just to see you fall   i ll make sure you suffer retribution   this is the first time i ve encountered an opponent capable of dodging so many attacks like this   but  there s no way you can keep it up forever  if it s me  if i m the one you re up against  then i can definitely defeat you i know it   i think i understand what you ve been trying to say   nanase  you don t have multiple personalities  nor did someone else s personality take over you   like i said  if you think i m joking  then please  be my guest  but there s no getting around the fact that i m the one right here in front of you   no  it s unfortunate  but i just don t believe you  if this alternate personality of yours hadn t been someone who actually existed elsewhere  then i suppose that i might ve been able to believe you  however  you re saying that  matsuo eiichiro  a person who exists here in real life  has gone and borrowed your body  and sorry  but that s just far too unrealistic   you just took the liberty to dream up another personality inside of yourself  the reason you deliberately chose to change from using  watashi  to boku was to remind yourself of that   more than anything else  this force  this power is proof that i m real   you re not showing me anything more than the strength you ve always had in you  nanase   y you re wrong i i m matsuo   there was something out of sorts about the way you were talking when you changed your first person pronoun  it s nothing more than a form of self deception   no   you want to believe that matsuo s personality resides within you  no  i ll bet that deep down  even you don t believe that   aaaaaaaahhhhhhh   it s time to give up nanase  you can t beat me   yes i can i have to   why  why can t i land a hit  why is this happening   l let go   even if i let go  nothing would change   let go of me   why  why i m so close and yet  only a little more  and yet   from the very beginning  you were wrong to tell yourself that you d eventually land a hit as long as you kept trying  at your level  even if you kept this up until the day you died  you d never be able to hit me  not even once   if you really want me expelled  your best bet is to start playing the victim now  if you make your clothes seem disorderly  that alone would probably be enough to drive me into a corner   i i","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p297-1\"><h3><span class=\"ttl\">Matsuo; the collapse<\/span><span class=\"meta\">Y2V3 · p.297–304<\/span><\/h3><p class=\"setup\">The『Boku』/『Watashi』switch; her Matsuo Eiichiro reveal — the son of the man Atsuomi killed; his demolition of the fiction; her teeth; her shriek; her knees give; his victim-play gambit; the end of the fight.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Do you really think that you can keep dodging forever!?”<span class=\"pg\">p.297<\/span><\/li><li class=\"q spoken\">“Ha, Haaa!!!”<span class=\"pg\">p.297<\/span><\/li><li class=\"q spoken\">“Whew… Haaa…!”<span class=\"pg\">p.297<\/span><\/li><\/ul><details class=\"more\"><summary>39 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Absolutely…『I’ll』absolutely defeat you… Absolutely… defeat… you…”<span class=\"pg\">p.297<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “『I』came back…『I』came back in order to bring you down…”<span class=\"pg\">p.297<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You came back? What are you talking about?”<span class=\"pg\">p.297<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It makes sense that you don’t understand. After all, you and『I』have never met in-person before.”<span class=\"pg\">p.297<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you aren’t going to fight back, then that’s your decision.『I’ll』just have to do this over and over until you’re down on the ground─”<span class=\"pg\">p.298<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hyaaah!!!”<span class=\"pg\">p.298<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t seem like Nanase anymore.”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You still don’t get it, do you?”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “『I’m』not Nanase. The one standing here before you right now is… Matsuo Eiichiro.”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Matsuo Eiichiro?”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The son of a man who was killed by your father.”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This body has been borrowed.『I’m』right here, right now, all for the sake of bringing you down.”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Borrowed? What a funny joke.”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you think『I’m』joking, then please, be my guest.”<span class=\"pg\">p.299<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “『I’m』here…『I』came all the way here just to see you fall!”<span class=\"pg\">p.300<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “『I’ll』make sure you suffer retribution!”<span class=\"pg\">p.300<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This is the first time『I’ve』encountered an opponent capable of dodging so many attacks like this. …But, there’s no way you can keep it up forever. If it’s『me』… If『I’m』the one you’re up against… Then『I』can definitely defeat you!『I』know it!”<span class=\"pg\">p.300<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think I understand what you’ve been trying to say.”<span class=\"pg\">p.300<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nanase, you don’t have multiple personalities, nor did someone else’s personality take over you.”<span class=\"pg\">p.301<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Like I said, if you think『I’m』joking, then please, be my guest. But there’s no getting around the fact that『I’m』the one right here in front of you.”<span class=\"pg\">p.301<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, it’s unfortunate, but I just don’t believe you. If this alternate personality of yours hadn’t been someone who actually existed elsewhere, then I suppose that I might’ve been able to believe you. However, you’re saying that ‘Matsuo Eiichiro’, a person who exists here in real life, has gone and borrowed your body. And sorry, but that’s just far too unrealistic.”<span class=\"pg\">p.301<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You just took the liberty to dream up another personality inside of yourself. The reason you deliberately chose to change from using ‘Watashi’ to『Boku』was to remind yourself of that.”<span class=\"pg\">p.301<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “More than anything else, this force, this power is proof that『I’m』real!”<span class=\"pg\">p.301<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not showing me anything more than the strength you’ve always had in you, Nanase.”<span class=\"pg\">p.301<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Y-you’re wrong!『I』…『I’m』Matsuo!”<span class=\"pg\">p.302<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There was something out of sorts about the way you were talking when you changed your first-person pronoun. It’s nothing more than a form of self-deception.”<span class=\"pg\">p.302<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No!!!”<span class=\"pg\">p.302<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You want to believe that Matsuo’s personality resides within you… No, I’ll bet that deep down, even you don’t believe that.”<span class=\"pg\">p.302<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “AAAAAAAAHHHHHHH!!!”<span class=\"pg\">p.302<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s time to give up Nanase. You can’t beat me.”<span class=\"pg\">p.303<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes『I』can!『I』have to!”<span class=\"pg\">p.303<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why!? Why can’t『I』land a hit!?!? Why is this happening!?!?”<span class=\"pg\">p.303<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “L-let go!”<span class=\"pg\">p.303<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if I let go, nothing would change.”<span class=\"pg\">p.303<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let go of『me』!!!”<span class=\"pg\">p.303<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why… Why…『I’m』so close and yet… Only a little more, and yet!”<span class=\"pg\">p.304<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From the very beginning, you were wrong to tell yourself that you’d eventually land a hit as long as you kept trying. At your level, even if you kept this up until the day you died, you’d never be able to hit me. Not even once.”<span class=\"pg\">p.304<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you really want me expelled, your best bet is to start playing the victim now. If you make your clothes seem disorderly, that alone would probably be enough to drive me into a corner.”<span class=\"pg\">p.304<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “『I』…『I』!!!”<span class=\"pg\">p.304<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p292-1\">← Before: The three stopped punches; her burst<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p306-1\">→ After: Kushida watches (POV switch)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p306-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa kushida watches  pov switch  pov switch recorded   this is kushida kikyo s interior monologue  named there but not present on these pages  fight  her words and her fear  recorded on her record  referenced here only to anchor her in the timeline","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p306-1\"><h3><span class=\"ttl\">Kushida watches (POV switch)<\/span><span class=\"meta\">Y2V3 · p.306–329<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> POV switch recorded — this is Kushida Kikyō&#x27;s interior monologue; named there but not present on these pages&#x27; fight; her words and her fear; recorded on her record; referenced here only to anchor her in the timeline.<span class=\"pg\">p.306–329<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p297-1\">← Before: Matsuo; the collapse<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p346-1\">→ After: The rain; the truth; the promise<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p346-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa the rain  the truth  the promise the evening of day 7  rain falling  he waits out the worst of it  the tsukishiro confessions fade into silence  she finally breaks   it s my loss  ayanokoji senpai   can i take that to mean you re finally convinced   yes  it seems that  despite my best efforts  it truly isn t possible for me to beat you senpai   if possible  how about you explain everything in detail  why were you targeting me  if we don t clear this up  there will be several issues later   that s fair  you have a right to know  no  i want you to know  senpai  her story unfurls in one long confession  the rain  her exhaustion  his silence  his patient evaluation   i  i enrolled in this school because i wanted to avenge my childhood friend   your childhood friend  you mean   yes  matsuo eiichiro   i hadn t truly realized it before enrolling here  but since this school is completely isolated from the outside world  there s no way you could ve known what happened  is there   from kindergarten up until the day he graduated from middle school  i was always together with eiichiro kun  he was a year above me and better than me at just about anything  from studies to the games we played together  he was my inspiration  my role model   even after he was kicked out of his home  eiichiro kun said he wouldn t give up until the very end  and that s when he started working  while we weren t able to see each other as often  i didn t think the relationship between us would change   even though he had given up on his education  even though he had lost his father  he told me that he wouldn t give up  that he d look toward the future and try his best  he even smiled  and yet   earlier this year  on the evening of february 14th  i paid a visit to eiichiro kun s apartment  he was trying so hard  so i was hoping to at least make him feel a little bit better  but   if you can never meet again  then you ll never be able to tell them how you feel  you said it yourself   i didn t know very much about you or your father at the time  in fact  i had only just sent out my application to another high school when  that person appeared before me   you mean tsukishiro   yes  back then  acting director tsukishiro told me why eiichiro kun s life had been thrown into turmoil  he said that the root cause of all of it had been that someone named ayanokoji kiyotaka had escaped from an establishment called  the white room  by enrolling at a school named  advanced nurturing high school  and that he had made arrangements for me to enroll there myself   if i could successfully get you expelled  he promised to let me meet your father  senpai   and apologize to eiichiro kun  but   tsukishiro told me that he had sent in a student from the white room  was that just a bluff   uhm  what do you mean by that  senpai  i don t really know much about this  white room  thing to begin with   i knew that you weren t the one at fault  ayanokoji senpai  but  i wanted  no  needed someone to take it out on  all my pent up anger and frustration   i  i don t know how i can face you anymore  senpai  i m so  so sorry   you don t need to apologize  the anger you feel is perfectly justified   i ve failed to carry out the acting director s orders  there s no point in me staying here anymore   will you drop out   it s the least i can do to atone for my actions   senpai   if you re really sorry  then please take back what you said just now   what  do you mean   you have nothing to feel ashamed of  you simply tried your best to avenge your friend  but there s a reason i can t lose to you  since i believe that staying here at this school is the only way i have of going against  that man  my father   are you saying that  i should ve been doing the opposite this entire time   if i could be a bit selfish here  i d rather not hear about you leaving the school  instead  i d like you to cooperate with me  even now  tsukishiro is probably scheming to use this special exam to expel me and present me as a gift to my father  if that were to happen  all the painstaking efforts matsuo eiichiro went through to get me into this school would be for nothing   can you lend me your hand   it s a promise    narration implied  recorded as the concluding gesture  not quoted speech   you ll catch a cold if you stay in the rain for too long  so let s get going   okay  he offers his hand  she takes it  his intent cold  her guilt real","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p346-1\"><h3><span class=\"ttl\">The rain; the truth; the promise<\/span><span class=\"meta\">Y2V3 · p.346–355<\/span><\/h3><p class=\"setup\">The evening of day 7; rain falling; he waits out the worst of it; the Tsukishiro confessions fade into silence; she finally breaks. Her story unfurls in one long confession; the rain; her exhaustion; his silence; his patient evaluation.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It’s my loss… Ayanokōji-senpai.”<span class=\"pg\">p.347<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Can I take that to mean you’re finally convinced?”<span class=\"pg\">p.347<\/span><\/li><li class=\"q spoken\">“Yes. It seems that, despite my best efforts, it truly isn’t possible for me to beat you Senpai.”<span class=\"pg\">p.347<\/span><\/li><\/ul><details class=\"more\"><summary>34 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “If possible, how about you explain everything in detail? Why were you targeting me? If we don’t clear this up, there will be several issues later.”<span class=\"pg\">p.347<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s fair. You have a right to know─ No, I want you to know, Senpai.”<span class=\"pg\">p.347<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I… I enrolled in this school because I wanted to avenge my childhood friend.”<span class=\"pg\">p.347<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Your childhood friend? You mean─”<span class=\"pg\">p.347<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Matsuo Eiichiro.”<span class=\"pg\">p.347<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hadn’t truly realized it before enrolling here, but since this school is completely isolated from the outside world, there’s no way you could’ve known what happened, is there?”<span class=\"pg\">p.348<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From kindergarten up until the day he graduated from middle school, I was always together with Eiichiro-kun. He was a year above me and better than me at just about anything, from studies to the games we played together… He was my inspiration, my role model.”<span class=\"pg\">p.348<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even after he was kicked out of his home, Eiichiro-kun said he wouldn’t give up until the very end, and that’s when he started working. While we weren’t able to see each other as often, I didn’t think the relationship between us would change.”<span class=\"pg\">p.348<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even though he had given up on his education… Even though he had lost his father… He told me that he wouldn’t give up… That he’d look toward the future and try his best… He even smiled… And yet…”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Earlier this year, on the evening of February 14th, I paid a visit to Eiichiro-kun’s apartment. He was trying so hard, so I was hoping to at least make him feel a little bit better, but─”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “‘If you can never meet again, then you’ll never be able to tell them how you feel.’ You said it yourself.”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I didn’t know very much about you or your father at the time. In fact, I had only just sent out my application to another high school when… that person appeared before me.”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean Tsukishiro?”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. Back then, Acting Director Tsukishiro told me why Eiichiro-kun’s life had been thrown into turmoil. He said that the root cause of all of it had been that someone named Ayanokōji Kiyotaka had escaped from an establishment called ‘The White Room’ by enrolling at a school named ‘Advanced Nurturing High School’, and that he had made arrangements for me to enroll there myself.”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I could successfully get you expelled, he promised to let me meet your father, Senpai. …and apologize to Eiichiro-kun, but…”<span class=\"pg\">p.349<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsukishiro told me that he had sent in a student from the White Room. Was that just a bluff?”<span class=\"pg\">p.350<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Uhm, what do you mean by that, Senpai? I don’t really know much about this ‘White Room’ thing to begin with.”<span class=\"pg\">p.350<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I knew that you weren’t the one at fault, Ayanokōji-senpai, but… I wanted… no, needed someone to take it out on… all my pent-up anger and frustration…”<span class=\"pg\">p.350<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I… I don’t know how I can face you anymore, Senpai… I’m so, so sorry…”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You don’t need to apologize. The anger you feel is perfectly justified.”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve failed to carry out the Acting Director’s orders. There’s no point in me staying here anymore.”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Will you drop out?”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s the least I can do to atone for my actions.”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai…?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you’re really sorry, then please take back what you said just now.”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What… do you mean…?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You have nothing to feel ashamed of. You simply tried your best to avenge your friend. But there’s a reason I can’t lose to you, since I believe that staying here at this school is the only way I have of going against ‘that man’, my father.”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you saying that… I should’ve been doing the opposite this entire time?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I could be a bit selfish here, I’d rather not hear about you leaving the school. Instead, I’d like you to cooperate with me. Even now, Tsukishiro is probably scheming to use this special exam to expel me and present me as a gift to my father. If that were to happen, all the painstaking efforts Matsuo Eiichiro went through to get me into this school would be for nothing.”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you lend me your hand?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “─It’s a promise.” — narration implied; recorded as the concluding gesture, not quoted speech.<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’ll catch a cold if you stay in the rain for too long, so let’s get going.”<span class=\"pg\">p.353<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Okay.”<span class=\"pg\">p.353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He offers his hand; she takes it; his intent cold; her guilt real.<span class=\"pg\">p.346–355<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p306-1\">← Before: Kushida watches (POV switch)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p358-1\">→ After: Nanase named in the Sakayanagi SS<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p358-1","v":"y2v3","y":2,"o":18,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase named in the sakayanagi ss  the fact nanase san isn t by him now means there was an empty spot for    named  not present  pov sakayanagi   it should take about 30 mins before the task is over and nanase san    named by sakayanagi  not present  pov sakayanagi   how did you know about nanase    named by ayanokoji  not present  pov sakayanagi","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p358-1\"><h3><span class=\"ttl\">Nanase named in the Sakayanagi SS<\/span><span class=\"meta\">Y2V3 · p.358<\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “The fact Nanase-san isn’t by him now means there was an empty spot for” — named; not present; POV Sakayanagi.<span class=\"pg\">p.358<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “It should take about 30 mins before the task is over and Nanase-san” — named by Sakayanagi; not present; POV Sakayanagi.<span class=\"pg\">p.358<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “How did you know about Nanase?” — named by Ayanokōji; not present; POV Sakayanagi.<span class=\"pg\">p.358<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p346-1\">← Before: The rain; the truth; the promise<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p360-1\">→ After: Nanase SS: “Unfathomable” (her POV)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p360-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase ss   unfathomable   her pov  her pov on the cliff  the resolve to stay on pace  the grab at rock  the cliff edge confession of her feelings  his rescue logic seen from her eyes   what are you doing   don t  mind me  i will  catch up to you  at my own pace   retiring will be the least of your worries if you fall from here   grab on   n no  i won t have it  since one of the conditions for following you was that you wouldn t help me  don t mind me and go on  please   but   it would leave a bad aftertaste if i went ahead and you hurt yourself  it would be one thing if you asked me for it  but i m offering this kindness of my own accord  don t mind it   we re wasting time as we speak  am i right   yes   senpai  have you ever climbed before   no  this is the first time i m moving up like this   is that so   from what he brazenly did during the fight with housen to this    housen referenced  not present  pov nanase  her fixation on never losing pace with him  his kindness offered from his own accord  his unfathomability  her vow to drag out  that person","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p360-1\"><h3><span class=\"ttl\">Nanase SS: “Unfathomable” (her POV)<\/span><span class=\"meta\">Y2V3 · p.360–362<\/span><\/h3><p class=\"setup\">Her POV on the cliff; the resolve to stay on pace; the grab at rock; the cliff-edge confession of her feelings; his rescue logic seen from her eyes.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “What are you doing?”<span class=\"pg\">p.360<\/span><\/li><li class=\"q spoken\">“Don’t… mind me. I will, catch up to you, at my own pace…!”<span class=\"pg\">p.360<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Retiring will be the least of your worries if you fall from here.”<span class=\"pg\">p.360<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Grab on.”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “N-no, I won’t have it. Since one of the conditions for following you was that you wouldn’t help me… Don’t mind me and go on, please.”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But…!”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It would leave a bad aftertaste if I went ahead and you hurt yourself. It would be one thing if you asked me for it, but I’m offering this kindness of my own accord. Don’t mind it.”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’re wasting time as we speak. Am I right?”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Yes.”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai… have you ever climbed before?”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, this is the first time I’m moving up like this.”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is that so…”<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “From what he brazenly did during the fight with Housen to this.” — Housen referenced; not present; POV Nanase.<span class=\"pg\">p.361<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her fixation on never losing pace with him; his kindness offered from his own accord; his unfathomability; her vow to drag out “that person.”<span class=\"pg\">p.360–362<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p358-1\">← Before: Nanase named in the Sakayanagi SS<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p365-1\">→ After: Nanase Tapestry SS: “What Could Be Seen From that Back” (her POV)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v3-p365-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"tokunaga ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase tapestry ss   what could be seen from that back   her pov  the beach flags final vs tokunaga  the gun  her rush  her awe at his calm  her embarrassed flush  her quiet promise to switch before he can see   fuu   what a terrifying 1st year  it s my loss   thank you so much  tokunaga senpai   you know about me   i looked at the oaa app for any upperclassmen i had to be wary of when preparing for this special exam   that was an overwhelming victory   thank you so much  i managed to win somehow   h hey  ayanokouji senpai   hmm   i can t really relax when you are  staring at me like that   whops  you re right  my bad   ayanokouji senpai seems to be talking to kiriyama senpai    kiriyama named  not present  pov nanase  her awe redirected into embarrassed stillness  her fear of letting her  plan  break  her decision to leave before he can see her unease","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v3-p365-1\"><h3><span class=\"ttl\">Nanase Tapestry SS: “What Could Be Seen From that Back” (her POV)<\/span><span class=\"meta\">Y2V3 · p.365–367<\/span><\/h3><p class=\"setup\">The Beach Flags final vs Tokunaga; the gun; her rush; her awe at his calm; her embarrassed flush; her quiet promise to switch before he can see.<\/p><p class=\"with\">with <a href=\"index.html#tokunaga\">Tokunaga<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Fuu…”<span class=\"pg\">p.365<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tokunaga<\/b> “What a terrifying 1st year. It’s my loss.”<span class=\"pg\">p.366<\/span><\/li><li class=\"q spoken\">“Thank you so much, Tokunaga-senpai.”<span class=\"pg\">p.366<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You know about me?”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I looked at the OAA app for any upperclassmen I had to be wary of when preparing for this special exam.”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That was an overwhelming victory.”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thank you so much. I managed to win somehow.”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “H-hey, Ayanokouji-senpai?”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm?”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t really relax when you are, staring at me like that…”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Whops, you’re right. My bad.”<span class=\"pg\">p.366<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokouji-senpai seems to be talking to Kiriyama-senpai” — Kiriyama named; not present; POV Nanase.<span class=\"pg\">p.367<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her awe redirected into embarrassed stillness; her fear of letting her “plan” break; her decision to leave before he can see her unease.<span class=\"pg\">p.365–367<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v3-p360-1\">← Before: Nanase SS: “Unfathomable” (her POV)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p8-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 1  she guards him  names the slope watcher in the rain  sensing the presences behind them  she notices amasawa at once and points the earlier watcher out   please get behind me  senpai   you  cannot be trusted   please don t listen to her  she s dangerous   while you were gone  i noticed that someone had been watching us from nearby  so i tried chasing after them   back then  the one watching us from the shadows was you  wasn t it amasawa san   you also hurt komiya senpai and kinoshita senpai  didn t you   i don t believe you  not at all   then  can you swear to me that you weren t the one who hurt them   if a girl came running at you with a scary look on her face  who wouldn t run away   but even if you broke your gps before the attack  wouldn t the school have taken notice   that s how it is  nanase chan  she slowly raises her right arm toward amasawa  identifying her as the fourth day shadow  she saw the hair  her testimony is circumstantial   she never saw the push  she wanted to testify that she saw amasawa at the scene  ayanokoji tells her it would only ever end in suspicion without conclusive evidence  she puts herself between ayanokoji and amasawa with zero hesitation  interrogates amasawa relentlessly  and correctly clocks the broken watch and the missing gps  and does not relax even after the stick is tossed down  accuses her of the cliff attack  sharpest suspicion in the exam  devoted guard  obeys his orders to stand down","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p8-1\"><h3><span class=\"ttl\">Ch.1: She guards him; names the slope watcher<\/span><span class=\"meta\">Y2V4 · p.8–14<\/span><\/h3><p class=\"setup\">In the rain, sensing the presences behind them, she notices Amasawa at once and points the earlier watcher out.<\/p><p class=\"with\">with <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Please get behind me, Senpai.”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\">“You─ cannot be trusted.”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\">“Please don’t listen to her, she’s dangerous.”<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “While you were gone, I noticed that someone had been watching us from nearby, so I tried chasing after them.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Back then, the one watching us from the shadows was you, wasn’t it Amasawa-san?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You also hurt Komiya-senpai and Kinoshita-senpai, didn’t you?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t believe you. Not at all.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Then, can you swear to me that you weren’t the one who hurt them?”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If a girl came running at you with a scary look on her face, who wouldn’t run away?”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But even if you broke your GPS before the attack, wouldn’t the school have taken notice?”<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s how it is, Nanase-chan.”<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She slowly raises her right arm toward Amasawa, identifying her as the fourth-day shadow (she saw the hair); her testimony is circumstantial — she never saw the push; she wanted to testify that she saw Amasawa at the scene; Ayanokōji tells her it would only ever end in suspicion without conclusive evidence.<span class=\"pg\">p.11–14<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She puts herself between Ayanokōji and Amasawa with zero hesitation, interrogates Amasawa relentlessly (and correctly clocks the broken watch and the missing GPS), and does not relax even after the stick is tossed down.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Accuses her of the cliff attack; sharpest suspicion in the exam.<span class=\"pg\">p.8–14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Devoted guard; obeys his orders to stand down.<span class=\"pg\">p.8–14<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p15-1\">→ After: Ch.1: Left out of the private talk<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p15-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"amasawa-ichika ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 1  left out of the private talk  jeez  i m not some bad guy  right ayanokoji senpai  i just wanna chat for a bit  kay   what s with this  nanase chan   you were about to lay your hands on ayanokoji senpai  weren t you   ah  are you worried about breaking the rules  it s fine  it s fine  even the school can t monitor everything  you know   that  that has nothing to do with you  why did you come here   let go of her arm nanase   wow  you re such a good girl nanase chan  it s like you re his loyal dog  it s a better look for you than i thought   why don t you just talk from where you are   now then  where oh where should i start  he motions her away so the rain masks a private conversation  reluctant to leave him alone with amasawa  she eventually gives in and steps back a few meters away   too far to hear  she does not hear the substance of the white room reveal  she only sees the two of them standing close in the rain","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p15-1\"><h3><span class=\"ttl\">Ch.1: Left out of the private talk<\/span><span class=\"meta\">Y2V4 · p.15–20<\/span><\/h3><p class=\"setup\">He motions her away so the rain masks a private conversation; reluctant to leave him alone with Amasawa, she eventually gives in and steps back a few meters away — too far to hear.<\/p><p class=\"with\">with <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Jeez. I’m not some bad guy, right Ayanokōji-senpai~? I just wanna chat for a bit, kay?”<span class=\"pg\">p.9<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “What’s with this, Nanase-chan?”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\">“You were about to lay your hands on Ayanokōji-senpai, weren’t you?”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Ah, are you worried about breaking the rules? It’s fine, it’s fine. Even the school can’t monitor everything, you know?”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That… That has nothing to do with you. Why did you come here?”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let go of her arm Nanase.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wow, you’re such a good girl Nanase-chan~! It’s like you’re his loyal dog; it’s a better look for you than I thought.”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Why don’t you just talk from where you are?”<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now then, where oh where should I start~?”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She does not hear the substance of the White Room reveal; she only sees the two of them standing close in the rain.<span class=\"pg\">p.16–17<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p8-1\">← Before: Ch.1: She guards him; names the slope watcher<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p18-1\">→ After: Nanase mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p18-1","v":"y2v4","y":2,"o":19,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase mentioned in passing  nanase did    ayanokoji s interior confirms she was the one who caught sight of amasawa fleeing   slightly behind schedule due to what happened with nanase and the rough patch of weather  i had finally secured the strategic position that i d been aiming for since the very beginning    ayanokoji   however  compared to when i had nanase accompanying me  i was currently a boy traveling on his own    ayanokoji   the information nanase had risked so much to tell me about the trick of the 12th was empty    ayanokoji   remembering what was heard from nanase the other day  instinctively  today is when the first graders are installed    ayanokoji   nanase s words   if they find you  you will become a victim of violence  will come true    ayanokoji   ayanokouji explains that nanase was one of the assassins sent by tsukishiro  since sakayanagi knows the story of the acting director    narration   i know nanase came to see you to gently warn you    hosen   nanase s defeat to me and going our separate ways  he wanted to act just to make a plan to hide around 11th place targeting higher ranks    narration   unlike what happened with nanase  i don t think my method of evading attacks is going to work    ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p18-1\"><h3><span class=\"ttl\">Nanase mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.18, 61, 63, 125, 151, 153, 162, 168, 253, 254<\/span><\/h3><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Nanase did.” — Ayanokōji&#x27;s interior confirms she was the one who caught sight of Amasawa fleeing.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “...slightly behind schedule due to what happened with Nanase and the rough patch of weather, I had finally secured the strategic position that I&#x27;d been aiming for since the very beginning.” — Ayanokōji.<span class=\"pg\">p.61<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “However, compared to when I had Nanase accompanying me, I was currently a boy traveling on his own.” — Ayanokōji.<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “The information Nanase had risked so much to tell me about the trick of the 12th was empty.” — Ayanokōji.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Remembering what was heard from Nanase the other day, instinctively. Today is when the first graders are installed.” — Ayanokōji.<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nanase&#x27;s words, “If they find you, you will become a victim of violence,” will come true.” — Ayanokōji.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Ayanokouji explains that Nanase was one of the assassins sent by Tsukishiro, since Sakayanagi knows the story of the Acting Director.” — narration.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I know Nanase came to see you to gently warn you.” — Hōsen.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Nanase&#x27;s defeat to me and going our separate ways. He wanted to act just to make a plan to hide around 11th place targeting higher ranks.” — narration.<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Unlike what happened with Nanase, I don&#x27;t think my method of evading attacks is going to work.” — Ayanokōji.<span class=\"pg\">p.254<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p15-1\">← Before: Ch.1: Left out of the private talk<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p21-1\">→ After: Ch.1: The footprints; she pushes the GPS idea<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p21-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa","q":"nanase tsubasa ch 1  the footprints  she pushes the gps idea  senpai   amasawa san s  footprints  is there something wrong with her footprints   senpai  let s do a gps search right now  it hasn t been that long since amasawa san first approached us  even if this mystery person ran away at full speed  they shouldn t have been able to get very far with the weather like this  right   then that s our guy   it s worth our while to spend the point on a search then  right   it still feels like a bit of a waste to not even check  she overrules herself  amasawa s footprints were clean  the mystery set was larger  she is frustrated by his gps veto but cannot disprove the  bait  theory  she accepts his judgment  both textbook detective and loyal ally  she cannot let a suspect walk away but yields to his read of the board","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p21-1\"><h3><span class=\"ttl\">Ch.1: The footprints; she pushes the GPS idea<\/span><span class=\"meta\">Y2V4 · p.21–27<\/span><\/h3><ul class=\"lines\"><li class=\"q spoken\">“Senpai…?”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\">“Amasawa-san’s… footprints? Is there something wrong with her footprints?”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\">“Senpai, let’s do a GPS Search right now! It hasn’t been that long since Amasawa-san first approached us. Even if this mystery person ran away at full speed, they shouldn’t have been able to get very far with the weather like…”<span class=\"pg\">p.26<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Senpai, let’s do a GPS Search right now! It hasn’t been that long since Amasawa-san first approached us. Even if this mystery person ran away at full speed, they shouldn’t have been able to get very far with the weather like this, right?”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…Then that’s our guy.”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s worth our while to spend the point on a search then, right?”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It still feels like a bit of a waste to not even check.”<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She overrules herself: Amasawa’s footprints were clean; the mystery set was larger; she is frustrated by his GPS veto but cannot disprove the “bait” theory; she accepts his judgment.<span class=\"pg\">p.21–27<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Both textbook detective and loyal ally; she cannot let a suspect walk away but yields to his read of the board.<span class=\"pg\">p.21–27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p18-1\">← Before: Nanase mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p28-1\">→ After: Ch.1: The tent visit; her confession of hostility<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p28-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa","q":"nanase tsubasa ch 1  the tent visit  her confession of hostility from across in her own tent she calls out through the rain and joins him  she sits in his tent dripping wet with a towel draped over her   i d like to talk to you for a bit  senpai  is it alright if i come and join you   hah  i m sorry for intruding upon your rest  senpai   i m pretty shameless  aren t i   i treated you with such hostility for the longest time  senpai  saying all sorts of terrible things straight to your face  you must be annoyed that i m reaching out all buddy buddy like this   i haven t been able to get the image of amasawa san out of my mind  showing up out of nowhere in the rain  when i started thinking about all the hardships you ve been put through  i just  i felt like i had to call out to you   i convinced myself that amasawa san was the one who pushed komiya senpai and kinoshita senpai down the slope  i thought that she was just hiding her true nature because she wanted to hide the truth  but then you said that she wasn t necessarily the culprit and now i just don t know what to believe anymore   that  uhm  wouldn t that be strange though   even if amasawa san isn t the real culprit  they d still have to be someone she knows  right  therefore  isn t it also possible that she s an accomplice of some sort   i suppose it s not hard to imagine that amasawa san is capable of exercising violence in much the same way   it d be weird if amasawa san was completely unrelated  right  i mean  her watch just  happened  to be broken when komiya and kinoshita just  happened  to get attacked  and she just  happened  to be watching from somewhere nearby  and to top it all off  i just  happened  to catch sight of her as she fled the scene   what  no  thank you for placing your trust in me  i m very grateful  overwhelmed by guilt  she apologizes for months of hostility  she is moved by his trust  points hidden from her  walkie talkie level screenshot knowledge  she pushes the theory that amasawa s associate is the real attacker","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p28-1\"><h3><span class=\"ttl\">Ch.1: The tent visit; her confession of hostility<\/span><span class=\"meta\">Y2V4 · p.28–36<\/span><\/h3><p class=\"setup\">From across in her own tent she calls out through the rain and joins him; she sits in his tent dripping wet with a towel draped over her.<\/p><ul class=\"lines\"><li class=\"q spoken\">“I’d like to talk to you for a bit, Senpai! Is it alright if I come and join you!?”<span class=\"pg\">p.29<\/span><\/li><li class=\"q spoken\">“Hah… I’m sorry for intruding upon your rest, Senpai.”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\">“I’m pretty shameless, aren’t I?”<span class=\"pg\">p.30<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I treated you with such hostility for the longest time, Senpai. Saying all sorts of terrible things straight to your face… You must be annoyed that I’m reaching out all buddy-buddy like this.”<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I haven’t been able to get the image of Amasawa-san out of my mind, showing up out of nowhere in the rain… When I started thinking about all the hardships you’ve been put through, I just… I felt like I had to call out to you.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I convinced myself that Amasawa-san was the one who pushed Komiya-senpai and Kinoshita-senpai down the slope. I thought that she was just hiding her true nature because she wanted to hide the truth, but then you said that she wasn’t necessarily the culprit and now I just don’t know what to believe anymore…”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That… Uhm, wouldn’t that be strange though?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even if Amasawa-san isn’t the real culprit, they’d still have to be someone she knows, right? Therefore, isn’t it also possible that she’s an accomplice of some sort?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I suppose it’s not hard to imagine that Amasawa-san is capable of exercising violence in much the same way.”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’d be weird if Amasawa-san was completely unrelated, right? I mean, her watch just ‘happened’ to be broken when Komiya and Kinoshita just ‘happened’ to get attacked, and she just ‘happened’ to be watching from somewhere nearby? And to top it all off, I just ‘happened’ to catch sight of her as she fled the scene?”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What? No! Thank you for placing your trust in me! I’m very grateful!”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Overwhelmed by guilt, she apologizes for months of hostility; she is moved by his trust (points hidden from her, walkie-talkie-level screenshot knowledge); she pushes the theory that Amasawa’s associate is the real attacker.<span class=\"pg\">p.28–36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p21-1\">← Before: Ch.1: The footprints; she pushes the GPS idea<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p36-1\">→ After: Ch.1: The screenshots; the 10-point gap; the fish-school strategy<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p36-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nagumo-miyabi kouenji-rokusuke amasawa-ichika nanase-tsubasa","q":"nanase tsubasa ch 1  the screenshots  the 10 point gap  the fish school strategy  wait  isn t your score somehow  lower than expected   there are arrival bonuses  early bird bonuses  and tasks  then subtracting points for any penalties  ah  i m also assuming that you took first place in the tasks you took part in while i was taking a break   but you only have 78  10 points less  i don t think i forgot a penalty or something either   uhm  i already understand what you used your points on  senpai  and i agree that if you know where everyone s moving on an hourly basis  you might be able to find out which tables they belong to  however  it didn t seem like you were doing very much with your tablet yesterday  and it s not very easy information to memorize either  are you  are you really telling me that you memorized everything in an instant   i say this with all due respect  but is this really worth paying ten whole points for  if it was possible to share the screenshots with someone  then there might be some added value  but it d take a considerable amount of time for one person to analyze the movement patterns on their own  wouldn t it   i didn t even realize that you had done this  senpai   there are so many groups moving around together  almost like they re a school of fish   are they  doing this to monopolize tasks   however  groups other than president nagumo s won t be able to score points as a result  right  i can t imagine that they re all part of the same table either  working together for the success of a specific group  it s an idea that pretty much anyone could come up with  but it d be impossible to put it into practice effectively   they  they re all from groups down at the bottom of the rankings   that would be due to class points and the overarching threat of expulsion  of course   would they really want to let nagumo win  even at the cost of their own expulsion  even if they can t rise up to class a  i can t imagine that they d want to leave the school  right   in a way  i can t even tell who s running this exam anymore  the school or the student council president   i think i understand now  you re saying that  for you  it wasn t a very big risk to spend ten points in exchange for this information  right senpai   koenji senpai sure is amazing  isn t he  giving president nagumo a run for his money all by himself   senpai  this looks like it could end up changing everything   eh  ah  sorry   i ll head back to my own tent then   as soon as the rain stops  i think i m going to try to chase after amasawa san  it s clear enough that she s from the white room  and i m concerned with what she s planning to do after this  her arithmetic is nearly perfect   she catches the 10 point discrepancy from arrival early bird bonuses and his solo first places  she reads the third year coalition as  a school of fish  can t tell who runs the exam anymore  she falls asleep mid conversation after exerting herself beyond her limits  mountain climb   nanase ayanokoji fight  and vows to trail amasawa once the rain stops  she pieces together the third year coalition from b8 hour by hours  admires his brilliance and fears the class competition is already lost for the third years  she calls him amazing for giving nagumo a run for his money alone  swears to chase her when the rain stops","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p36-1\"><h3><span class=\"ttl\">Ch.1: The screenshots; the 10-point gap; the fish-school strategy<\/span><span class=\"meta\">Y2V4 · p.36–46<\/span><\/h3><p class=\"with\">with <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Wait, isn’t your score somehow… lower than expected?”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\">“There are Arrival Bonuses, Early Bird Bonuses, and Tasks… then subtracting points for any penalties─ Ah, I’m also assuming that you took first place in the Tasks you took part in while I was taking a break.”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\">“But you only have 78, 10 points less. I don’t think I forgot a penalty or something either…”<span class=\"pg\">p.35<\/span><\/li><\/ul><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Uhm, I already understand what you used your points on, Senpai. And I agree that if you know where everyone’s moving on an hourly basis, you might be able to find out which Tables they belong to. However, it didn’t seem like you were doing very much with your tablet yesterday, and it’s not very easy information to memorize either… Are you… Are you really telling me that you memorized everything in an instant?”<span class=\"pg\">p.36<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I say this with all due respect, but is this really worth paying ten whole points for? If it was possible to share the screenshots with someone, then there might be some added value, but it’d take a considerable amount of time for one person to analyze the movement patterns on their own, wouldn’t it?”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I didn’t even realize that you had done this, Senpai.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are so many groups moving around together… almost like they’re a school of fish.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are they… doing this to monopolize Tasks?”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “However, groups other than President Nagumo’s won’t be able to score points as a result, right? I can’t imagine that they’re all part of the same Table either. Working together for the success of a specific group… It’s an idea that pretty much anyone could come up with, but it’d be impossible to put it into practice effectively.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “They… they’re all from groups down at the bottom of the rankings…”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That would be due to class points and the overarching threat of expulsion, of course.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Would they really want to let Nagumo win, even at the cost of their own expulsion? Even if they can’t rise up to Class A, I can’t imagine that they’d want to leave the school, right?”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In a way, I can’t even tell who’s running this exam anymore: the school or the student council president.”<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think I understand now. You’re saying that, for you, it wasn’t a very big risk to spend ten points in exchange for this information, right Senpai?”<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kōenji-senpai sure is amazing, isn’t he? Giving President Nagumo a run for his money all by himself.”<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Senpai, this looks like it could end up changing everything.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh? Ah…! Sorry!”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “…I’ll head back to my own tent then.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As soon as the rain stops, I think I’m going to try to chase after Amasawa-san. It’s clear enough that she’s from the White Room, and I’m concerned with what she’s planning to do after this.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her arithmetic is nearly perfect — she catches the 10-point discrepancy from arrival/early-bird bonuses and his solo first places; she reads the third-year coalition as “a school of fish,” can’t tell who runs the exam anymore; she falls asleep mid-conversation after exerting herself beyond her limits (mountain climb + Nanase–Ayanokōji fight) and vows to trail Amasawa once the rain stops.<span class=\"pg\">p.36–46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> She pieces together the third-year coalition from B8 hour-by-hours; admires his brilliance and fears the class competition is already lost for the third years.<span class=\"pg\">p.38–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> She calls him amazing for giving Nagumo a run for his money alone.<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Swears to chase her when the rain stops.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p28-1\">← Before: Ch.1: The tent visit; her confession of hostility<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p47-1\">→ After: Ch.1: Sent off with warnings<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p47-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi nanase-tsubasa","q":"nanase tsubasa ch 1  sent off with warnings  i m not clear on all the details  but from what you re saying she must be an extremely dangerous opponent   yes  given his sheer strength  he s not an opponent i can handle either   i m not afraid of getting expelled  ayanokoji senpai  i ll do anything if it means protecting you  no matter the cost   that  that would be unacceptable of me  i can t be causing you any more trouble than i already have   i understand  i promise  she hears the warning  hosen  no underestimating amasawa by gender age  as a rallying cry and vows to protect him at any cost  he reframes it   her carelessness may cost him  she tears up and promises to be careful  her other group member  he tells her hosen is beyond her handling  she concedes it","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p47-1\"><h3><span class=\"ttl\">Ch.1: Sent off with warnings<\/span><span class=\"meta\">Y2V4 · p.47–50<\/span><\/h3><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m not clear on all the details, but from what you’re saying she must be an extremely dangerous opponent.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“Yes. Given his sheer strength, he’s not an opponent I can handle either.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“I’m not afraid of getting expelled, Ayanokōji-senpai. I’ll do anything if it means protecting you, no matter the cost.”<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “That… That would be unacceptable of me. I can’t be causing you any more trouble than I already have…”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand, I promise.”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She hears the warning (Hōsen, no underestimating Amasawa by gender/age) as a rallying cry and vows to protect him at any cost; he reframes it — her carelessness may cost him; she tears up and promises to be careful.<span class=\"pg\">p.47–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Her other group member; he tells her Hōsen is beyond her handling; she concedes it.<span class=\"pg\">p.47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p36-1\">← Before: Ch.1: The screenshots; the 10-point gap; the fish-school strategy<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p51-1\">→ After: Ch.2: Parting at area E3<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p51-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka amasawa-ichika nanase-tsubasa","q":"nanase tsubasa ch 2  parting at area e3 after the rain clears by 6 00 am she tells him she s all packed  the two walk together to e3  both heading to the same area  on the way they compare notes on amasawa s movements   amasawa s most likely just going to head to the next designated area  right   amasawa san was following us as of the evening of the sixth day or the morning of the seventh  right   without putting too much thought into it  it s probably safe to assume that she approached us using a gps search on the morning of the seventh   naturally  i ve referenced this with the data on my tablet already  but  as far as i recall  our score didn t go down whatsoever yesterday   although it s unknown where on the island amasawa san was that morning  you and i were traveling quite fast at the time  it wouldn t have been very easy for her to catch up to us unless she was already somewhere nearby  right   it looks like this is where we part ways  senpai  at least for now   how do you plan on joining up with amasawa and hosen   i can t imagine that i d cross paths with them by aimlessly wandering around the island  but it s not like i can waste a bunch of points searching for them either  with that being the case  i ll start out by using the point i just got and try my best to chase after their gps signals  if i can t find them after that  i guess i ll just travel to the next designated area   i think it ll take a first year student like me to poke around and find out what other first years are up to  if i catch wind that something bad is going down  i ll come running and let you know  ayanokoji senpai  sober about amasawa s surveillance abilities  no group gps search used   score unchanged  proposes tailing her with minimalist searches  knows he is stronger  so she volunteers to infiltrate first year circles for intelligence  walks with him  parts at e3 with her own plan to spy on the first years for him  her target  she intends to chase amasawa with gps searches and watch the first years","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p51-1\"><h3><span class=\"ttl\">Ch.2: Parting at area E3<\/span><span class=\"meta\">Y2V4 · p.51–54<\/span><\/h3><p class=\"setup\">After the rain clears by 6:00 AM she tells him she’s all packed; the two walk together to E3, both heading to the same area; on the way they compare notes on Amasawa’s movements.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Amasawa’s most likely just going to head to the next designated area, right?”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\">“Amasawa-san was following us as of the evening of the sixth day or the morning of the seventh, right?”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Without putting too much thought into it, it’s probably safe to assume that she approached us using a GPS Search on the morning of the seventh.”<span class=\"pg\">p.52<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Naturally, I’ve referenced this with the data on my tablet already, but… as far as I recall, our score didn’t go down whatsoever yesterday.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Although it’s unknown where on the island Amasawa-san was that morning, you and I were traveling quite fast at the time. It wouldn’t have been very easy for her to catch up to us unless she was already somewhere nearby, right?”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It looks like this is where we part ways, Senpai. At least for now.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How do you plan on joining up with Amasawa and Hōsen?”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can’t imagine that I’d cross paths with them by aimlessly wandering around the island, but it’s not like I can waste a bunch of points searching for them either. With that being the case, I’ll start out by using the point I just got and try my best to chase after their GPS signals. If I can’t find them after that, I guess I’ll just travel to the next designated area.”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think it’ll take a first-year student like me to poke around and find out what other first-years are up to. If I catch wind that something bad is going down, I’ll come running and let you know, Ayanokōji-senpai.”<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sober about Amasawa’s surveillance abilities (no group GPS Search used — score unchanged); proposes tailing her with minimalist searches; knows he is stronger, so she volunteers to infiltrate first-year circles for intelligence.<span class=\"pg\">p.51–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Walks with him; parts at E3 with her own plan to spy on the first-years for him.<span class=\"pg\">p.51–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Her target; she intends to chase Amasawa with GPS searches and watch the first-years.<span class=\"pg\">p.51–54<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p47-1\">← Before: Ch.1: Sent off with warnings<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p120-1\">→ After: Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p120-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"ayanokouji-kiyotaka housen-kazuomi tsubaki-sakurako nanase-tsubasa","q":"nanase tsubasa ch 4  2 30 a m  nanase s warning in the middle of the night she slips to his tent   she was working with hosen all day  she came straight to him with the leak   it s me  nanase   i m fine  i was in i9 like you  in fact  i even saw you from afar at night  but since i was working with housen kun  so i decided to avoid contact   there is something i need to tell you as soon as possible  today  well  the date has already changed  so it was yesterday to be exact  but housen kun told me that on the twelfth day  the first years will make a great play on ayanokouji senpai   a great play  it sure isn t the only thing   no  no  let me tell you in order  she explains  around the ninth day an errand boy from one of the first year groups showed up with a walkie talkie and asked for hosen s help again   he wants to force ayanokoji senpai to withdraw at the exam s end  and to hunt down and remove seniors performing alone  specifics would be communicated on the day  hosen holds the walkie talkie but has no intention of cooperating   he s pretending to go along   who is in charge   i don t know  but tsubaki was the main person i spoke to on the walkie talkie   she didn t seem like the type that has long been outdoors   i agree with you  because i had the impression that class c was more focused on utomiya  but utomiya and housen don t get along  and when it comes to arguing  they quickly get into quarrels  so tsubaki may have been deliberately chosen to act as an intermediary   oh no  thanks for that  but that s enough for this uninhabited island exam  if you see a freshman moving around  you don t have to come tell me  and you don t have to help me   nevertheless   nanase  you have given me enough information  now you must do what you have to do as one of the group of housen and amasawa   if ayanokouji senpai says so  i understand   she risks her cover at 2 30 a m  to pass the leak  she knows hosen pretends to cooperate  she reports whatever she hears  he cuts her loose so she can protect her cover  her leak is his edge  he sends her away so she stays an operative  pretending to cooperate  holds the walkie talkie  the main person on the walkie talkie","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p120-1\"><h3><span class=\"ttl\">Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/span><span class=\"meta\">Y2V4 · p.120–122<\/span><\/h3><p class=\"setup\">In the middle of the night she slips to his tent — she was working with Hōsen all day; she came straight to him with the leak.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It&#x27;s me, Nanase.”<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\">“I&#x27;m fine; I was in I9 like you. In fact, I even saw you from afar at night, but since I was working with Housen-kun, so I decided to avoid contact.”<span class=\"pg\">p.120<\/span><\/li><li class=\"q spoken\">“There is something I need to tell you as soon as possible ...Today... well, the date has already changed, so it was yesterday to be exact, but Housen-kun told me that on the twelfth day, the first years will make a great play on…”<span class=\"pg\">p.120<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There is something I need to tell you as soon as possible ...Today... well, the date has already changed, so it was yesterday to be exact, but Housen-kun told me that on the twelfth day, the first years will make a great play on Ayanokouji-senpai.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A great play? It sure isn&#x27;t the only thing.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, no, let me tell you in order.”<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She explains: around the ninth day an errand boy from one of the first-year groups showed up with a walkie-talkie and asked for Hōsen&#x27;s help again — he wants to force Ayanokōji-senpai to withdraw at the exam&#x27;s end, and to hunt down and remove seniors performing alone. Specifics would be communicated on the day; Hōsen holds the walkie-talkie but has no intention of cooperating — he&#x27;s pretending to go along.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Who is in charge?”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know, but Tsubaki was the main person I spoke to on the walkie-talkie.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She didn&#x27;t seem like the type that has long been outdoors.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I agree with you, because I had the impression that Class C was more focused on Utomiya. But Utomiya and Housen don&#x27;t get along, and when it comes to arguing, they quickly get into quarrels, so Tsubaki may have been deliberately chosen to act as an intermediary.”<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh no, thanks for that, but that&#x27;s enough for this uninhabited island exam. If you see a freshman moving around, you don&#x27;t have to come tell me, and you don&#x27;t have to help me.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nevertheless...”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nanase, you have given me enough information. Now you must do what you have to do as one of the group of Housen and Amasawa.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If Ayanokouji senpai says so, I understand ...”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She risks her cover at 2:30 a.m. to pass the leak; she knows Hōsen pretends to cooperate; she reports whatever she hears; he cuts her loose so she can protect her cover.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her leak is his edge; he sends her away so she stays an operative.<span class=\"pg\">p.120–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Pretending to cooperate; holds the walkie-talkie.<span class=\"pg\">p.120–121<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> The main person on the walkie-talkie.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p51-1\">← Before: Ch.2: Parting at area E3<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p126-1\">→ After: Ch.5: The tent at day nine; the insult over her figure<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4-p126-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"housen-kazuomi tsubaki-sakurako nanase-tsubasa","q":"nanase tsubasa ch 5  the tent at day nine  the insult over her figure a shadow falls beside hosen s tent  she approaches as his groupmate to ask for housen s help with ayanokoji senpai  he mocks her body before listening   good morning  housen kun   oh   it s me  nanase   i know from your voice  what are you doing here   what do you mean  we are a group and it is not unnatural for us to make contact   i don t know if you can say that  you seem to have had a lot of fun with ayanokouji  how have you been   there is no  i was no match for him   ha  you didn t even use your woman s weapon to challenge him head on  did you   a woman s weapon   i do not know what you re talking about   you have big breasts  but you don t have any brain   well  i really don t understand the relationship between the size of my breasts and my head   it s enough  and that  did you come here just to make that report   it was a mistake for me to try to expel ayanokouji kun by myself  so i have come to ask for housen kun s help  if you have a plan  let me hear it   leave it  i ll do it myself    i ll wait until you change your mind   go to the designated area  for god s sake  the only thing you can do is avoid a penalty   it seems we have a visitor   i don t know what you re talking about  after the negotiation concludes  she reveals she stayed to tail him   and asks to be by his side until she learns more from tsubaki san  this would require repeated gps searches  he decided that if tsubaki was going to provide him with all these things  it would be in her best interest to do so   because i want to protect the first year d class group too  please let me be by your side until i get more information from tsubaki san   do whatever you want  she follows hosen relentlessly to tail tsubaki  hosen mocks her body  she stays close to the action   and reports back through the walkie talkie to ayanokoji  her group leader  he tolerates her shadowing him  her stakeout target   the information she wants","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4-p126-1\"><h3><span class=\"ttl\">Ch.5: The tent at day nine; the insult over her figure<\/span><span class=\"meta\">Y2V4 · p.126–133<\/span><\/h3><p class=\"setup\">A shadow falls beside Hōsen&#x27;s tent; she approaches as his groupmate to ask for Housen&#x27;s help with Ayanokōji-senpai; he mocks her body before listening. After the negotiation concludes, she reveals she stayed to tail him — and asks to be by his side until she learns more from Tsubaki-san.<\/p><p class=\"with\">with <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"tsubaki-sakurako.html\">Tsubaki Sakurako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Good morning, Housen-kun.”<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hōsen Kazuomi<\/b> “Oh?”<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\">“It&#x27;s me, Nanase.”<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>22 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I know from your voice. What are you doing here?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do you mean? We are a group and it is not unnatural for us to make contact.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know if you can say that. You seem to have had a lot of fun with Ayanokouji, how have you been?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is no .......I was no match for him.”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ha, you didn&#x27;t even use your woman&#x27;s weapon to challenge him head on, did you?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A woman&#x27;s weapon.....?”<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I do not know what you&#x27;re talking about”,<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You have big breasts, but you don&#x27;t have any brain.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I really don&#x27;t understand the relationship between the size of my breasts and my head.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s enough. And that? Did you come here just to make that report?”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It was a mistake for me to try to expel Ayanokouji-kun by myself. So I have come to ask for Housen-kun&#x27;s help. If you have a plan, let me hear it.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Leave it, I&#x27;ll do it myself.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...... I&#x27;ll wait until you change your mind.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Go to the designated area, for God&#x27;s sake. The only thing you can do is avoid a penalty.”<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It seems we have a visitor.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know what you&#x27;re talking about”,<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> This would require repeated GPS searches. He decided that if Tsubaki was going to provide him with all these things, it would be in her best interest to do so.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because I want to protect the first year D-class group too. Please let me be by your side until I get more information from Tsubaki-san.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do whatever you want.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She follows Hōsen relentlessly to tail Tsubaki; Hōsen mocks her body; she stays close to the action — and reports back through the walkie-talkie to Ayanokōji.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Her group leader; he tolerates her shadowing him.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsubaki Sakurako<\/b> Her stakeout target — the information she wants.<span class=\"pg\">p.129–139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4-p120-1\">← Before: Ch.4: 2:30 a.m.; Nanase&#x27;s warning<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p10-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"ishizaki-daichi sakayanagi-arisu nanase-tsubasa","q":"nanase tsubasa relations in this volume  depth pass  ishizaki teases ayanokoji about dating her  she runs away  sakayanagi s ss watches her  she never sees it","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p10-1\"><h3><span class=\"ttl\">Relations in this volume (depth pass)<\/span><span class=\"meta\">Y2V4.5 · p.10–290<\/span><\/h3><p class=\"with\">with <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Ishizaki teases Ayanokōji about dating her; she runs away.<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Sakayanagi&#x27;s SS watches her; she never sees it.<span class=\"pg\">p.287–288<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p73-1\">→ After: Nanase on the bow deck; lunch interrupted<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p73-1","v":"y2v4.5","y":2,"o":20,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase on the bow deck  lunch interrupted ayanokoji  giving up on the crowded bow deck  finds nanase alone on a bench with a sandwich and milk    it was the opposite of yesterday  where she was the one that found me  she freezes mid bite  he asks about yesterday  she deflects   she solved it herself   ah  senfai   gulp um  i m sorry  but actually i was eating lunch   i m sorry  but i ve already solved the problem myself  so could you just forget about it   senfai  is printed as such in the translation  kept as printed  yesterday s problem is never stated  she keeps it rather than shares it  the main text and the short story both keep her secret  uses him as an excuse to face the deck  he uses her as an excuse to stop and eat  both pretend it s coincidence","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p73-1\"><h3><span class=\"ttl\">Nanase on the bow deck; lunch interrupted<\/span><span class=\"meta\">Y2V4.5 · p.73–77<\/span><\/h3><p class=\"setup\">Ayanokōji, giving up on the crowded bow deck, finds Nanase alone on a bench with a sandwich and milk — &quot;It was the opposite of yesterday, where she was the one that found me.&quot; She freezes mid-bite; he asks about yesterday; she deflects — she solved it herself.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ah, senfai.”<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\">“Gulp…Um, I&#x27;m sorry, but actually…I was eating lunch.”<span class=\"pg\">p.75<\/span><\/li><li class=\"q spoken\">“I&#x27;m sorry, but I&#x27;ve already solved the problem myself, so could you just forget about it?”<span class=\"pg\">p.77<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> &quot;senfai&quot; is printed as such in the translation; kept as printed.<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Yesterday&#x27;s problem is never stated; she keeps it rather than shares it (the main text and the short story both keep her secret).<span class=\"pg\">p.77<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Uses him as an excuse to face the deck; he uses her as an excuse to stop and eat; both pretend it&#x27;s coincidence.<span class=\"pg\">p.73–77<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p10-1\">← Before: Relations in this volume (depth pass)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p182-1\">→ After: Nanase and Ryūen interrogate Kurachi (the cliff attacker)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p182-1","v":"y2v4.5","y":2,"o":20,"k":"spoken","w":"ryuuen-kakeru utomiya-riku ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa nanase and ryuen interrogate kurachi  the cliff attacker  ryuen  investigating who pushed komiya  stops nanase during the treasure hunt  she agrees to help question kurachi naohiro  the first year who attacked ayanokoji on day seven   nanase tsubasa  right   tell me why you were targeting ayanokoji senpai during the uninhabited island exam   is urgently trying to find the culprit who almost attacked ayanokoji senpai   i was told i d be given money if i attacked ayanokoji senpai   give me time  of course  i don t mean for free  deftly interrogates kurachi using the threat of hosen s fists  plus ryuen behind her  learns utomiya riku paid him  anonymously  before the exam  to  pretend  to attack ayanokoji  brokers a deal with ryuen   she ll reveal a witness in komiya s case if he doesn t contact utomiya yet  works with him  reluctantly  to find the attacker  he wants to confront utomiya  she negotiates delay  revealed as the one who paid kurachi to attack ayanokoji  investigates his attacker without his permission   a  defence plan  of her own","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p182-1\"><h3><span class=\"ttl\">Nanase and Ryūen interrogate Kurachi (the cliff attacker)<\/span><span class=\"meta\">Y2V4.5 · p.182–191<\/span><\/h3><p class=\"setup\">Ryūen (investigating who pushed Komiya) stops Nanase during the treasure hunt; she agrees to help question Kurachi Naohiro, the first-year who attacked Ayanokōji on day seven.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;Nanase Tsubasa, right?&quot;<span class=\"pg\">p.183<\/span><\/li><li class=\"q spoken\">&quot;Tell me why you were targeting Ayanokōji-senpai during the uninhabited island exam.&quot;<span class=\"pg\">p.188<\/span><\/li><li class=\"q spoken\">&quot;is urgently trying to find the culprit who almost attacked Ayanokōji-senpai.&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I was told I&#x27;d be given money if I attacked Ayanokōji-senpai…&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Give me time. Of course, I don&#x27;t mean for free.&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deftly interrogates Kurachi using the threat of Hōsen&#x27;s fists (plus Ryūen behind her), learns Utomiya Riku paid him (anonymously, before the exam) to &quot;pretend&quot; to attack Ayanokōji; brokers a deal with Ryūen — she&#x27;ll reveal a witness in Komiya&#x27;s case if he doesn&#x27;t contact Utomiya yet.<span class=\"pg\">p.182–191<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Works with him (reluctantly) to find the attacker; he wants to confront Utomiya, she negotiates delay.<span class=\"pg\">p.182–191<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Revealed as the one who paid Kurachi to attack Ayanokōji.<span class=\"pg\">p.189–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Investigates his attacker without his permission — a &quot;defence plan&quot; of her own.<span class=\"pg\">p.188<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p73-1\">← Before: Nanase on the bow deck; lunch interrupted<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p283-1\">→ After: Short story: &quot;A Double-sided Favour Repayment&quot; — tailing Kurachi<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v4_5-p283-1","v":"y2v4.5","y":2,"o":20,"k":"narration","w":"ayanokouji-kiyotaka kurachi nanase-tsubasa","q":"nanase tsubasa short story   a double sided favour repayment    tailing kurachi from her own pov  tails first year kurachi through the store  buying a sandwich and milk to blend in   he appeared on her gps search for ayanokoji s attacker   because if i could leave behind at least something for ayanokouji senpai  it would have been worth it   yes  this is my own decision   nanase   phease huht waid a bid   sorry  that s something i ve already taken care of so can i ask you to forget about it   i m sorry  ayanokouji senpai  i already knew i should have just told you all this upfront  devoted and secretive   she s investigating the attack on her own  keeping it from ayanokoji  to leave behind  some accomplishments  refuses the easy path of letting him  pamper  her  and hides the tailing from him even when he calls her out   apologizing internally  resolved to  work hard  for him  the  double sided favour  of the title reflects her divided loyalty  she hides her investigation from him  then regrets it   he s too kind and would have stopped her  the first year she tails   suspect in the attack on ayanokoji","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v4_5-p283-1\"><h3><span class=\"ttl\">Short story: &quot;A Double-sided Favour Repayment&quot; — tailing Kurachi<\/span><span class=\"meta\">Y2V4.5 · p.283–286<\/span><\/h3><p class=\"setup\">From her own POV, tails first-year Kurachi through the store, buying a sandwich and milk to blend in — he appeared on her GPS search for Ayanokōji&#x27;s attacker.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"index.html#kurachi\">Kurachi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">&quot;Because if I could leave behind at least something for Ayanokouji-senpai, it would have been worth it.&quot;<span class=\"pg\">p.283<\/span><\/li><li class=\"q narration\">&quot;Yes, this is my own decision.&quot;<span class=\"pg\">p.283<\/span><\/li><li class=\"q narration\">&quot;Nanase.&quot;<span class=\"pg\">p.284<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Phease huht waid a bid.&quot;<span class=\"pg\">p.284<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Sorry, That&#x27;s something I&#x27;ve already taken care of so can I ask you to forget about it?&quot;<span class=\"pg\">p.285<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;m sorry, Ayanokouji-senpai… I already knew I should have just told you all this upfront.&quot;<span class=\"pg\">p.286<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Devoted and secretive — she&#x27;s investigating the attack on her own (keeping it from Ayanokōji) to leave behind &quot;some accomplishments,&quot; refuses the easy path of letting him &quot;pamper&quot; her, and hides the tailing from him even when he calls her out — apologizing internally, resolved to &quot;work hard&quot; for him; the &quot;double-sided favour&quot; of the title reflects her divided loyalty.<span class=\"pg\">p.283–286<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She hides her investigation from him, then regrets it — he&#x27;s too kind and would have stopped her.<span class=\"pg\">p.284–286<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kurachi<\/b> The first-year she tails — suspect in the attack on Ayanokōji.<span class=\"pg\">p.283–285<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v4_5-p182-1\">← Before: Nanase and Ryūen interrogate Kurachi (the cliff attacker)<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v6-p279-1","v":"y2v6","y":2,"o":22,"k":"spoken","w":"amasawa-ichika horikita-suzune nanase-tsubasa","q":"nanase tsubasa ch 5  nanase s turnaround  horikita s pov  her first match with ease and we watch amasawa san s team  nanase san is far better than they thought  she controls the match with sharp offense and defense   she wins with amasawa barely touching the ball  by the final  she goes from a quiet player to a monster who gets the ball to land out of bounds   a stuff block  i think  i m not too familiar with it myself  though   ahh  sorry  nanase chan  i missed  it s pretty hard to control it perfectly  huh   oh  time s up  it was just starting to get interesting  a girl who flies under the radar   but is actually carrying amasawa s team  once she wakes up  she will outpace everyone  she reads the final s last volleyball like it was meant for her  her teammate and anchor   she holds her up while she adapts  the first year that outclassed everyone   she beat her in the final 7 6","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v6-p279-1\"><h3><span class=\"ttl\">Ch.5: Nanase&#x27;s turnaround (Horikita&#x27;s POV)<\/span><span class=\"meta\">Y2V6 · p.279–285<\/span><\/h3><p class=\"setup\">Her first match with ease and we watch Amasawa-san&#x27;s team; Nanase-san is far better than they thought; she controls the match with sharp offense and defense — she wins with Amasawa barely touching the ball; by the final, she goes from a quiet player to a monster who gets the ball to land out of bounds.<\/p><p class=\"with\">with <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“A stuff block, I think. I’m not too familiar with it myself, though.”<span class=\"pg\">p.282<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Ahh. Sorry, Nanase-chan, I missed~ It’s pretty hard to control it perfectly, huh?”<span class=\"pg\">p.284<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amasawa Ichika<\/b> “Oh, time’s up. It was just starting to get interesting!”<span class=\"pg\">p.284<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> A girl who flies under the radar — but is actually carrying Amasawa&#x27;s team; once she wakes up, she will outpace everyone; she reads the final&#x27;s last volleyball like it was meant for her.<span class=\"pg\">p.279–285<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Her teammate and anchor — she holds her up while she adapts.<span class=\"pg\">p.279–285<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> The first-year that outclassed everyone — she beat her in the final 7-6.<span class=\"pg\">p.279–285<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v7-p108-1","v":"y2v7","y":2,"o":23,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa named in ayanokoji s count of first years he talks to  i talk to nanase or amasawa once in a while  but that s about it    ayanokoji s list of first year acquaintances  named only   no scene presence","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v7-p108-1\"><h3><span class=\"ttl\">Named in Ayanokōji&#x27;s count of first-years he talks to<\/span><span class=\"meta\">Y2V7 · p.108<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I talk to Nanase or Amasawa once in a while, but that&#x27;s about it.” — Ayanokōji&#x27;s list of first-year acquaintances.<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Named only — no scene presence.<span class=\"pg\">p.108<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v8-p28-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"ayanokouji-kiyotaka yagami-takuya amasawa-ichika nanase-tsubasa","q":"nanase tsubasa nanase  yagami s fear  warnings about the trip  i think he was scared  yagami was afraid of fighting ayanokoji senpai   i want ayanokoji senpai to remain at this school and graduate   the outside world is full of danger  reports a first year s approach to him  reveals yagami was  scared  of fighting ayanokoji  why he lashed out  and warns about dangers on the school trip   the outside world  possible white room involvement  family registers  now openly wants him to stay and graduate  and chides him for being too calm about the danger  she worried about him on the trip    i can t believe i m the one worried about ayanokoji senpai  he was  afraid of fighting  ayanokoji   explains his rampage  he brings up amasawa  she has no new information about her plans for the trip","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v8-p28-1\"><h3><span class=\"ttl\">Nanase: Yagami&#x27;s fear; warnings about the trip<\/span><span class=\"meta\">Y2V8 · p.28–38<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;I think he was scared. Yagami was afraid of fighting Ayanokōji-senpai.&quot;<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\">&quot;I want Ayanokōji-senpai to remain at this school and graduate.&quot;<span class=\"pg\">p.33<\/span><\/li><li class=\"q spoken\">&quot;the outside world is full of danger.&quot;<span class=\"pg\">p.35<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Reports a first-year&#x27;s approach to him, reveals Yagami was &quot;scared&quot; of fighting Ayanokōji (why he lashed out), and warns about dangers on the school trip — the outside world, possible White Room involvement (family registers); now openly wants him to stay and graduate, and chides him for being too calm about the danger.<span class=\"pg\">p.28–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She worried about him on the trip — &quot;I can&#x27;t believe I&#x27;m the one worried about Ayanokōji-senpai.&quot;<span class=\"pg\">p.32–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> He was &quot;afraid of fighting&quot; Ayanokōji — explains his rampage.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> He brings up Amasawa; she has no new information about her plans for the trip.<span class=\"pg\">p.34–37<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v8-p126-1\">→ After: Chocolate-coated potatoes, site-seeing day<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v8-p126-1","v":"y2v8","y":2,"o":24,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa chocolate coated potatoes  site seeing day ayanokoji remembers nanase asked about chocolate coated potatoes as a souvenir  he still has no idea what they are  he ll hunt for them on tomorrow s tour or the final free day  he takes her souvenir wish seriously","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v8-p126-1\"><h3><span class=\"ttl\">Chocolate-coated potatoes, site-seeing day<\/span><span class=\"meta\">Y2V8 · p.126<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Ayanokōji remembers Nanase asked about chocolate-coated potatoes as a souvenir; he still has no idea what they are; he&#x27;ll hunt for them on tomorrow&#x27;s tour or the final free day.<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He takes her souvenir wish seriously.<span class=\"pg\">p.126<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v8-p28-1\">← Before: Nanase: Yagami&#x27;s fear; warnings about the trip<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v8-p176-1\">→ After: Passing-mention record<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v8-p176-1","v":"y2v8","y":2,"o":24,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa passing mention record  including what i felt from nanase  it remained very unclear whether or not the caller was an enemy   ayanokoji  mid sakayanagi meeting","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v8-p176-1\"><h3><span class=\"ttl\">Passing-mention record<\/span><span class=\"meta\">Y2V8 · p.176<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> &quot;Including what I felt from Nanase, it remained very unclear whether or not the caller was an enemy.&quot; (Ayanokōji, mid-Sakayanagi meeting)<span class=\"pg\">p.176<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y2v8-p126-1\">← Before: Chocolate-coated potatoes, site-seeing day<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y2v9-p67-1","v":"y2v9","y":2,"o":25,"k":"spoken","w":"horikita-suzune kushida-kikyou nanase-tsubasa","q":"nanase tsubasa nanase  accepted onto the student council horikita invites her to join the student council  she happily agrees  exchanges contact details  and says she is glad to gain more contacts   umm  what should i do from tomorrow onwards   i m glad to have more contacts as well   yes  i m looking forward to hearing from you  she arrives at the council room  greets horikita politely and chats easily with kushida  nagumo formally approves her as a new member from class 1 d   good evening  horikita senpai  cheerful  socially eager and polite   delighted at the chance to join and quick to bond with her fellow new member  recruited by her  calls her senpai  hits it off with her immediately in the council room","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v9-p67-1\"><h3><span class=\"ttl\">Nanase: accepted onto the student council<\/span><span class=\"meta\">Y2V9 · p.67–73<\/span><\/h3><p class=\"setup\">Horikita invites her to join the student council; she happily agrees, exchanges contact details, and says she is glad to gain more contacts. She arrives at the council room, greets Horikita politely and chats easily with Kushida; Nagumo formally approves her as a new member from Class 1-D.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Umm, what should I do from tomorrow onwards?&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\">&quot;I&#x27;m glad to have more contacts as well!&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\">&quot;Yes, I&#x27;m looking forward to hearing from you!&quot;<span class=\"pg\">p.67<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Good evening, Horikita-senpai.&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cheerful, socially eager and polite — delighted at the chance to join and quick to bond with her fellow new member.<span class=\"pg\">p.67–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Recruited by her; calls her senpai.<span class=\"pg\">p.67–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Hits it off with her immediately in the council room.<span class=\"pg\">p.73<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v9_5-p63-1","v":"y2v9.5","y":2,"o":26,"k":"spoken","w":"ichinose-honami housen-kazuomi nanase-tsubasa","q":"nanase tsubasa ch 3  christmas photo with ichinose and hosen finds ichinose and ayanokoji mid photo session  joins  together they pose  she bumps into hosen and drags him over  pushes hosen into the photo  later whispers to ayanokoji that hosen came because he likes ichinose  used her to get close   sorry  can you wait a moment  photo partner  ferry service between hosen and the mall  she walks ahead of him  relays his intent to ayanokoji in confidence","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v9_5-p63-1\"><h3><span class=\"ttl\">Ch.3: Christmas photo with Ichinose and Hōsen<\/span><span class=\"meta\">Y2V9.5 · p.63–65<\/span><\/h3><p class=\"setup\">Finds Ichinose and Ayanokōji mid-photo-session; joins; together they pose; she bumps into Hōsen and drags him over. Pushes Hōsen into the photo; later whispers to Ayanokōji that Hōsen came because he likes Ichinose; used her to get close.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Sorry, can you wait a moment?&quot;<span class=\"pg\">p.63<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Photo partner; ferry service between Hōsen and the mall.<span class=\"pg\">p.63–65<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> She walks ahead of him; relays his intent to Ayanokōji in confidence.<span class=\"pg\">p.64–65<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v11-p70-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 2  the oshibana match group 9   horikita s class   lines up against group 20 for the day 1 oshibana match  nanase asks kiyotaka about oshibana   do you also make oshibana  ayanokoji senpai   i see  i thought you were good at it because you were the only boy participating   please go easy on me  nine out of ten participants are girls  kiyotaka wins his head to head with her  the group takes 3 2  she meets him as an opponent and loses  he compliments the field","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v11-p70-1\"><h3><span class=\"ttl\">Ch.2: The oshibana match<\/span><span class=\"meta\">Y2V11 · p.70–71<\/span><\/h3><p class=\"setup\">Group 9 — Horikita&#x27;s class — lines up against Group 20 for the Day 1 oshibana match; Nanase asks Kiyotaka about oshibana.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Do you also make oshibana, Ayanokōji-senpai?”<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\">“I see. I thought you were good at it because you were the only boy participating.”<span class=\"pg\">p.71<\/span><\/li><li class=\"q spoken\">“Please go easy on me.”<span class=\"pg\">p.71<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Nine out of ten participants are girls; Kiyotaka wins his head-to-head with her; the group takes 3–2.<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She meets him as an opponent and loses; he compliments the field.<span class=\"pg\">p.70–71<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa nanase tsubasa mentioned in passing named in this volume  passing mention  locator pages  p 40  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v12-p12-1\"><h3><span class=\"ttl\">nanase-tsubasa mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.40; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y2v12_5-p148-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa ch 9 mentioned appears in ch 9  appears in this volume","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y2v12_5-p148-1\"><h3><span class=\"ttl\">Ch.9<\/span><span class=\"meta\">Y2V12.5 · p.148-176<\/span><\/h3><p class=\"setup\">Mentioned/appears in Ch.9.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Appears in this volume.<span class=\"pg\">p.148-176<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p10-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro ayanokouji-kiyotaka ayanokouji-atsuomi nanase-tsubasa","q":"nanase tsubasa prologue   depth read  tsukishiro s offer sits beside the unconscious matsuo eiichirou in his hospital room  overwhelmed with regret   how did it come to this   if i d noticed something was wrong with eiichirou kun  this wouldn t have happened   i have brought you an opportunity to exact your revenge   attending anhs is the only way to get close to your target   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   you must mix lies with the truth  her goal has shifted from revenge   to help ayanokoji so he won t become a  pure evil  who creates more victims like eiichirou  is recruited by him to get close to ayanokoji in exchange for revenge  is tasked with approaching him as an insignificant being  now wants to save him  holds him responsible for cornering eiichirou   the true target of her revenge  tsukishiro s mention of  shirogane san  proves he knew nanase since childhood  eiichirou is in a vegetative state   a  prolonged disturbance of consciousness","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-1\"><h3><span class=\"ttl\">Prologue — depth read: Tsukishiro&#x27;s offer<\/span><span class=\"meta\">Y3V2 · p.10–12<\/span><\/h3><p class=\"setup\">Sits beside the unconscious Matsuo Eiichirou in his hospital room, overwhelmed with regret.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;How did it come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\">&quot;If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened.&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her goal has shifted from revenge — to help Ayanokōji so he won&#x27;t become a &quot;pure evil&quot; who creates more victims like Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is recruited by him to get close to Ayanokōji in exchange for revenge.<span class=\"pg\">p.10–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is tasked with approaching him as an insignificant being; now wants to save him.<span class=\"pg\">p.11–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Holds him responsible for cornering Eiichirou — the true target of her revenge.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of &quot;Shirogane-san&quot; proves he knew Nanase since childhood.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Eiichirou is in a vegetative state — a &quot;prolonged disturbance of consciousness.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-2\">→ After: Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p10-2","v":"y3v2","y":3,"o":34,"k":"narration spoken","w":"tsukishiro nanase-tsubasa","q":"nanase tsubasa nanase at eiichirou s bedside  tsukishiro s offer sits beside matsuo eiichirou in his hospital room  murmuring  how did it come to this  as he lies in a vegetative state   how did it come to this   yes  if i  if i d noticed something was wrong with eiichirou kun  this wouldn t have happened  no  i never would have let something like this happen  eiichirou suffers from a  prolonged disturbance of consciousness    a vegetative state  he can open his eyes and breathe but isn t conscious or responsive  doctors gave a slim chance of recovery within weeks or months   you cannot survive in this world on kindness alone  no  in fact  you ll be preyed upon by fiends so wicked they are beyond salvation   the world works on give and take  you understand that  yes   yes  i am grateful for your considerable support  after visiting hospital after hospital  tsukishiro was the one who found a place that would accept eiichirou  thirty minutes later and he might not have survived   what is it you want me to do   i have brought you an opportunity to exact your revenge   i will teach you how to get close to the person you should take revenge on  he offers her revenge in exchange for getting close to a target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-2\"><h3><span class=\"ttl\">Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/span><span class=\"meta\">Y3V2 · p.10–11<\/span><\/h3><p class=\"setup\">Sits beside Matsuo Eiichirou in his hospital room, murmuring &quot;How did it come to this—&quot; as he lies in a vegetative state.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;HOW DID IT come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;You cannot survive in this world on kindness alone. No, in fact, you&#x27;ll be preyed upon by fiends so wicked they are beyond salvation—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;The world works on give-and-take. You understand that, yes?&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;...Yes... If I... If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened, no... I never would have let something like this happen...&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Eiichirou suffers from a &quot;prolonged disturbance of consciousness&quot; — a vegetative state: he can open his eyes and breathe but isn&#x27;t conscious or responsive; doctors gave a slim chance of recovery within weeks or months.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes. I am grateful for your considerable support.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> After visiting hospital after hospital, Tsukishiro was the one who found a place that would accept Eiichirou; thirty minutes later and he might not have survived.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What is it you want me to do?&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will teach you how to get close to the person you should take revenge on.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> He offers her revenge in exchange for getting close to a target.<span class=\"pg\">p.10–11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-1\">← Before: Prologue — depth read: Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p11-1\">→ After: Learning the target; Tsukishiro&#x27;s true nature<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p11-1","v":"y3v2","y":3,"o":34,"k":"narration spoken","w":"tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa learning the target  tsukishiro s true nature tsukishiro places an application form and photograph on the portable table   what is this   attending anhs is the only way to get close to your target   i realize i haven t asked your name  who are you   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   i ve seen plenty of adults approach me  pretending to know things when they really know nothing   is shirogane san doing well  the name shirogane makes her body react unconsciously  betraying her feigned composure   he knew them since childhood  and she instantly understands he is telling the truth   you re not evil  but the inhabitants of the world i live in are nothing but evil   you re ordinary  yet excellent  ordinary  yet immature  ordinary  yet talented   you re tsukishiro san  you said  is this boy connected to that evil   he is ayanokouji kiyotaka  a key figure who will lead you to the target of your revenge  tsukishiro s mention of shirogane    she took good care of me when i was young    reveals he knew nanase and eiichirou since childhood  shirogane is not on the roster  identified in the photograph as the key figure leading to her revenge target","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p11-1\"><h3><span class=\"ttl\">Learning the target; Tsukishiro&#x27;s true nature<\/span><span class=\"meta\">Y3V2 · p.11–12<\/span><\/h3><p class=\"setup\">Tsukishiro places an application form and photograph on the portable table.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;Is Shirogane-san doing well?&quot;<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;What is this...?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;...I realize I haven&#x27;t asked your name... Who are you?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;ve seen plenty of adults approach me, pretending to know things when they really know nothing.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The name Shirogane makes her body react unconsciously, betraying her feigned composure — he knew them since childhood, and she instantly understands he is telling the truth.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re not evil. But the inhabitants of the world I live in are nothing but evil.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re ordinary, yet excellent. Ordinary, yet immature. Ordinary, yet talented.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You&#x27;re Tsukishiro-san, you said. Is this boy connected to that evil?&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;He is Ayanokouji Kiyotaka, a key figure who will lead you to the target of your revenge.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of Shirogane — &quot;she took good care of me when I was young&quot; — reveals he knew Nanase and Eiichirou since childhood (Shirogane is not on the roster).<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Identified in the photograph as the key figure leading to her revenge target.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-2\">← Before: Nanase at Eiichirou&#x27;s bedside; Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p12-1\">→ After: Accepting the mission; the motive shifts<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p12-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro nanase-tsubasa","q":"nanase tsubasa accepting the mission  the motive shifts  that boy  though inorganic  has outstanding  refined instincts  if you approach him carelessly  he will easily see through you   then  what should i do   you must mix lies with the truth   he will naturally be suspicious of you  but he won t delve too deeply  that is because he will recognize you as an insignificant being   let me ask one last thing  why me   it is because you are in a perfect position  neither clearly on one side  nor the other  she nods without a pause   at that time her heart was set on revenge against ayanokouji atsuomi  the one who cornered eiichirou  her motive has since shifted  she now wants to help ayanokouji senpai  believing that if he graduates as he is  he will walk a path of  pure evil  and create more victims like eiichirou   so  knowing that predicament firsthand  she must stop it  shirogane is not on the roster   tsukishiro s remark is recorded here  not as a  rel  to a non existent id","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p12-1\"><h3><span class=\"ttl\">Accepting the mission; the motive shifts<\/span><span class=\"meta\">Y3V2 · p.12<\/span><\/h3><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;That boy, though inorganic, has outstanding, refined instincts. If you approach him carelessly, he will easily see through you.&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\">&quot;Then, what should I do?&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;He will naturally be suspicious of you, but he won&#x27;t delve too deeply. That is because he will recognize you as an insignificant being.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Let me ask one last thing. Why me?&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It is because you are in a perfect position. Neither clearly on one side, nor the other.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> She nods without a pause — at that time her heart was set on revenge against Ayanokouji Atsuomi, the one who cornered Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her motive has since shifted: she now wants to help Ayanokouji-senpai, believing that if he graduates as he is, he will walk a path of &quot;pure evil&quot; and create more victims like Eiichirou — so, knowing that predicament firsthand, she must stop it.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Shirogane is not on the roster — Tsukishiro&#x27;s remark is recorded here, not as a `[rel:]` to a non-existent id.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p11-1\">← Before: Learning the target; Tsukishiro&#x27;s true nature<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p66-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p66-1","v":"y3v2","y":3,"o":34,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p66-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.66–77<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p12-1\">← Before: Accepting the mission; the motive shifts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p78-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p78-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki  assists her in the investigation and is asked to help uncover the truth   you mean their pride was wounded because they lost a two on one fight  it s not out of the question  but would they really be that tight lipped about it   of course  student council president  but being the president is a lot of work  isn t it  you re amazing  horikita senpai   no mediocre  even so  i think that s fine  a mediocre horikita senpai isn t bad at all   w wha  i i m so sorry  i think student council president horikita is very admirable  helpful but awkward   blurted out the honest view that being mediocre is fine and panicked  trying to smooth it over  the two first years kusanagi minato and maki yuuma got into a fight  neither would report it  hinting a third party  possibly a girl  was involved","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p78-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.78–89<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><p class=\"with\">with <a href=\"horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;You mean their pride was wounded because they lost a two-on-one fight? It&#x27;s not out of the question, but would they really be that tight-lipped about it?&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">&quot;Of course, Student Council President. But being the president is a lot of work, isn&#x27;t it? You&#x27;re amazing, Horikita-senpai.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\">&quot;No—mediocre. Even so, I think that&#x27;s fine. A mediocre Horikita-senpai isn&#x27;t bad at all.&quot;<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Assists her in the investigation and is asked to help uncover the truth.<span class=\"pg\">p.85–88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;W-Wha—!? I-I&#x27;m so sorry! I think Student Council President Horikita is very admirable!&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Helpful but awkward — blurted out the honest view that being mediocre is fine and panicked, trying to smooth it over.<span class=\"pg\">p.87–88<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The two first-years Kusanagi Minato and Maki Yuuma got into a fight; neither would report it, hinting a third party (possibly a girl) was involved.<span class=\"pg\">p.86<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p66-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p90-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p90-1","v":"y3v2","y":3,"o":34,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p90-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.90–101<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p78-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p102-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p102-1","v":"y3v2","y":3,"o":34,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p102-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.102–113<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p90-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p114-1\">→ After: Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p114-1","v":"y3v2","y":3,"o":34,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p114-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Nanase and the first-year fight<\/span><span class=\"meta\">Y3V2 · p.114–125<\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p102-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p211-1\">→ After: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p211-1","v":"y3v2","y":3,"o":34,"k":"","w":"nanase-tsubasa","q":"nanase tsubasa ch 7   depth read  nanase works the white room angle meets shiraishi back to back in a quiet restaurant  having called her out","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p211-1\"><h3><span class=\"ttl\">Ch.7 — depth read: Nanase works the White Room angle<\/span><span class=\"meta\">Y3V2 · p.211–222<\/span><\/h3><p class=\"setup\">Meets Shiraishi back-to-back in a quiet restaurant, having called her out.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p114-1\">← Before: Ch.3 — depth read: Nanase and the first-year fight<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p223-1\">→ After: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p223-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka ayanokouji-kiyotaka tsukishiro nanase-tsubasa","q":"nanase tsubasa ch 7   depth read  nanase works the white room angle meets shiraishi back to back in a quiet restaurant  having called her out   have i kept you waiting  cautious and probing   arranged a covert meeting  tries to read shiraishi through emphases and emphasized names  and aligns herself with tsukishiro s anti ayanokoji faction  demands her cooperation intelligence  is refused  and warns her of consequences if expelled  is working against him  refers to him as  ayanokouji senpai   why is that   then why have you started to close the distance now   i am from that side   at least give me some information  please  just disclose the names of your associates   that if i am expelled before ayanokouji senpai s fate is decided  things may very well head in a direction that shirogane sensei would not desire  reveals she is aligned with his faction  that side superiors  cites  shirogane sensei  in her warning   a name tied to her past  not on the roster","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p223-1\"><h3><span class=\"ttl\">Ch.7 — depth read: Nanase works the White Room angle<\/span><span class=\"meta\">Y3V2 · p.223–230<\/span><\/h3><p class=\"setup\">Meets Shiraishi back-to-back in a quiet restaurant, having called her out.<\/p><p class=\"with\">with <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Have I kept you waiting?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;Why...is that?&quot;<span class=\"pg\">p.228<\/span><\/li><li class=\"q spoken\">&quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — arranged a covert meeting, tries to read Shiraishi through emphases and emphasized names, and aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Demands her cooperation/intelligence; is refused, and warns her of consequences if expelled.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is working against him; refers to him as &quot;Ayanokouji-senpai.&quot;<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I am from that side.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That if I am expelled before Ayanokouji-senpai&#x27;s fate is decided... things may very well head in a direction that Shirogane-sensei would not desire.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Reveals she is aligned with his faction (&quot;that side&quot;/&quot;superiors&quot;).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Cites &quot;Shirogane-sensei&quot; in her warning — a name tied to her past (not on the roster).<span class=\"pg\">p.230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p211-1\">← Before: Ch.7 — depth read: Nanase works the White Room angle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p226-1\">→ After: Nanase&#x27;s secret meeting: asking Shiraishi to expel Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p226-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka ayanokouji-kiyotaka tsukishiro hashimoto-masayoshi morishita-ai nanase-tsubasa","q":"nanase tsubasa nanase s secret meeting  asking shiraishi to expel ayanokoji sits back to back with shiraishi in a quiet restaurant  having contacted her in violation of the rules   are you really sure this was the right place to meet   it s true that it s easier to talk since there are few customers  but on the flip side  that means we inevitably stand out   i want to get ayanokouji senpai expelled  as soon as possible  and at a time he can t predict   then why have you started to close the distance now   i will take action while ayanokouji senpai is still within reach   at least give me some information  please  just disclose the names of your associates  cautious and probing   uses a back to back meeting  deliberately emphasizes  nishikawa  to read shiraishi s reaction  admits carelessness with the second phone  and grows impatient in her goal to expel ayanokoji  aligns herself with tsukishiro s anti ayanokoji faction  tries to recruit her  refused  but leaves with a warning about shirogane  wants him expelled as soon as possible  her  superior  in the anti ayanokoji faction  recorded via shiraishi s line  shiraishi silenced him after he witnessed nanase s second phone  likewise silenced","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p226-1\"><h3><span class=\"ttl\">Nanase&#x27;s secret meeting: asking Shiraishi to expel Ayanokōji<\/span><span class=\"meta\">Y3V2 · p.226–230<\/span><\/h3><p class=\"setup\">Sits back-to-back with Shiraishi in a quiet restaurant, having contacted her in violation of the rules.<\/p><p class=\"with\">with <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Are you really sure this was the right place to meet?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\">&quot;It&#x27;s true that it&#x27;s easier to talk since there are few customers, but on the flip side, that means we inevitably stand out.&quot;<span class=\"pg\">p.227<\/span><\/li><li class=\"q spoken\">&quot;I want to get Ayanokouji-senpai expelled. As soon as possible, and at a time he can&#x27;t predict.&quot;<span class=\"pg\">p.228<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I will take action while Ayanokouji-senpai is still within reach.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — uses a back-to-back meeting, deliberately emphasizes &quot;Nishikawa&quot; to read Shiraishi&#x27;s reaction, admits carelessness with the second phone, and grows impatient in her goal to expel Ayanokōji; aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Tries to recruit her; refused, but leaves with a warning about Shirogane.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Wants him expelled as soon as possible.<span class=\"pg\">p.228–229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Her &quot;superior&quot; in the anti-Ayanokōji faction (recorded via Shiraishi&#x27;s line).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Shiraishi silenced him after he witnessed Nanase&#x27;s second phone.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Likewise silenced.<span class=\"pg\">p.228<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p223-1\">← Before: Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"}];
